--

CREATE FUNCTION audit.audit_table(target_table regclass, audit_rows BIT, audit_query_text BIT, ignored_cols NVARCHAR(MAX)[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  stm_targets NVARCHAR(MAX) = 'INSERT OR UPDATE OR DELETE OR TRUNCATE'
  _q_txt NVARCHAR(MAX)
  _ignored_cols_snip NVARCHAR(MAX) = ''
BEGIN
    EXECUTE 'DROP TRIGGER IF EXISTS audit_trigger_row ON ' || target_table(MAX)
    EXECUTE 'DROP TRIGGER IF EXISTS audit_trigger_stm ON ' || target_table(MAX)
    IF audit_rows THEN
        IF array_length(ignored_cols,1) > 0 THEN
            _ignored_cols_snip = ', ' || quote_literal(ignored_cols)
        END IF
        _q_txt = 'CREATE TRIGGER audit_trigger_row AFTER INSERT OR UPDATE OR DELETE ON ' || 
                 target_table(MAX) || 
                 ' FOR EACH ROW EXECUTE PROCEDURE audit.if_modified_func(' ||
                 quote_literal(audit_query_text) || _ignored_cols_snip || ');'
        RAISE NOTICE '%',_q_txt
        EXECUTE _q_txt
        stm_targets = 'TRUNCATE'
    ELSE
    END IF
    _q_txt = 'CREATE TRIGGER audit_trigger_stm AFTER ' || stm_targets || ' ON ' ||
             target_table(MAX) ||
             ' FOR EACH STATEMENT EXECUTE PROCEDURE audit.if_modified_func('||
             quote_literal(audit_query_text) || ');'
    RAISE NOTICE '%',_q_txt
    EXECUTE _q_txt
END
$$
