COMMENT ON FUNCTION audit.audit_table(target_table regclass, audit_rows BIT, audit_query_text BIT, ignored_cols NVARCHAR(MAX)[]) IS '
ADD auditing support TO a TABLE.
 
Arguments:
   target_table:     TABLE name, schema qualified IF NOT ON search_path
   audit_rows:       Record each row CHANGE, OR only audit at a statement level
   audit_query_text: Record the NVARCHAR(MAX) of the client query that triggered the audit event?
   ignored_cols:     COLUMNS TO exclude FROM UPDATE diffs, IGNORE updates that CHANGE only ignored cols.
'
--
-- Name: if_modified_func(); Type: FUNCTION; Schema: audit; Owner: postgres
--

CREATE FUNCTION audit.if_modified_func() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    audit_row audit.logged_action
    include_values BIT
    log_diffs BIT
    h_old hstore
    h_new hstore
    excluded_cols NVARCHAR(MAX)[] = ARRAY[](MAX)[]
BEGIN
    IF TG_WHEN <> 'AFTER' THEN
        RAISE EXCEPTION 'audit.if_modified_func() may only run as an AFTER trigger'
    END IF
    audit_row = ROW(
        NEXTVAL('audit.logged_action_id_seq'), -- id
        TG_TABLE_SCHEMA(MAX),                        -- schema_name
        TG_TABLE_NAME(MAX),                          -- table_name
        --TG_RELID,                                     -- relation OID for much quicker searches
        audit.null_prone_integer_setting_get('practice_director.user_id'),   -- use custom GUC parameter to provide practice_director_user_id
        audit.null_prone_integer_setting_get('practice_director.patient_id'),   -- use custom GUC parameter to provide practice_director_patient_id
        current_timestamp,                            -- action_tstamp_tx
        --statement_timestamp(),                        -- action_tstamp_stm
        --clock_timestamp(),                            -- action_tstamp_clk
       --txid_current(),                               -- transaction ID
        (SELECT setting FROM pg_settings WHERE name = 'application_name'),
        --inet_client_addr(),                           -- client_addr
        --inet_client_port(),                           -- client_port
        current_query(),                              -- top-level query or queries (if multistatement) from client
        substring(TG_OP,1,1),                         -- action
        NULL, NULL,                                   -- row_data, changed_fields
        'f',                                           -- statement_only
        (select max(id) from audit.logged_action), -- previously seen id at time of log insert.
        null,                                      -- row hash
        null                                      -- previous row hash
        )
    IF NOT TG_ARGV[0]'f'.client_query = NULL
    END IF
    IF TG_ARGV[1] IS NOT NULL THEN
        excluded_cols = TG_ARGV[1](MAX)[]
    END IF
    IF (TG_OP = 'UPDATE' AND TG_LEVEL = 'ROW') THEN
        audit_row.row_data = hstore(OLD.*)
        audit_row.changed_fields =  (hstore(NEW.*) - audit_row.row_data) - excluded_cols
        IF audit_row.changed_fields = hstore('') THEN
            -- All changed fields are ignored. Skip this update.
            RETURN NULL
        END IF
    ELSIF (TG_OP = 'DELETE' AND TG_LEVEL = 'ROW') THEN
        audit_row.row_data = hstore(OLD.*) - excluded_cols
    ELSIF (TG_OP = 'INSERT' AND TG_LEVEL = 'ROW') THEN
        audit_row.row_data = hstore(NEW.*) - excluded_cols
    ELSIF (TG_LEVEL = 'STATEMENT' AND TG_OP IN ('INSERT','UPDATE','DELETE','TRUNCATE')) THEN
        audit_row.statement_only = 't'
    ELSE
        RAISE EXCEPTION '[audit.if_modified_func] - Trigger func added as trigger for unhandled case: %, %',TG_OP, TG_LEVEL
        RETURN NULL
    END IF
    INSERT INTO audit.logged_action VALUES (audit_row.*)
    RETURN NULL
END
$$
ALTER FUNCTION audit.if_modified_func() OWNER TO postgres
--
-- Name: FUNCTION if_modified_func(); Type: COMMENT; Schema: audit; Owner: postgres
--

COMMENT ON FUNCTION audit.if_modified_func() IS '
Track changes TO a TABLE at the statement AND/OR row level.

Optional parameters TO TRIGGER IN CREATE TRIGGER call:

param 0: BIT, whether TO log the query NVARCHAR(MAX). DEFAULT ''t''.

param 1: NVARCHAR(MAX)[], COLUMNS TO IGNORE IN updates. DEFAULT [].

         Updates TO ignored cols are omitted FROM changed_fields.

         Updates WITH only ignored cols changed are NOT inserted
         INTO the audit log.

         Almost ALL the processing work IS still done FOR updates
         that ignored. IF you need TO save the LOAD, you need TO USE
         WHEN clause ON the TRIGGER instead.

         No warning OR error IS issued IF ignored_cols contains COLUMNS
         that do NOT exist IN the target TABLE. This lets you specify
         a standard SET of ignored COLUMNS.

There IS no parameter TO disable logging of VALUES. ADD this TRIGGER AS
a ''FOR EACH STATEMENT'' rather than ''FOR EACH ROW'' TRIGGER IF you do NOT
want TO log row VALUES.

Note that the user name logged IS the login role FOR the session. The audit TRIGGER
cannot obtain the active role because it IS reset BY the SECURITY DEFINER invocation
of the audit TRIGGER its self.
'
--
-- Name: log_add_update_delete(integer, integer, NVARCHAR(MAX), NVARCHAR(MAX), NVARCHAR(MAX), NVARCHAR(MAX), integer); Type: FUNCTION; Schema: audit; Owner: postgres
--

CREATE FUNCTION audit.log_add_update_delete(user_id integer, patient_id integer, action NVARCHAR(MAX), description NVARCHAR(MAX), appver NVARCHAR(MAX), table_name NVARCHAR(MAX), table_id integer) RETURNS BIT
    LANGUAGE plpgsql
    AS $_$
DECLARE
	c bigint
  servver NVARCHAR(MAX)
  usr int
BEGIN
	-- LOG a query, copy, or print action but only record it once per unique set of paramaters in addition to 'current_timestamp'. 
	-- The intention is to keep from poluting the log with loads of reduent stuff.
	servver = $5
	IF servver= ''(MAX) or servver = '0.0.0.0'(MAX) THEN
	  select setting into servver from pg_settings where name like 'server_version' 
	END IF
	usr = $1
	IF usr = 0 THEN
	 usr = (SELECT nullif(cast(nullif(trim(current_setting('practice_director.user_id')), '' )  as int), -1))
	END IF
	IF $3 = 'I'(MAX) or $3 = 'U'(MAX) or $3 = 'D'(MAX) THEN
		select COALESCE (count(id), 0) into c from audit.logged_action_high_level l where  l.table_name IS NOT DISTINCT FROM $6 and l.practice_director_user_id IS NOT DISTINCT FROM usr and l.practice_director_patient_id IS NOT DISTINCT FROM $2 and l.table_id IS NOT DISTINCT FROM $7 and l.action IS NOT DISTINCT FROM $3 and l.action_tstamp_tx IS NOT DISTINCT FROM current_timestamp
		IF c = 0 THEN
			-- Suff empty strings tinto schema_name and table_name as the type of logging we are doing here is more high level then recording what has been changed.
			insert into audit.logged_action_high_level  (id, schema_name, table_name, practice_director_user_id, practice_director_patient_id, table_id, action_tstamp_tx, application_name, application_ver, client_action, action, prev_id) values (NEXTVAL('audit.logged_action_high_level_id_seq'), '', $6, $1, $2, $7, current_timestamp, '', servver, $4, $3, (select max(id) from audit.logged_action_high_level))
		END IF
		RETURN c = 0
	END IF
	RETURN false
END
$_$
