CREATE FUNCTION audit.null_prone_integer_setting_get(propertyname NVARCHAR(MAX)) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  query_value integer
BEGIN
  query_value := (SELECT nullif(cast(nullif(trim(current_setting(propertyName)), '' )  as int), -1))
  return query_value
  EXCEPTION
  WHEN OTHERS THEN
    RETURN null
END
$$
