-- Name: add_audit_log_triggers_to_tables(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.add_audit_log_triggers_to_tables() RETURNS void
    LANGUAGE plpgsql
    AS $$ 
DECLARE
	t NVARCHAR(MAX)
BEGIN
	FOR t IN  select table_name from information_schema.tables where table_type = 'BASE TABLE' and table_schema = 'public' and not (table_name(MAX) = 'logged_action' or table_name(MAX) ilike 'jms_%' or table_name(MAX) ilike 'timers') 
	LOOP
		PERFORM audit.audit_table(t)
	END LOOP
END
$$
