--
-- Name: add_index_to_fkey(NVARCHAR(MAX), NVARCHAR(MAX)); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.add_index_to_fkey(schema_name NVARCHAR(MAX), contraint NVARCHAR(MAX)) RETURNS void
    LANGUAGE plpgsql
    AS $_$DECLARE
    functor NVARCHAR(MAX)
BEGIN    
    FOR functor IN 
        select 
        'CREATE INDEX ' || quote_ident(x.constraint_name || '_idx') || ' ON ' || quote_ident(x.schema_name) || '.' || quote_ident(x.table_name) ||' (' || array_to_string(pd_array_agg(quote_ident(x.column_name)), ',') || ')'
        from 
            (
                select
                    vfki.constraint_name,
                    vfki.schema_name,
                    vfki.table_name,
                    vfki.index_name,
                    pd_unnest(vfki.column_name_list) as column_name
                from    
                    view_foriegn_key_indexes as vfki
                where vfki.schema_name = $1 and vfki.constraint_name = $2
        ) as x
        group by x.constraint_name, x.schema_name, x.table_name, x.index_name having x.index_name is null LOOP  
             EXECUTE functor
    END LOOP
END;$_$
