CREATE FUNCTION dbo.add_mission_proc_code() RETURNS integer
    LANGUAGE plpgsql
    AS $$ DECLARE number_of_entries INTEGER; BEGIN SELECT count(*) INTO number_of_entries FROM procedure_code WHERE procedure_code like 'V2797'; IF number_of_entries <= 0 THEN INSERT INTO procedure_code (id,default_pos_id, default_tos_id, procedure_code, procedure_name, procedure_type, procedure_country, procedure_region, procedure_codeset, revenue_type_id) VALUES (nextVal('procedure_code_id_seq'), 8, 2, 'V2797', 'Vision supply, accessory and/or service component of another hcpcs vision code', 'MED', null, null, 'C', null ); END IF; return 1; END; $$
