--
-- Name: add_procedure_code(NVARCHAR(MAX), NVARCHAR(MAX), NCHAR(1), integer, integer, NCHAR(1)); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.add_procedure_code(p_procedure_code NVARCHAR(MAX), p_procedure_name NVARCHAR(MAX), p_procedure_type NCHAR(1), p_pos_id integer, p_tos_id integer, p_procedure_codeset NCHAR(1)) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cnt integer
  v_pos_id integer
  v_tos_id integer
  v_procedure_type char(3)
  v_procedure_codeset char(1)
BEGIN
	-- check if there is an existing procedure code
	SELECT count(*) INTO v_cnt FROM procedure_code WHERE procedure_code = p_procedure_code
	-- if there is not an existing procedure code, then add
	IF v_cnt = 0 THEN
		-- get default values
		IF p_pos_id IS NULL THEN
			SELECT MAX(id) INTO v_pos_id FROM place_of_service WHERE pos_code = '11'
		ELSE
			v_pos_id := p_pos_id
		END IF
		IF p_tos_id IS NULL THEN
			SELECT MAX(id) INTO v_tos_id FROM type_of_service WHERE tos_code = '1'
		ELSE
			v_tos_id := p_tos_id
		END IF
		IF p_procedure_type IS NULL THEN
			v_procedure_type := 'MED'
		ELSE
			IF p_procedure_type <> 'MED' AND p_procedure_type <> 'NON' THEN
				v_procedure_type = 'MED'
			ELSE
				v_procedure_type := p_procedure_type
			END IF
		END IF
		IF p_procedure_codeset IS NULL THEN
			v_procedure_codeset := 'C'
		ELSE
			v_procedure_codeset := p_procedure_codeset
		END IF
		-- add the procedure code
		INSERT INTO procedure_code (id, procedure_code, procedure_name, default_pos_id, default_tos_id, procedure_type, procedure_codeset)
		  values (nextVal('procedure_code_id_seq'),
			  p_procedure_code,
			  p_procedure_name,
			  v_pos_id,
			  v_tos_id,
			  v_procedure_type,
			  v_procedure_codeset)
	END IF
END
$$
ALTER FUNCTION dbo.add_procedure_code(p_procedure_code NVARCHAR(MAX), p_procedure_name NVARCHAR(MAX), p_procedure_type NCHAR(1), p_pos_id integer, p_tos_id integer, p_procedure_codeset NCHAR(1)) OWNER TO postgres
