--
-- Name: bmi_nqf_421(numeric, numeric, BIT); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.bmi_nqf_421(height numeric, weight numeric, havemetric BIT) RETURNS numeric
    LANGUAGE plpgsql STRICT
    AS $$       
DECLARE 
	height2 numeric
	weight2 numeric
	bmi numeric
	inchesToCentimeters numeric
	poundsToKilograms numeric
BEGIN
	inchesToCentimeters := 2.54
	poundsToKilograms := 0.45359237
	IF haveMetric THEN
		height2 := height / 100
		weight2 := weight
    ELSE
    	height2 := (height * inchesToCentimeters) / 100
    	weight2 := weight * poundsToKilograms
    END IF
    IF height2 <> 0 THEN
    	bmi := weight2 / (height2 * height2)
    	RETURN bmi
    ELSE
    	RETURN NULL
    END IF
END
$$
ALTER FUNCTION dbo.bmi_nqf_421(height numeric, weight numeric, havemetric BIT) OWNER TO postgres
