--
-- Name: compute_patient_final_balance(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.compute_patient_final_balance(p_id integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$

DECLARE
  pat_id alias for $1; -- the patient
  debt record; -- credit or prepayment

  patFinalBalance numeric
BEGIN
-- we need to look at the patients un resolved invoices, sum them up and update the cached value
  patFinalBalance:=(Select patient_balance from patient where id = pat_id)
  -- For each invoice line of the given invoice id
  FOR debt IN (SELECT * from prepayment as pp where pp.patient = pat_id AND pp.remaining > 0 AND pp.reversal_of is null AND (Select count(ppO.prepayment_id) from prepayment as ppO where ppO.reversal_of = pp.prepayment_id ) =0) LOOP
    patFinalBalance :=patFinalBalance - debt.remaining
  END LOOP
    FOR debt IN (SELECT * from credit as pp where pp.patient = pat_id AND pp.remaining > 0 AND pp.reversal_of is null AND (Select count(ppO.credit_id) from credit as ppO where ppO.reversal_of = pp.credit_id ) =0) LOOP
    patFinalBalance :=patFinalBalance - debt.remaining
  END LOOP
  return patFinalBalance
END
$_$
ALTER FUNCTION dbo.compute_patient_final_balance(p_id integer) OWNER TO postgres
