-- Name: delete_exam(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.delete_exam(p_exam_id integer) RETURNS BIT
    LANGUAGE plpgsql
    AS $$
DECLARE
  hist_id integer
  med_id integer
  option_id integer
  row RECORD
BEGIN
  SELECT id INTO hist_id FROM exam_case_history hist WHERE hist.exam_id = p_exam_id
  -- delete exam_chief_complaints
  DELETE FROM exam_chief_complaints WHERE exam_case_history_id = hist_id
  -- delete exam_case_history
  DELETE FROM exam_case_history WHERE exam_id = p_exam_id
  SELECT id INTO med_id FROM exam_medical_decision med WHERE med.exam_id = p_exam_id
  -- delete from exam_diagnosis_and_management_options_xref
  FOR row IN SELECT * FROM exam_diagnosis_and_management_options WHERE exam_medical_decision_id = med_id LOOP
    DELETE FROM exam_diagnosis_and_management_options_xref WHERE exam_diagnosis_and_management_options_id = row.id
  END LOOP
  -- delete from exam_diagnosis_and_management_options
  DELETE FROM exam_diagnosis_and_management_options WHERE exam_medical_decision_id = med_id
  -- delete from exam_medical_decision_code
  DELETE FROM exam_medical_decision_code WHERE exam_medical_decision_id = med_id
  -- delete from health_concerns
  DELETE FROM health_concern WHERE emd_id = med_id
  -- delete from health_concern_observations
  DELETE FROM health_concern_observation WHERE emd_id = med_id
  -- delete exam_medical_decision
  DELETE FROM exam_medical_decision WHERE exam_id = p_exam_id
  -- delete exam_review_of_systems
  DELETE FROM exam_review_of_systems WHERE exam_id = p_exam_id
  -- delete cl_prescription
  DELETE FROM cl_prescription WHERE exam_id = p_exam_id
  -- delete spec_prescription
  DELETE FROM spec_prescription where exam_id = p_exam_id
  -- delete document_management
  DELETE FROM document_management WHERE exam_id  = p_exam_id
  -- delete image_management
  DELETE FROM patient_image WHERE exam_id = p_exam_id
  -- delete exam_change_log
  DELETE FROM exam_change_log WHERE exam_id = p_exam_id
  -- delete amendments
  DELETE FROM exam_amendment WHERE exam_id = p_exam_id
  -- delete the exam
  DELETE FROM exam WHERE id = p_exam_id
  return true
END
$$
ALTER FUNCTION dbo.delete_exam(p_exam_id integer) OWNER TO postgres
