-- Name: determinecodesystem(NVARCHAR(MAX)); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.determinecodesystem(code NVARCHAR(MAX)) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
	ICD9 integer := 0
	ICD10 integer := 1
BEGIN
	IF char_length(upper(regexp_replace($1, '\.', ''))) <=5 THEN
		IF array_length(regexp_matches($1, '^[evEV0-9].*'), 1) >0 THEN
			return ICD9
		END IF
	END IF
	return ICD10
END
$_$
ALTER FUNCTION dbo.determinecodesystem(code NVARCHAR(MAX)) OWNER TO postgres
