CREATE FUNCTION dbo.ecpid() RETURNS NVARCHAR(MAX)
    LANGUAGE plpgsql
    AS $$

DECLARE
  serverId NVARCHAR(MAX)
  ch NVARCHAR(MAX)
  ecpId NVARCHAR(MAX)
BEGIN

  select pref_value into serverId from preferences where pref_key = 'rabbitmq.serverid'
  FOREACH ch IN ARRAY regexp_split_to_array(serverId, '')
  LOOP

    select concat(ecpId, ASCII(ch)) into ecpId
  END LOOP
  return ecpId
END
$$
