--

CREATE FUNCTION dbo.fixphonenumber() RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
   contact_infos record
begin
   for contact_infos in select * from contact_info order by id loop /* loop thru all contact infos*/
	update contact_info set value = (replace(contact_infos.value, '--', '-')) where id = contact_infos.id
   end loop
   return 1
end
$$
