-- Name: get_all_nqf_measures(date, date, NVARCHAR(MAX)[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_all_nqf_measures(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[]) RETURNS SETOF dbo.pqri_measure
    LANGUAGE plpgsql
    AS $_$DECLARE
    reporting_period_start ALIAS FOR $1
    reporting_period_end ALIAS FOR $2
    npis ALIAS FOR $3
    function_name RECORD
    pqri_data RECORD
    functor NVARCHAR(MAX)
BEGIN
    IF (reporting_period_start is null or reporting_period_end is null or npis is null) THEN
        RAISE EXCEPTION 'null values in any of the paramaters is not allowed.'
    END IF
    FOR function_name IN SELECT * FROM pqri_function_names LOOP
            functor := 'select * from ' || quote_ident(function_name.routine_schema) || '.' || quote_ident(function_name.routine_name) || '(' || quote_literal(reporting_period_start(MAX)) || ' ,' || quote_literal(reporting_period_end(MAX)) || ' ,' || quote_literal(textin(array_out(npis))) || '(MAX)[] )'
        FOR pqri_data IN EXECUTE functor LOOP
            RETURN NEXT pqri_data
        END LOOP
    END LOOP
END;$_$
ALTER FUNCTION dbo.get_all_nqf_measures(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[]) OWNER TO postgres
--
-- Name: get_all_nqf_measures(date, date, NVARCHAR(MAX)[], integer, integer, NVARCHAR(MAX)[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_all_nqf_measures(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], patient_id integer, exam_id integer, alert_ids NVARCHAR(MAX)[]) RETURNS SETOF dbo.pqri_measure
    LANGUAGE plpgsql
    AS $_$DECLARE
    reporting_period_start ALIAS FOR $1
    reporting_period_end ALIAS FOR $2
    npis ALIAS FOR $3
    patient_id ALIAS FOR $4
    exam_id ALIAS FOR $5
    alert_ids ALIAS FOR $6
    function_name RECORD
    pqri_data RECORD
    functor NVARCHAR(MAX)
BEGIN
    IF (reporting_period_start is null or reporting_period_end is null or npis is null) THEN
        RAISE EXCEPTION 'null value in reporting_period_start, reporting_period_end or npis parameter is not allowed.'
    END IF
    FOR function_name IN SELECT * FROM pqri_function_names LOOP
    	IF patient_id IS NULL AND exam_id IS NULL and alert_ids IS NULL THEN	
    		functor := 'select * from ' || quote_ident(function_name.routine_schema) || '.' || quote_ident(function_name.routine_name) || '(' || quote_literal(reporting_period_start(MAX)) || ' ,' || quote_literal(reporting_period_end(MAX)) || ' ,' || quote_literal(textin(array_out(npis))) || '(MAX)[]' || ' , null, null )'
    	ELSE
    	    IF substring(function_name.routine_name from 'nqf_(.*)(?:(_.*){2})') = ANY (alert_ids) OR
			   substring(function_name.routine_name from 'nqf_(.*)(?:(_.*){1})') = ANY (alert_ids) OR
			   substring(function_name.routine_name from 'nqf_(.*)(?:$)') = ANY (alert_ids) THEN
    	    	functor := 'select * from ' || quote_ident(function_name.routine_schema) || '.' || quote_ident(function_name.routine_name) || '(' || quote_literal(reporting_period_start(MAX)) || ' ,' || quote_literal(reporting_period_end(MAX)) || ' ,' || quote_literal(textin(array_out(npis))) || '(MAX)[]' || ' ,' || quote_literal(patient_id(MAX)) || ' ,' || quote_literal(exam_id(MAX)) || ' )'
    	    ELSE
				functor := NULL
    	    END IF
		END IF
		IF functor IS NOT NULL THEN
        	FOR pqri_data IN EXECUTE functor LOOP
         	   RETURN NEXT pqri_data
       	 	END LOOP
        END IF
    END LOOP
END;$_$
ALTER FUNCTION dbo.get_all_nqf_measures(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], patient_id integer, exam_id integer, alert_ids NVARCHAR(MAX)[]) OWNER TO postgres
--
-- Name: get_available_exams(date, date, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_available_exams(series_start date, series_end date, work_office integer, provider integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE
	total_exams integer := 0; -- function result
	default_exams integer := 0
	recurring_record RECORD
	override_record RECORD
	work_office_iteration integer
	provider_iteration integer
	aer_rows integer
	aeo_rows integer
BEGIN
	-- check for null return
	aer_rows = COUNT(*) FROM available_exams_recurring
	aeo_rows = COUNT(*) FROM available_exams_override
	IF aer_rows = 0 AND aeo_rows = 0 THEN
		RETURN NULL
	END IF
	-- create temporary table with date range corresponding to input parameters,
	-- initialized to 0 available exams
	CREATE TEMPORARY TABLE date_series ON COMMIT DROP AS
		SELECT generate_series(series_start, series_end, '1 day') AS date_row,
		0 AS available_exams ORDER BY date_row
	--RAISE NOTICE '% days in series.', series_end - series_start + 1
	-- loop through applicable work offices
	FOR work_office_iteration IN
			SELECT id FROM work_office wo WHERE (wo.is_deleted IS NULL OR NOT wo.is_deleted)
			ORDER BY id LOOP
		IF work_office > 0 AND work_office_iteration <> work_office THEN
			CONTINUE
		END IF
		-- loop through applicable providers
		FOR provider_iteration IN
					SELECT DISTINCT ps.doctor_provider_id AS id FROM provider_schedule ps
					INNER JOIN doctor_provider dp ON ps.doctor_provider_id = dp.id
					INNER JOIN work_office wo ON ps.work_office_id = wo.id
					WHERE dp.is_active AND ps.work_office_id = work_office_iteration
					ORDER BY id LOOP
			IF provider > 0 AND provider_iteration <> provider THEN
				CONTINUE
			END IF
			-- clear available exams across date range
			UPDATE date_series SET available_exams = 0
			-- apply default and other recurring from table available_exams_recurring
			FOR recurring_record IN SELECT * FROM available_exams_recurring
					ORDER BY is_default DESC, is_all_prov DESC, is_all_wo DESC, day_of_week LOOP
				IF recurring_record.is_default THEN
					-- recurring default
					UPDATE date_series SET available_exams = recurring_record.available_exams
							WHERE
								(date_part('dow', date_row) = recurring_record.day_of_week) AND
								(
									(NOT(recurring_record.is_alternating)) OR
									((CAST(date_row AS date) - CAST(recurring_record.start_date AS date)) % 14 = 0)
								) AND
								(
									(recurring_record.is_all_wo) OR
									--(work_office = -1) OR
									(recurring_record.work_office_id = work_office_iteration)
								) AND
								(
									(recurring_record.is_all_prov) OR
									--(provider = -1) OR
									(recurring_record.doctor_id = provider_iteration)
								)
				ELSE
					-- recurring override (date range)
					UPDATE date_series SET available_exams = recurring_record.available_exams
							WHERE
								(date_part('dow', date_row) = recurring_record.day_of_week) AND
								(
									(NOT(recurring_record.is_alternating)) OR
									((CAST(date_row AS date) - CAST(recurring_record.start_date AS date)) % 14 = 0)
								) AND
								((CAST(date_row AS date), CAST(date_row AS date)) OVERLAPS
										(CAST(recurring_record.start_date AS date), CAST(recurring_record.end_date + 1 AS date))
								) AND
								(
									(recurring_record.is_all_wo) OR
									--(work_office = -1) OR
									(recurring_record.work_office_id = work_office_iteration)
								) AND
								(
									(recurring_record.is_all_prov) OR
									--(provider = -1) OR
									(recurring_record.doctor_id = provider_iteration)
								)
				END IF
			END LOOP; -- recurring_record

			-- apply overrides from table available_exams_override
			FOR override_record IN SELECT * FROM available_exams_override
					WHERE (CAST(start_date AS date), CAST(end_date AS date)) OVERLAPS
								(series_start, series_end)
					ORDER BY is_all_prov DESC, is_all_wo DESC, start_date, id LOOP
				--RAISE NOTICE 'Override %', override_record.id
				UPDATE date_series SET available_exams = override_record.available_exams
						WHERE
							((CAST(date_row AS date), CAST(date_row AS date)) OVERLAPS
									(CAST(override_record.start_date AS date), CAST(override_record.end_date + 1 AS date))
							) AND
							(
								(override_record.is_all_wo) OR
								--(work_office = -1) OR
								(override_record.work_office_id = work_office_iteration)
							) AND
							(
								(override_record.is_all_prov) OR
								--(provider = -1) OR
								(override_record.doctor_id = provider_iteration)
							)
			END LOOP; -- override_record

			-- add sum of available exams across date range
			total_exams = total_exams + sum(available_exams) FROM date_series
		END LOOP; -- provider_iteration
	END LOOP; -- work_office_iteration
	
	RETURN total_exams
END
$$
ALTER FUNCTION dbo.get_available_exams(series_start date, series_end date, work_office integer, provider integer) OWNER TO postgres
--
-- Name: get_business_day_interval(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_business_day_interval(period_start date, period_end date) RETURNS integer
    LANGUAGE plpgsql
    AS $$

/**********

PL/pgSQL function get_business_day_interval(date, date)

Created: 05/2014
Version: 1.1
Author: Phil Belyaev

Given input parameters for a reporting period start and end dates, 
calculate and return the count of business days elapsed.

CHANGE LOG
1.1:	For intervals ending on a nonbusiness day, extend the 
		interval to the next business day. For example, for an
		interval from a Friday to the next day (Saturday),
		return 1.
1.0		Original version

*********/

DECLARE
	raw_interval integer
	start_isodow integer
	end_isodow integer
	n1 integer
	n2 integer
	nbd integer
BEGIN
	
	raw_interval := period_end - period_start
	start_isodow := EXTRACT(ISODOW FROM period_start)
	end_isodow := EXTRACT(ISODOW FROM period_end)
	IF end_isodow > 5 THEN
		-- interval ends on Saturday or Sunday
		raw_interval := raw_interval + (8 - end_isodow)
	END IF
	n1 := ((start_isodow + 1) % 7) + raw_interval
	n2 := (start_isodow % 7) + raw_interval
	nbd := div(n1, 7) + div(n2, 7)
	RETURN GREATEST(raw_interval - nbd, 0)
END
$$
ALTER FUNCTION dbo.get_business_day_interval(period_start date, period_end date) OWNER TO postgres
