--
-- Name: get_contact_number(integer, NVARCHAR(MAX), NVARCHAR(MAX)); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_contact_number(p_patient_id integer, p_type NVARCHAR(MAX), p_subtype NVARCHAR(MAX)) RETURNS NVARCHAR(MAX)
    LANGUAGE plpgsql
    AS $$
DECLARE 
	v_contact_number NVARCHAR(MAX)
	v_extended_value NVARCHAR(MAX)
BEGIN

	-- if the subtype is null, then dont include in the query
	IF (p_subtype IS NULL) THEN
		SELECT  ci.value, ci.extended_value from patient p inner join patient_contact_info_xref x on p.id = x.patient_id inner join contact_info ci on x.contact_info_id = ci.id 
			WHERE p.id = p_patient_id AND ci.type = p_type
		INTO 
			v_contact_number, v_extended_value
	ELSE 
		SELECT  ci.value, ci.extended_value from patient p inner join patient_contact_info_xref x on p.id = x.patient_id inner join contact_info ci on x.contact_info_id = ci.id 
			WHERE p.id = p_patient_id AND ci.type = p_type AND ci.sub_type = p_subtype
		INTO 
			v_contact_number, v_extended_value
	END IF
	-- append the extend value, type is phone and subtype is phone_work
	IF (p_type = 'phone' AND p_subtype = 'phone_work' AND v_extended_value IS NOT NULL) THEN
		v_contact_number = v_contact_number || '  ' || v_extended_value
	END IF
	RETURN v_contact_number
END
$$
ALTER FUNCTION dbo.get_contact_number(p_patient_id integer, p_type NVARCHAR(MAX), p_subtype NVARCHAR(MAX)) OWNER TO postgres
--
-- Name: get_electronic_medication_count_rpp(date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_electronic_medication_count_rpp(period_start date, period_end date, provider integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

