ALTER FUNCTION dbo.get_measure_denominator_patients_education_provider_2014(measure_id integer, period_start date, period_end date, provider integer, tin NVARCHAR(MAX)) OWNER TO postgres
--
-- Name: get_measure_numerator_2014(integer, date, date, integer, NVARCHAR(MAX)); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_measure_numerator_2014(measure_id integer, period_start date, period_end date, provider integer, tin NVARCHAR(MAX)) RETURNS integer
    LANGUAGE plpgsql
    AS $$
/**********
PL/pgSQL function get_measure_numerator_2014(integer, date, date, integer)

Created: 05/2014
Version: 1.8
Author: Phil Belyaev

Given input parameters for a measure ID, reporting period start and end dates, and provider ID,
calculate and return the numerator for the Meaningful Use Report, in accordance with the
2014 Test Procedure for 170.314(g)(1) Automated numerator recording &
170.314(g)(2) Automated measure calculation.

Call subordinate functions for individual measure numerator calculations.

CHANGE LOG
1.13    Added M2017_8_1 for MOD_STAGE_2_2017_OBJECTIVE_8_VDT_ACCESS and M2017_8_2 for MOD_STAGE_2_2017_OBJECTIVE_8_VDT_USE.
1.12	Support TIN (Tax ID Number) parameter to use in queries along with provider id. (tcp 2/12/2018)
		Note for numerator calculation, patient-based ACI measures require transitivity across TINs
		so they will not use TIN as a condition:
			M2018_ACI_PEA_2,
			M2018_ACI_TRANS_PSE_1,
			M2018_ACI_PEA_1,
			M2018_ACI_TRANS_PEA_1,
			M2018_ACI_CCTPE_1,
			M2018_ACI_TRANS_PEA_2,
			M2018_ACI_CCTPE_2,
			M2018_ACI_CCTPE_3

		Added M2018_ACI_EP_1 for ACI_2018_E_PRESCRIBING
		Added M2018_ACI_HIE_1 for ACI_2018_HIE_SEND_SOC
		Added M2018_ACI_HIE_2 for ACI_2018_HIE_ACCEPT_SOC
		Added M2018_ACI_HIE_3 for ACI_2018_HIE_RECONCILIATION
		Added M2018_ACI_PEA_2 for ACI_2018_PEA_PATIENT_EDUCATION
		Added M2018_ACI_PEA_1 for ACI_2018_PEA_VDT_AND_API_ACCESS
		Added M2018_ACI_CCTPE_for 1 ACI_2018_CC_VDT_OR_API_USE
		Added M2018_ACI_CCTPE_2 for ACI_2018_CC_SECURE_MSG
		Added M2018_ACI_CCTPE_3 for ACI_2018_CC_PATIENT_HEALTH_DATA
		Added M2018_ACI_TRANS_PSE_1 for ACI_TRANSITION_2018_PATIENT_SPECIFIC_EDUCATION
		Added M2018_ACI_TRANS_PEA_1 for ACI_TRANSITION_2018_PROVIDE_PATIENT_ACCESS
		Added M2018_ACI_TRANS_PEA_2 for ACI_TRANSITION_2018_VIEW_DOWNLOAD_TRANSMIT
1.11	Added M2018_5_1_ID for MeaningfulUseID.STAGE_3_OBJECTIVE_5_VDT_AND_API_ACCESS. (tcp 2/6/2018)
		Added M2018_5_2_ID for MeaningfulUseID.STAGE_3_OBJECTIVE_5_PATIENT_EDUC_ELEC_ACCESS.
		Added M2018_6_1_ID for MeaningfulUseID.STAGE_3_OBJECTIVE_6_VDT_OR_API_USE.
1.10	Added M2018_6_3_ID for MeaningfulUseID.STAGE_3_OBJECTIVE_6_PATIENT_HEALTH_DATA. (tcp 1/29/2018)
1.9		Added M2018_7_2_ID for MeaningfulUseID.STAGE_3_OBJECTIVE_7_SOC_INCORPORATION. (tcp 1/25/2018)
1.8     Added M2016_9_ID for MeaningfulUseID.MOD_STAGE_2_2016_OBJECTIVE_9_SECURE_MSG. (tcp 3/10/2016)
1.7		Adjust Vital Signs numerators (M2014_10_1_BP_OOS_ID, M2014_10_1_HW_OOS_ID, M2014_10_1_ID, M2014_10_2_BP_OOS_ID, M2014_10_2_HW_OOS_ID, M2014_10_2_ID) (pb).
1.6		Adjust Electronic Prescribing numerators (M2014_8_1_ID, M2014_8_2_ID) (pb 11/18/2014).
1.5		Changed to support capturing vitals outside the reporting period. tcp 2014-07-30
1.4		Changed to support detection of permissible prescription (and its electronic transmission) (M2014_8_1_ID, M2014_8_2_ID, M2014_8_2_CS_ID) / tcp
1.3		Update Summary of Care numerators (M2014_18_1_ID, M2014_18_2_A_ID, M2014_18_2_B_ID) > validate ccda.
1.2		Update Imaging numerator (M2014_20_2_ID) > radiology images.
1.1		Update several calculations.
1.0		Original version
*********/
DECLARE
	query_result integer; -- function result
	M2014_7_1_ID integer := 25
	M2014_7_1_ALT_ID integer := 26
	M2014_7_2_MED_ID integer := 27
	M2014_7_2_RAD_ID integer := 28
	M2014_7_2_LAB_ID integer := 29
	M2014_8_1_ID integer := 30
	M2014_8_2_ID integer := 32
	M2014_9_ID integer := 33
	M2014_10_1_BP_OOS_ID integer := 34
	M2014_10_1_HW_OOS_ID integer := 35
	M2014_10_1_ID integer := 36
	M2014_10_2_BP_OOS_ID integer := 37
	M2014_10_2_HW_OOS_ID integer := 38
	M2014_10_2_ID integer := 39
	M2014_11_ID integer := 40
	M2014_12_ID integer := 41
	M2014_13_1_ID integer := 42
	M2014_13_2_ID integer := 43
	M2014_14_A_ID integer := 44
	M2014_14_B_ID integer := 45
	M2014_15_1_ID integer := 46
	M2014_15_2_ID integer := 47
	M2014_16_1_ID integer := 48
	M2014_16_2_ID integer := 49
	M2014_17_1_ID integer := 50
	M2014_17_2_ID integer := 51
	M2014_18_1_ID integer := 52
	M2014_18_2_A_ID integer := 53
	M2014_18_2_B_ID integer := 54
	M2014_19_2_ID integer := 55
	M2014_20_2_ID integer := 56
	M2014_21_2_ID integer := 57
	M2014_22_2_ID integer := 58
	M2016_9_ID integer := 100
	M2017_6_1 integer := 119
	M2017_8_1 integer := 121
	M2017_8_2 integer := 122
	M2018_5_1_ID integer := 140
	M2018_5_2_ID integer := 141
	M2018_6_1_ID integer := 142
	M2018_6_3_ID integer := 144
	M2018_7_1_ID integer := 145
	M2018_7_2_ID integer := 146
	M2018_7_3_ID integer := 147
	M2018_ACI_TRANS_PSE_1 integer := 129
 	M2018_ACI_TRANS_PEA_1 integer := 130
 	M2018_ACI_TRANS_PEA_2 integer := 131
 	M2018_ACI_EP_1 integer	:= 150
 	M2018_ACI_HIE_1 integer := 151
 	M2018_ACI_HIE_2 integer := 152
 	M2018_ACI_HIE_3 integer := 153
 	M2018_ACI_PEA_2 integer := 154
 	M2018_ACI_PEA_1 integer := 155
 	M2018_ACI_CCTPE_1 integer := 156
 	M2018_ACI_CCTPE_2 integer := 157
 	M2018_ACI_CCTPE_3 integer := 158
 	M2019_PI_EP integer := 161
 	M2019_PI_SEND_HI integer := 162
    M2019_PI_PEA integer := 163
BEGIN
	CASE measure_id
		WHEN	M2014_7_1_ID THEN
			query_result := get_patient_electronic_medication_count_rpp(period_start, period_end, provider) +
							get_patient_electronic_medication_error_count_rpp(period_start, period_end, provider)
		WHEN	M2014_7_2_RAD_ID THEN
			query_result := get_radiology_order_count_rpp(period_start, period_end, provider)
		WHEN	M2014_7_2_LAB_ID THEN
			query_result := get_lab_order_count_rpp(period_start, period_end, provider)
		WHEN	M2014_7_1_ALT_ID,
				M2014_7_2_MED_ID THEN
			query_result := get_electronic_medication_count_rpp(period_start, period_end, provider) +
							get_electronic_medication_error_count_rpp(period_start, period_end, provider)
		WHEN	M2014_8_1_ID,
				M2014_8_2_ID THEN
			query_result := get_electronic_nonscheduled_sent_count_rpp(period_start, period_end, provider) +
							get_electronic_nonscheduled_sent_error_count_rpp(period_start, period_end, provider)
		WHEN	M2014_9_ID THEN
			query_result := get_patient_demographics_count_rpp(period_start, period_end, provider)
		WHEN	M2014_10_1_BP_OOS_ID,
				M2014_10_2_BP_OOS_ID THEN
			query_result := get_patient_height_weight_count_rppa(period_start, period_end, provider, 0)
		WHEN	M2014_10_1_HW_OOS_ID,
				M2014_10_2_HW_OOS_ID THEN
			query_result := get_patient_blood_pressure_count_rppa(period_start, period_end, provider, 3)
		WHEN	M2014_10_1_ID,
				M2014_10_2_ID THEN
			query_result := get_patient_combined_vitals_count_rpp(period_start, period_end, provider)
		WHEN	M2014_11_ID THEN
			query_result := get_patient_smoking_status_count_rppa(period_start, period_end, provider, 13)
		WHEN	M2014_12_ID THEN
			query_result := get_lab_result_count_rpp(period_start, period_end, provider)
		WHEN	M2014_13_1_ID THEN
			query_result := get_patient_recall_count_565_rpp(period_start, period_end, provider)
		WHEN	M2014_13_2_ID THEN
			query_result := get_patient_recall_count_224_rpp(period_start, period_end, provider)
		/* M2014_14_A_ID implemented externally */
		/* M2014_14_B_ID implemented externally */

		WHEN	M2014_15_1_ID THEN
			query_result := get_exam_csp_count_rppi(period_start, period_end, provider, 3)
		WHEN	M2014_15_2_ID THEN
			query_result := get_exam_csp_count_rppi(period_start, period_end, provider, 1)
		WHEN	M2014_16_1_ID,
				M2014_16_2_ID THEN
			query_result := get_patient_education_count_rpp(period_start, period_end, provider)
		WHEN	M2017_6_1,
				M2018_ACI_TRANS_PSE_1 THEN
			query_result := get_patient_education_provider_count_rpp(period_start, period_end, provider)
		WHEN	M2014_17_1_ID,
				M2014_17_2_ID THEN
			query_result := get_medication_reconciliation_count_rppf(period_start, period_end, provider, true)
		WHEN	M2014_18_1_ID,
				M2014_18_2_A_ID THEN
			query_result := get_soc_outgoing_count_rppef(period_start, period_end, provider, false, true)
		WHEN	M2014_18_2_B_ID THEN
			query_result := get_soc_outgoing_count_rppef(period_start, period_end, provider, true, true)
		/* M2014_19_2_ID implemented externally */

		WHEN	M2014_20_2_ID THEN
			query_result := get_radiology_image_count_rpp(period_start, period_end, provider)
		WHEN	M2014_21_2_ID THEN
			query_result := get_patient_fhh_count_rpp(period_start, period_end, provider)
		WHEN	M2014_22_2_ID THEN
			query_result := get_patient_electronic_note_count_rpp(period_start, period_end, provider)
	    /* M2016_9_ID implemented externally */
		/* M2018_ACI_CCTPE_2 implemented externally */

		/* M2017_8_1 implemented externally */
		/* M2018_ACI_TRANS_PEA_1 implemented externally */
		/* M2018_5_1_ID implemented externally */
		/* M2018_ACI_PEA_1 implemented externally */

		/* M2018_5_2_ID implemented externally */
		/* M2018_ACI_PEA_2 implemented externally */


		WHEN	M2017_8_2,
				M2018_ACI_TRANS_PEA_2 THEN
			query_result := get_patient_vdt_use_count_rpp(period_start, period_end, provider)
		WHEN	M2018_6_1_ID,
				M2018_ACI_CCTPE_1 THEN
			query_result := get_patient_vdt_or_api_use_count_rpp(period_start, period_end, provider)
		WHEN	M2018_6_3_ID,
				M2018_ACI_CCTPE_3 THEN
			query_result := get_patient_generated_data_count_rpp(period_start, period_end, provider)
		WHEN	M2018_7_2_ID THEN
			query_result := get_soc_incorporation_count_rppt(period_start, period_end, provider, tin)
		WHEN	M2018_ACI_EP_1, M2019_PI_EP THEN
			query_result := get_electronic_nonscheduled_sent_count_rpp(period_start, period_end, provider) +
							get_electronic_nonscheduled_sent_error_count_rpp(period_start, period_end, provider)
		WHEN	M2018_7_1_ID,
		        M2018_ACI_HIE_1, M2019_PI_SEND_HI THEN
			query_result := get_soc_outgoing_elec_count_rppvt(period_start, period_end, provider, true, tin)
		WHEN	M2018_ACI_HIE_2 THEN
			query_result := get_soc_incorporation_count_rppt(period_start, period_end, provider, tin)
		WHEN	M2018_7_3_ID,
				M2018_ACI_HIE_3 THEN
			query_result := get_soc_reconciled_count_rppt(period_start, period_end, provider, tin)
		ELSE
			query_result := 0; -- debug
	END CASE
	RETURN query_result
END
$$
ALTER FUNCTION dbo.get_measure_numerator_2014(measure_id integer, period_start date, period_end date, provider integer, tin NVARCHAR(MAX)) OWNER TO postgres
--
-- Name: get_measure_numerator_2014_list(integer, date, date, integer, NVARCHAR(MAX)); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_measure_numerator_2014_list(measure_id integer, period_start date, period_end date, provider integer, tin NVARCHAR(MAX)) RETURNS SETOF integer
    LANGUAGE plpgsql
    AS $$
/**********
PL/pgSQL function get_measure_numerator_2014_list(integer, date, date, integer)

Created: 11/2014
Version: 1.4
Author: Phil Belyaev

Given input parameters for a measure ID, reporting period start and end dates, and provider ID,
calculate and return the list comprising the numerator for the Meaningful Use Report, in accordance with the
2014 Test Procedure for 170.314(g)(1) Automated numerator recording &
170.314(g)(2) Automated measure calculation.

Call subordinate functions for individual measure numerator calculations.

CHANGE LOG
1.9     Added M2017_8_1 for MOD_STAGE_2_2017_OBJECTIVE_8_VDT_ACCESS and M2017_8_2 for MOD_STAGE_2_2017_OBJECTIVE_8_VDT_USE.
1.8		Support TIN (Tax ID Number) parameter to use in queries along with provider id. (tcp 2/12/2018)
		Note for numerator calculation, patient-based ACI measures require transitivity across TINs
		so they will not use TIN as a condition:
			M2018_ACI_PEA_2,
			M2018_ACI_TRANS_PSE_1,
			M2018_ACI_PEA_1,
			M2018_ACI_TRANS_PEA_1,
			M2018_ACI_CCTPE_1,
			M2018_ACI_TRANS_PEA_2,
			M2018_ACI_CCTPE_2,
			M2018_ACI_CCTPE_3
		Added M2018_ACI_EP_1 for ACI_2018_E_PRESCRIBING
		Added M2018_ACI_HIE_1 for ACI_2018_HIE_SEND_SOC
		Added M2018_ACI_HIE_2 for ACI_2018_HIE_ACCEPT_SOC
		Added M2018_ACI_HIE_3 for ACI_2018_HIE_RECONCILIATION
		Added M2018_ACI_PEA_2 for ACI_2018_PEA_PATIENT_EDUCATION
		Added M2018_ACI_PEA_1 for ACI_2018_PEA_VDT_AND_API_ACCESS
		Added M2018_ACI_CCTPE_for 1 ACI_2018_CC_VDT_OR_API_USE
		Added M2018_ACI_CCTPE_2 for ACI_2018_CC_SECURE_MSG
		Added M2018_ACI_CCTPE_3 for ACI_2018_CC_PATIENT_HEALTH_DATA
		Added M2018_ACI_TRANS_PSE_1 for ACI_TRANSITION_2018_PATIENT_SPECIFIC_EDUCATION
		Added M2018_ACI_TRANS_PEA_1 for ACI_TRANSITION_2018_PROVIDE_PATIENT_ACCESS
		Added M2018_ACI_TRANS_PEA_2 for ACI_TRANSITION_2018_VIEW_DOWNLOAD_TRANSMIT
1.7		Added M2018_5_1_ID for MeaningfulUseID.STAGE_3_OBJECTIVE_5_VDT_AND_API_ACCESS. (tcp 2/6/2018)
		Added M2018_5_2_ID for MeaningfulUseID.STAGE_3_OBJECTIVE_5_PATIENT_EDUC_ELEC_ACCESS.
		Added M2018_6_1_ID for MeaningfulUseID.STAGE_3_OBJECTIVE_6_VDT_OR_API_USE.
1.6		Added M2018_6_3_ID for MeaningfulUseID.STAGE_3_OBJECTIVE_6_PATIENT_HEALTH_DATA. (tcp 1/29/2018)
1.5		Added M2018_7_2_ID for MeaningfulUseID.STAGE_3_OBJECTIVE_7_SOC_INCORPORATION. (tcp 1/25/2018)
1.4     Added M2016_9_ID for MeaningfulUseID.MOD_STAGE_2_2016_OBJECTIVE_9_SECURE_MSG. (tcp 3/10/2016)
1.3		Add legacy Stage 1 menu measures (M2_ID, M4_ID, M6_ID, M7_ID, M8_ID)
1.2		Adjust Vital Signs numerators (M2014_10_1_BP_OOS_ID, M2014_10_1_HW_OOS_ID, M2014_10_1_ID, M2014_10_2_BP_OOS_ID, M2014_10_2_HW_OOS_ID, M2014_10_2_ID) (pb).
1.1		Add legacy Stage 1 core measures
1.0		Original version
*********/
DECLARE
	C3_ID integer := 0
	C5_ID integer := 1
	C6_ID integer := 2
	C7_ID integer := 3
	C8_ID integer := 6
	C9_ID integer := 7
	C12_ID integer := 12; /* implemented externally */

	M2_ID integer := 8
	M4_ID integer := 15
	M6_ID integer := 4
	M7_ID integer := 10
	M8_ID integer := 11
	M2014_7_1_ID integer := 25
	M2014_7_1_ALT_ID integer := 26
	M2014_7_2_MED_ID integer := 27
	M2014_7_2_RAD_ID integer := 28
	M2014_7_2_LAB_ID integer := 29
	M2014_8_1_ID integer := 30
	M2014_8_2_ID integer := 32
	M2014_9_ID integer := 33
	M2014_10_1_BP_OOS_ID integer := 34
	M2014_10_1_HW_OOS_ID integer := 35
	M2014_10_1_ID integer := 36
	M2014_10_2_BP_OOS_ID integer := 37
	M2014_10_2_HW_OOS_ID integer := 38
	M2014_10_2_ID integer := 39
	M2014_11_ID integer := 40
	M2014_12_ID integer := 41
	M2014_13_1_ID integer := 42
	M2014_13_2_ID integer := 43
	M2014_14_A_ID integer := 44
	M2014_14_B_ID integer := 45
	M2014_15_1_ID integer := 46
	M2014_15_2_ID integer := 47
	M2014_16_1_ID integer := 48
	M2014_16_2_ID integer := 49
	M2014_17_1_ID integer := 50
	M2014_17_2_ID integer := 51
	M2014_18_1_ID integer := 52
	M2014_18_2_A_ID integer := 53
	M2014_18_2_B_ID integer := 54
	M2014_19_2_ID integer := 55
	M2014_20_2_ID integer := 56
	M2014_21_2_ID integer := 57
	M2014_22_2_ID integer := 58
	M2016_9_ID integer := 100
	M2017_6_1 integer := 119
	M2017_8_1 integer := 121
	M2017_8_2 integer := 122
	M2018_5_1_ID integer := 140
	M2018_5_2_ID integer := 141
	M2018_6_1_ID integer := 142
	M2018_6_3_ID integer := 144
	M2018_7_1_ID integer := 145
	M2018_7_2_ID integer := 146
	M2018_7_3_ID integer := 147
	M2018_ACI_TRANS_PSE_1 integer := 129
 	M2018_ACI_TRANS_PEA_1 integer := 130
 	M2018_ACI_TRANS_PEA_2 integer := 131
 	M2018_ACI_EP_1 integer	:= 150
 	M2018_ACI_HIE_1 integer := 151
 	M2018_ACI_HIE_2 integer := 152
 	M2018_ACI_HIE_3 integer := 153
 	M2018_ACI_PEA_2 integer := 154
 	M2018_ACI_PEA_1 integer := 155
 	M2018_ACI_CCTPE_1 integer := 156
 	M2018_ACI_CCTPE_2 integer := 157
 	M2018_ACI_CCTPE_3 integer := 158
 	M2019_PI_EP integer := 161
 	M2019_PI_SEND_HI integer := 162
    M2019_PI_PEA integer := 163
	TOKEN_PATIENT integer := -1
	TOKEN_EXAM integer := -2
	TOKEN_RADIOLOGY_IMAGING_ORDER integer := -3
	TOKEN_LAB_ORDER integer := -4
	TOKEN_REFERRAL_DOCUMENT integer := -5
	TOKEN_SOC_RECEIVED_DOCUMENT integer := -6
BEGIN
	CASE measure_id
		WHEN	C3_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_stage1_c3_list_rpp(period_start, period_end, provider)
		WHEN	C5_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_stage1_c5_list_rpp(period_start, period_end, provider)
		WHEN	C6_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_stage1_c6_list_rpp(period_start, period_end, provider)
		WHEN	C8_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_vitals_list_ndr(period_start, period_end, provider, 2)
		WHEN	M2014_7_1_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_electronic_medication_list_rpp(period_start, period_end, provider)
			RETURN QUERY SELECT get_patient_electronic_medication_error_list_rpp(period_start, period_end, provider)
		WHEN	M2014_7_2_RAD_ID THEN
			RETURN QUERY SELECT TOKEN_RADIOLOGY_IMAGING_ORDER
			RETURN QUERY SELECT get_radiology_order_list_rpp(period_start, period_end, provider)
		WHEN	M2014_7_2_LAB_ID THEN
			RETURN QUERY SELECT TOKEN_LAB_ORDER
			RETURN QUERY SELECT get_lab_order_list_rpp(period_start, period_end, provider)
		WHEN	M2014_7_1_ALT_ID,
				M2014_7_2_MED_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_electronic_medication_list_rpp(period_start, period_end, provider)
			RETURN QUERY SELECT	get_electronic_medication_error_list_rpp(period_start, period_end, provider)
		WHEN	M2014_8_1_ID,
				M2014_8_2_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_electronic_nonscheduled_sent_list_rpp(period_start, period_end, provider)
			RETURN QUERY SELECT get_electronic_nonscheduled_sent_error_list_rpp(period_start, period_end, provider)
		WHEN	C7_ID,
				M2014_9_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_demographics_list_rpp(period_start, period_end, provider)
		WHEN	M2014_10_1_BP_OOS_ID,
				M2014_10_2_BP_OOS_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_height_weight_list_rppa(period_start, period_end, provider, 0)
		WHEN	M2014_10_1_HW_OOS_ID,
				M2014_10_2_HW_OOS_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_blood_pressure_list_rppa(period_start, period_end, provider, 3)
		WHEN	M2014_10_1_ID,
				M2014_10_2_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_combined_vitals_list_rpp(period_start, period_end, provider)
		WHEN	C9_ID,
				M2014_11_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_smoking_status_list_rppa(period_start, period_end, provider, 13)
		WHEN	M2_ID,
				M2014_12_ID THEN
			RETURN QUERY SELECT TOKEN_LAB_ORDER
			RETURN QUERY SELECT get_lab_result_list_rpp(period_start, period_end, provider)
		WHEN	M4_ID,
				M2014_13_1_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_recall_list_565_rpp(period_start, period_end, provider)
		WHEN	M2014_13_2_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_recall_list_224_rpp(period_start, period_end, provider)
		/* M2014_14_A_ID implemented externally */
		/* M2014_14_B_ID implemented externally */

		WHEN	M2014_15_1_ID THEN
			RETURN QUERY SELECT TOKEN_EXAM
			RETURN QUERY SELECT get_exam_csp_list_rppi(period_start, period_end, provider, 3)
		WHEN	M2014_15_2_ID THEN
			RETURN QUERY SELECT TOKEN_EXAM
			RETURN QUERY SELECT get_exam_csp_list_rppi(period_start, period_end, provider, 1)
		WHEN	M6_ID,
				M2014_16_1_ID,
				M2014_16_2_ID  THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_education_list_rpp(period_start, period_end, provider)
		WHEN	M2017_6_1,
				M2018_ACI_TRANS_PSE_1 THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_education_provider_list_rpp(period_start, period_end, provider)
		WHEN	M7_ID,
				M2014_17_1_ID,
				M2014_17_2_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_medication_reconciliation_list_rppf(period_start, period_end, provider, true)
		WHEN	M8_ID,
				M2014_18_1_ID,
				M2014_18_2_A_ID THEN
			RETURN QUERY SELECT TOKEN_REFERRAL_DOCUMENT
			RETURN QUERY SELECT get_soc_outgoing_list_rppef(period_start, period_end, provider, false, true)
		WHEN	M2014_18_2_B_ID THEN
			RETURN QUERY SELECT TOKEN_REFERRAL_DOCUMENT
			RETURN QUERY SELECT get_soc_outgoing_list_rppef(period_start, period_end, provider, true, true)
		/* M2014_19_2_ID implemented externally */

		WHEN	M2014_20_2_ID THEN
			RETURN QUERY SELECT TOKEN_RADIOLOGY_IMAGING_ORDER
			RETURN QUERY SELECT get_radiology_image_list_rpp(period_start, period_end, provider)
		WHEN	M2014_21_2_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_fhh_list_rpp(period_start, period_end, provider)
		WHEN	M2014_22_2_ID THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_electronic_note_list_rpp(period_start, period_end, provider)
		/* M2016_9_ID implemented externally */
		/* M2018_ACI_CCTPE_2 implemented externally */

		/* M2017_8_1 implemented externally */
		/* M2018_ACI_TRANS_PEA_1 implemented externally */
		/* M2018_5_1_ID implemented externally */
		/* M2018_ACI_PEA_1 implemented externally */

		/* M2018_5_2_ID implemented externally */
		/* M2018_ACI_PEA_2 implemented externally */

		WHEN	M2017_8_2,
				M2018_ACI_TRANS_PEA_2 THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_vdt_use_list_rpp(period_start, period_end, provider)
		WHEN	M2018_6_1_ID,
				M2018_ACI_CCTPE_1 THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_vdt_or_api_use_list_rpp(period_start, period_end, provider)
		WHEN	M2018_6_3_ID,
				M2018_ACI_CCTPE_3 THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_patient_generated_data_list_rpp(period_start, period_end, provider)
		WHEN	M2018_7_2_ID THEN
			RETURN QUERY SELECT TOKEN_SOC_RECEIVED_DOCUMENT
			RETURN QUERY SELECT get_soc_incorporation_list_rppt(period_start, period_end, provider, tin)
		WHEN	M2018_ACI_EP_1, M2019_PI_EP THEN
			RETURN QUERY SELECT TOKEN_PATIENT
			RETURN QUERY SELECT get_electronic_nonscheduled_sent_list_rpp(period_start, period_end, provider)
			RETURN QUERY SELECT get_electronic_nonscheduled_sent_error_list_rpp(period_start, period_end, provider)
			WHEN	M2018_7_1_ID,
			        M2018_ACI_HIE_1, M2019_PI_SEND_HI THEN
			RETURN QUERY SELECT TOKEN_REFERRAL_DOCUMENT
			RETURN QUERY SELECT get_soc_outgoing_elec_list_rppvt(period_start, period_end, provider, true, tin)
		WHEN	M2018_ACI_HIE_2 THEN
			RETURN QUERY SELECT TOKEN_SOC_RECEIVED_DOCUMENT
			RETURN QUERY SELECT get_soc_incorporation_list_rppt(period_start, period_end, provider, tin)
		WHEN 	M2018_7_3_ID,
				M2018_ACI_HIE_3 THEN
			RETURN QUERY SELECT TOKEN_SOC_RECEIVED_DOCUMENT
			RETURN QUERY SELECT get_soc_reconciled_list_rppt(period_start, period_end, provider, tin)
		ELSE
			RETURN QUERY SELECT 0; -- debug
	END CASE
	RETURN
END
$$
