1.1		Redfine FATHER, etc variables to coincide with Java enum values. tcp
1.0		Original version

*********/

DECLARE
FATHER integer := 0
MOTHER integer := 1
DAUGHTER integer := 2
SON integer := 3
BROTHER integer := 4
SISTER integer := 5
BEGIN
	
	RETURN COUNT(DISTINCT patient_id) FROM v_patient_exam_fhh 
	WHERE exam_provider = provider AND exam_date BETWEEN period_start AND period_end AND
	relation IN (FATHER, MOTHER, DAUGHTER, SON, BROTHER, SISTER)
END
$$
