	RETURN COUNT(DISTINCT patient_id) FROM v_patient_exams 
	INNER JOIN v_patient_exam_ros_nonnull_smoking USING (patient_id)
	WHERE exam_provider = provider AND exam_date BETWEEN period_start AND period_end 
	AND patient_age_at_exam >= patient_age
END
$$
