--
-- Name: get_preferred_contact(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_preferred_contact(p_patient_id integer) RETURNS NVARCHAR(MAX)
    LANGUAGE plpgsql
    AS $$
DECLARE 
	v_preferred_contact NVARCHAR(MAX)
	v_contact_number NVARCHAR(MAX)
	v_contact_number_extension NVARCHAR(MAX)
BEGIN

	SELECT lower(preferred_contact) FROM patient WHERE patient.id = p_patient_id INTO v_preferred_contact
	IF (v_preferred_contact IS NOT NULL AND v_preferred_contact <> 'n/a') THEN
		IF (v_preferred_contact = 'phone') THEN 
			v_contact_number = get_contact_number(p_patient_id, 'phone', 'phone_home')
		ELSIF (v_preferred_contact = 'work') THEN
			v_contact_number = get_contact_number(p_patient_id, 'phone', 'phone_work')
		ELSIF (v_preferred_contact = 'cell') THEN 
			v_contact_number = get_contact_number(p_patient_id, 'phone', 'phone_cell')
		ELSIF (v_preferred_contact = 'fax') THEN 
			v_contact_number = get_contact_number(p_patient_id, 'phone', 'phone_fax')
		ELSIF (v_preferred_contact = 'email') THEN
			v_contact_number = get_contact_number(p_patient_id, 'email', null)
		ELSIF (v_preferred_contact = 'pager') THEN 
			v_contact_number = get_contact_number(p_patient_id, 'phone', 'phone_pager')
		ELSE 
			v_contact_number = get_contact_number(p_patient_id, 'phone', 'phone_home')
		END IF
	ELSE
		v_contact_number = get_contact_number(p_patient_id, 'phone', 'phone_home')
	END IF
	RETURN v_contact_number
END
$$
ALTER FUNCTION dbo.get_preferred_contact(p_patient_id integer) OWNER TO postgres
