CREATE FUNCTION dbo.get_soc_available_count_rppt(period_start date, period_end date, provider integer, tin NVARCHAR(MAX)) RETURNS integer
    LANGUAGE plpgsql
    AS $$

/**********

PL/pgSQL function get_soc_available_count_rppt(date, date, integer, NVARCHAR(MAX))

Created: 05/2014
Version: 1.0
Author: Phil Belyaev

Given input parameters for a reporting period start and end dates, provider ID, tin ...
*********/

DECLARE
	SUMMARY_OF_CARE_INCOMING integer := 3
BEGIN

	RETURN COUNT(DISTINCT vrdr.received_id) FROM v_referral_documents_received vrdr
	WHERE received_provider = provider AND (tin is null OR length(tin) = 0 OR received_office_tin = tin)
    AND patient_in_date BETWEEN period_start AND period_end
    AND requested_date BETWEEN period_start AND period_end
	AND available
END
$$
