--
-- Name: get_transferred_amount(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_transferred_amount(v_patient_id integer, v_payment_set_id integer) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    grand_total numeric(11,2) := 0(11,2)
    payment_total numeric(11,2) := 0(11,2)
    allocation_total numeric(11,2) := 0(11,2)
    credit_total numeric(11,2) := 0(11,2)
BEGIN
	SELECT sum(p.amount) into payment_total from payment p where p.patient_id = v_patient_id and p.payment_set_id = v_payment_set_id
	if payment_total is null then
		payment_total := 0
	end if
	SELECT sum(pa.amount) into allocation_total from payment_allocation pa where pa.patient_id = v_patient_id and pa.payment_set_id = v_payment_set_id
	if allocation_total is null then
		allocation_total := 0
	end if
	SELECT sum(p.amount) into credit_total from payment p where p.patient_id = v_patient_id and p.parent_payment_set_id = v_payment_set_id
	if credit_total is null then
		credit_total := 0
	end if
	grand_total := payment_total - credit_total - allocation_total
	return grand_total
END
$$
ALTER FUNCTION dbo.get_transferred_amount(v_patient_id integer, v_payment_set_id integer) OWNER TO postgres
--
-- Name: get_transfers_for_ledger(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.get_transfers_for_ledger(v_patient_id integer) RETURNS SETOF dbo.transfer_record
    LANGUAGE plpgsql STABLE
    AS $$
declare 
	r transfer_record%rowtype
begin

	for r in select ps.id, ps.date_of_payment_set as transaction_date, get_transferred_amount(v_patient_id, ps.id) as patient_amount
		from payment_set ps where
		ps.id in (select distinct ps.id from payment_set ps left join payment p on p.payment_set_id = ps.id left join payment_allocation pa on pa.payment_set_id = ps.id 
			where (ps.is_refund_set is null or ps.is_refund_set = false)
		and (p.patient_id = v_patient_id or pa.patient_id = v_patient_id) and (p.payment_type_id = 3 or p.payment_type_id = 1))
		and get_transferred_amount(v_patient_id, ps.id) <> 0
	end loop
	return
end
$$
ALTER FUNCTION dbo.get_transfers_for_ledger(v_patient_id integer) OWNER TO postgres
