--
-- Name: import_new_medications_no_duplicates(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.import_new_medications_no_duplicates() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD
	count INTEGER
BEGIN
	FOR r IN (SELECT * FROM exam_medication_temp) LOOP
		SELECT COUNT(id) AS count INTO count FROM exam_medication WHERE UPPER(medication_name) = UPPER(r.medication_name)
		IF count = 0 THEN
			INSERT INTO exam_medication (id, medication_name, medication_description) VALUES (nextval('exam_medication_id_seq'), r.medication_name, r.medication_description)
		END IF
		END LOOP
	RETURN 1
END
$$
ALTER FUNCTION dbo.import_new_medications_no_duplicates() OWNER TO postgres
