-- Name: increment_conf_panel_order(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.increment_conf_panel_order(marker_parent integer, marker_order_id integer, new_panel_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    marker_parent ALIAS for $1
    marker_order_id ALIAS for $2
BEGIN
    
    insert into emr_panels_xref (parent_section_id, panel_id, order_index) values (marker_parent, new_panel_id, marker_order_id +1)
    update emr_panels_xref set order_index = order_index + 1 where parent_section_id = marker_parent and order_index > marker_order_id and panel_id != new_panel_id
END
$_$
ALTER FUNCTION dbo.increment_conf_panel_order(marker_parent integer, marker_order_id integer, new_panel_id integer) OWNER TO postgres
