-- Name: is_debit_normal_balance(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.is_debit_normal_balance(account integer) RETURNS BIT
    LANGUAGE plpgsql
    AS $_$

DECLARE
  account_number alias for $1
  account_category integer
  account_debit BIT
BEGIN

  account_category := account_number / 1000
  IF account_category = 1 OR account_category = 5 THEN
    account_debit:=true
  ELSE
    account_debit:=false
  end if
  return account_debit
END
$_$
ALTER FUNCTION dbo.is_debit_normal_balance(account integer) OWNER TO postgres
--
-- Name: isinuse(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.isinuse(codeid integer) RETURNS BIT
    LANGUAGE plpgsql
    AS $_$
DECLARE
    c integer
BEGIN
	EXECUTE 'SELECT count(*) FROM patient_family_health_history_item WHERE code_id = $1' INTO c USING codeID
	IF c = 0 THEN
	--Not found
		EXECUTE 'SELECT count(*) FROM patient_diagnostic_code_status WHERE diagnostic_code_id = $1' INTO c USING codeID
		IF c = 0 THEN
		--Not found
			EXECUTE 'SELECT count(*) FROM exam_diagnosis_and_management_options WHERE diagnostic_code_id = $1' INTO c USING codeID
			IF c = 0 THEN
			--Not found
				EXECUTE 'SELECT count(*) FROM diagnostic_code_education WHERE diagnostic_code_id = $1' INTO c USING codeID
				IF c = 0 THEN
				--Not found
					return false
				END IF
			END IF
		END IF
	END IF
	return true
END
$_$
ALTER FUNCTION dbo.isinuse(codeid integer) OWNER TO postgres
