--
-- Name: move_complaints(NVARCHAR(MAX), NVARCHAR(MAX)[], NVARCHAR(MAX)[], NVARCHAR(MAX)[], NVARCHAR(MAX)[], NVARCHAR(MAX)[], NVARCHAR(MAX)[], NVARCHAR(MAX)[], NVARCHAR(MAX)[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.move_complaints(tblname NVARCHAR(MAX), loc NVARCHAR(MAX)[], qual NVARCHAR(MAX)[], sev NVARCHAR(MAX)[], dur NVARCHAR(MAX)[], timing NVARCHAR(MAX)[], context NVARCHAR(MAX)[], mod_factors NVARCHAR(MAX)[], signs NVARCHAR(MAX)[], cc_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    an_array        ALIAS FOR $2
    in_table        ALIAS FOR $1
    size            int
    val             NVARCHAR(MAX)
    location_txt        NVARCHAR(MAX)
    quality_txt     NVARCHAR(MAX)
    severity_txt        NVARCHAR(MAX)
    duration_txt        NVARCHAR(MAX)
    timing_txt      NVARCHAR(MAX)
    context_txt     NVARCHAR(MAX)
    mod_factors_txt     NVARCHAR(MAX)
    signs_txt       NVARCHAR(MAX)
    q_string NVARCHAR(MAX)
BEGIN

    -- initialize to empty strings
    location_txt = ''
    quality_txt = ''
    severity_txt = ''
    duration_txt = ''
    timing_txt = ''
    context_txt = ''
    mod_factors_txt = ''
    signs_txt = ''
    -- get the size of the largest array
    size = array_upper(loc,1)
    if array_upper(dur,1)>size THEN
        size = array_upper(dur,1)
    END IF
    if array_upper(sev,1)>size THEN
        size = array_upper(sev,1)
    END IF
    if array_upper(timing,1)>size THEN
        size = array_upper(timing,1)
    END IF
    if array_upper(context,1)>size THEN
        size = array_upper(context,1)
    END IF
    if array_upper(mod_factors,1)>size THEN
        size = array_upper(mod_factors,1)
    END IF
    if array_upper(signs,1)>size THEN
        size = array_upper(signs,1)
    END IF
    if size is NULL THEN 
        size = 0
    END IF
    if size>0 THEN
        FOR i IN 1..size LOOP
                       
                location_txt = loc[i]
                quality_txt = qual[i]
                severity_txt = sev[i]
                duration_txt = dur[i]
                timing_txt = timing[i]
                context_txt = context[i]
                mod_factors_txt = mod_factors[i]
                signs_txt = signs[i]
            -- since our insert query string cannot execute with NULLs we have to replace them with empty strings
            IF location_txt is NULL THEN
                location_txt = ''
            END IF
            IF quality_txt is NULL THEN
                quality_txt =  ''
            END IF
            IF severity_txt is NULL THEN
                severity_txt =  ''
            END IF
            IF duration_txt is NULL THEN
                duration_txt =  ''
            END IF
            IF timing_txt is NULL THEN
                timing_txt =  ''
            END IF
            IF context_txt is NULL THEN
                context_txt =  ''
            END IF
            IF mod_factors_txt is NULL THEN
                mod_factors_txt =  ''
            END IF
            IF signs_txt is NULL THEN
                signs_txt =  ''
            END IF
    location_txt := replace(location_txt, $q$'$q$, $q$\'$q$)
    quality_txt := replace(quality_txt, $q$'$q$, $q$\'$q$)
    severity_txt := replace(severity_txt, $q$'$q$, $q$\'$q$)
    duration_txt := replace(duration_txt, $q$'$q$, $q$\'$q$)
    timing_txt := replace(timing_txt, $q$'$q$, $q$\'$q$)
    context_txt := replace(context_txt, $q$'$q$, $q$\'$q$)
    mod_factors_txt := replace(mod_factors_txt, $q$'$q$, $q$\'$q$)
    signs_txt := replace(signs_txt, $q$'$q$, $q$\'$q$)
        q_string = 'INSERT INTO ' || quote_ident(in_table) ||' values(nextval(''' || quote_ident(in_table) || '_seq' ||'''), ' ||cc_id|| ','''||
                    location_txt ||''','''||
                    quality_txt ||''','''||
                    severity_txt ||''','''||
                    duration_txt ||''','''||
                    timing_txt ||''','''||
                    context_txt ||''','''||
                    mod_factors_txt ||''','''||
                    signs_txt ||''')'
           -- perform insert
            execute q_string
            -- reset to empty strings
            location_txt = ''
            quality_txt = ''
            severity_txt = ''
            duration_txt = ''
            timing_txt = ''
            context_txt = ''
            mod_factors_txt = ''
            signs_txt = ''
        END LOOP
    END IF
END
$_$
ALTER FUNCTION dbo.move_complaints(tblname NVARCHAR(MAX), loc NVARCHAR(MAX)[], qual NVARCHAR(MAX)[], sev NVARCHAR(MAX)[], dur NVARCHAR(MAX)[], timing NVARCHAR(MAX)[], context NVARCHAR(MAX)[], mod_factors NVARCHAR(MAX)[], signs NVARCHAR(MAX)[], cc_id integer) OWNER TO postgres
--
-- Name: move_exam_case_hist(NVARCHAR(MAX), NVARCHAR(MAX)[], NVARCHAR(MAX), integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.move_exam_case_hist(tblname NVARCHAR(MAX), comp NVARCHAR(MAX)[], comments NVARCHAR(MAX), anid integer) RETURNS void
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    an_array        ALIAS FOR $2
    in_table        ALIAS FOR $1
    val             NVARCHAR(MAX)
    is_chief        NVARCHAR(MAX)
    q_string        NVARCHAR(MAX)
    com             NVARCHAR(MAX)
BEGIN
    com = $3
    com = replace(com, $q$'$q$, $q$\'$q$)
    if array_upper(comp,1)>0 THEN
        FOR i IN 1..array_upper(comp, 1) LOOP
            is_chief = false
            if i = 1 THEN
                is_chief = true
            END IF
         val := trim(comp[i])
        val := replace(val, $q$'$q$, $q$\'$q$)
        q_string = 'INSERT INTO '|| quote_ident(in_table) || ' values(nextval('''|| quote_ident(in_table)||'_seq' ||''')' || ','|| anid || ',''' 
            || is_chief || ''',''' ||coalesce(val, '') || ''','''|| coalesce(com, '') ||''')'
        execute q_string
        END LOOP
        execute 'select exam_case_history.id, move_complaints(''exam_hpi'', 
    string_to_array(hpi_location, '':''),
    string_to_array(hpi_quality, '':''),
    string_to_array(hpi_severity, '':''),
    string_to_array(hpi_duration, '':''),
    string_to_array(hpi_timing, '':''),
    string_to_array(hpi_context, '':''),
    string_to_array(hpi_modifying_factors, '':''),
    string_to_array(hpi_signs_symptoms, '':''), exam_chief_complaints.id) from exam_case_history, exam_chief_complaints where exam_chief_complaints.exam_case_history_id = exam_case_history.id  
                            and exam_case_history.id = ' || anid 
    END IF
END;$_$
ALTER FUNCTION dbo.move_exam_case_hist(tblname NVARCHAR(MAX), comp NVARCHAR(MAX)[], comments NVARCHAR(MAX), anid integer) OWNER TO postgres
--
-- Name: move_exam_case_hist_with_null_chief(NVARCHAR(MAX), NVARCHAR(MAX), NVARCHAR(MAX), integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.move_exam_case_hist_with_null_chief(tblname NVARCHAR(MAX), complaint NVARCHAR(MAX), comments NVARCHAR(MAX), anid integer) RETURNS void
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    in_table        ALIAS FOR $1
    comp        NVARCHAR(MAX)
    val             NVARCHAR(MAX)
    is_chief        NVARCHAR(MAX)
    q_string        NVARCHAR(MAX)
    com             NVARCHAR(MAX)
BEGIN
    comp = $2
    com = $3
    com = replace(com, $q$'$q$, $q$\'$q$)
    if com is null THEN
     com = ''
    END IF
    if comp is NULL or comp = '' THEN
        is_chief = true
        comp = ''
        q_string = 'INSERT INTO '|| quote_ident(in_table) || ' values(nextval('''|| quote_ident(in_table)||'_seq' ||''')' || ','|| anid || ',''' 
            || is_chief || ''',''' ||comp || ''','''|| com ||''')'
        execute q_string
        execute 'select exam_case_history.id, move_complaints(''exam_hpi'', 
    string_to_array(hpi_location, '':''),
    string_to_array(hpi_quality, '':''),
    string_to_array(hpi_severity, '':''),
    string_to_array(hpi_duration, '':''),
    string_to_array(hpi_timing, '':''),
    string_to_array(hpi_context, '':''),
    string_to_array(hpi_modifying_factors, '':''),
    string_to_array(hpi_signs_symptoms, '':''), exam_chief_complaints.id) from exam_case_history, exam_chief_complaints where exam_chief_complaints.exam_case_history_id = exam_case_history.id  
                            and exam_case_history.id = ' || anid 
    END IF
END;$_$
ALTER FUNCTION dbo.move_exam_case_hist_with_null_chief(tblname NVARCHAR(MAX), complaint NVARCHAR(MAX), comments NVARCHAR(MAX), anid integer) OWNER TO postgres
--
-- Name: no_multilevel_guarantors(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.no_multilevel_guarantors() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  i BIT
BEGIN
    IF (TG_OP = 'INSERT' OR TG_OP = 'UPDATE') THEN
        i := exists (select id from patient where (guarantor = NEW.id and (NEW.guarantor IS NOT NULL OR NEW.non_patient_guarantor IS NOT NULL)) OR (id = NEW.guarantor and patient.guarantor is not null))
        IF i = true THEN
            RAISE EXCEPTION 'multilevel_guarantors: No multilevel guarantor allowed.'
        END IF
        RETURN NEW
    END IF
END
$$
ALTER FUNCTION dbo.no_multilevel_guarantors() OWNER TO postgres
--
-- Name: normalizecode(NVARCHAR(MAX), integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.normalizecode(code NVARCHAR(MAX), codetype integer) RETURNS NVARCHAR(MAX)
    LANGUAGE plpgsql
    AS $_$
/**********

PL/pgSQL function normalizeCode(code NVARCHAR(MAX)(30), type integer)

Created: 12/2014
Version: 1.0
Author: Dan Hutchinson

Given input parameters of a Display code, convert it to a decimal free format.
Currently this only applies to ICD9 and ICD10, if a code system other than those
are given the code is returned as given.  Support can be added for other code systems
as needed.  If the ICD9 or ICD10 code does not follow the standard display spec, null
is returned.  

ICD9 3-5 charaters, decimal after the 3rd char if more than 3 charters in length. 
ICD9 3-7 charaters, decimal after the 3rd char if more than 3 charters in length.

CHANGE LOG
1.0		Original version

*********/

    DECLARE
	query_result NVARCHAR(MAX)(30)
	ICD9 integer := 0
	ICD10 integer := 1
BEGIN

	-- Normalize if ICD9
	IF $2 = ICD9 THEN
	    -- test if only 3 chars
		IF length($1) = 3 THEN
		     query_result := $1
		-- check if there is a period in the third NCHAR(1) and only 1 period total
		ELSIF regexp_replace($1, '[evEV0-9][\d][\d](\.\d\d)?(\.\d)?'(MAX), 'X') = 'X' THEN
		   query_result:= upper(regexp_replace($1, '\.', ''))
		ELSE
			query_result:=''
		END IF
	-- Normalize if ICD10
	ELSIF $2 = ICD10 THEN
	    -- test if only 3 chars
		IF length($1) = 3 THEN
		     query_result := $1
		-- check if there is a period in the third NCHAR(1) and only 1 period total
		ELSIF regexp_replace($1, '[a-zA-Z0-9][\d][\d](\.\d\d\d\d)?(\.\d\d\d)?(\.\d\d)?(\.\d)?'(MAX), 'X') = 'X' THEN
		   query_result:= upper(regexp_replace($1, '\.', ''))
		ELSE
			query_result:=''
		END IF
	-- JUST return otherwise
	ELSE
		query_result:= $1
	END IF
	RETURN query_result
END
$_$
ALTER FUNCTION dbo.normalizecode(code NVARCHAR(MAX), codetype integer) OWNER TO postgres
