--
-- Name: nqf_13(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_13(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier,
    '13'(MAX), null, null,
    count(patient_id),
    count(exams_with_blood_pressure),
    0,
    count(patient_id) - count(exams_with_blood_pressure),
    100.00,
    safe_divide (count(exams_with_blood_pressure)* 100, count(patient_id))
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi, patient.id as patient_id, nullif(count(ex.blood_pressure), 0) as exams_with_blood_pressure
    from
        patient
        inner join (select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                (nullif(trim(blood_pressure_a(MAX)), '') || nullif(trim(blood_pressure_b(MAX)), '')) as blood_pressure
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id 
                inner join exam_medical_decision emd on exam.id=emd.exam_id
                inner join exam_physical ep on exam.id = ep.exam_id
            where 
                (exam_date_of_service between $1 and $2) and
                nqf_util_check_exam_status(exam.id, exam.exam_status, $5) and       
                doctor_provider.national_provider_identifier = any ($3) and
                nqf_util_procedure_code_check(exam.id, ARRAY['99304', '99305', '99306', '99307', '99308', '99309', '99310', '99201', '99202', '99203', '99204', '99205', '99212', '99213',
                            '99214', '99215', '99241', '99242', '99243', '99244', '99245', '99324', '99325', '99326', '99327', '99328', '99334', '99335',
                            '99336', '99337', '99341', '99342', '99343', '99344', '99345', '99347', '99348', '99349', '99350'])
                ) as ex on patient.id=ex.patient_id
    where
        (
            ($4 is null and extract('years' from age($1, patient.date_of_birth))>=18) or
            ($4 is not null and patient.id = $4 and extract('years' from age($1, patient.date_of_birth))>=18)
        ) and
        nqf_util_diagnosis_check(patient_id, $1, $2, ARRAY['401.0', '401.1', '401.9', '402.00', '402.01', '402.10', '402.11', '402.90', '402.91', '403.00',
                    '403.01', '403.10', '403.11', '403.90', '403.91', '404.00', '404.01', '404.02', '404.03', '404.10',
                    '404.11', '404.12', '404.13', '404.90', '404.91', '404.92', '404.93'])
    group by ex.dp_npi, patient.id having count(distinct ex.id) >= 2) as measures 
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_13(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_24_1_1(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_24_1_1(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier,
    '24'(MAX),
    1,
    1,
    count(patient_id),
    count(has_bmi_percentile),
    0,
    count(patient_id) - count(has_bmi_percentile),
    100.00,
    safe_divide (count(has_bmi_percentile)* 100, count(patient_id))
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi,
        patient.id as patient_id,
        nullif(
            exists (
                select
                    ex2.id    
                from
                    doctor_provider as dp2
                    inner join exam as ex2 on dp2.id = ex2.doctor_provider_id
                    inner join exam_physical ep2 on ex2.id = ep2.exam_id
                where 
                    ex2.patient_id = patient.id and
                    dp2.national_provider_identifier = ex.dp_npi and
                    ex2.exam_date_of_service between $1 and $2 and
                    ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                    ep2.height is not null and
                    ep2.weight is not null and
                    ep2.height <> 0
            ) or exists(
                select
                    edmo2.id
                from 
                    doctor_provider as dp2
                    inner join exam as ex2 on dp2.id = ex2.doctor_provider_id
                    inner join exam_medical_decision as emd2 on ex2.id=emd2.exam_id
                    inner join exam_diagnosis_and_management_options as edmo2 on emd2.id=edmo2.exam_medical_decision_id
                    inner join diagnostic_code as dc2 on edmo2.diagnostic_code_id = dc2.id
                where
                    ex2.patient_id = patient.id and
                    dp2.national_provider_identifier = ex.dp_npi and
                    ex2.exam_date_of_service between $1 and $2 and
                    ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                    (upper(trim(dc2.code)) in ('V85.5', 'V85.51', 'V85.52', 'V85.53', 'V85.54'))
            ) or exists(
                select
                    odx2.diagnosis_id,
                    odx2.exam_medical_decision_id
                from 
                    doctor_provider as dp2
                    inner join exam as ex2 on dp2.id = ex2.doctor_provider_id
                    inner join exam_medical_decision as emd2 on ex2.id=emd2.exam_id
                    inner join exam_other_diagnosis_xref as odx2 on emd2.id=odx2.exam_medical_decision_id
                    inner join diagnostic_code as dc2 on odx2.diagnosis_id = dc2.id
                where
                    ex2.patient_id = patient.id and
                    dp2.national_provider_identifier = ex.dp_npi and
                    ex2.exam_date_of_service between $1 and $2 and
                    ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                    (upper(trim(dc2.code)) in ('V85.5', 'V85.51', 'V85.52', 'V85.53', 'V85.54'))
            ), false) as has_bmi_percentile
    from
        patient
        inner join (
            select distinct 
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                left join exam_medical_decision emd on exam.id=emd.exam_id
            where 
               (exam_date_of_service between $1 and $2) and
                exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                doctor_provider.national_provider_identifier = any ($3) and 
                (
                    exists (
                        select 
                            dcp.id
                        from
                            exam_diagnosis_and_management_options as edmo
                            left join diagnostic_code as dcp on edmo.diagnostic_code_id = dcp.id
                        where
                            emd.id=edmo.exam_medical_decision_id and
                            upper(trim(dcp.code)) in (
                               'V70.0', 'V70.3', 'V70.5', 'V70.6', 'V70.8', 'V70.9', 'V24', 'V25', 'V26',
                               'V27', 'V28', 'V45.5', 'V61.5', 'V61.6', 'V61.7', 'V69.2', 'V72.3', 'V72.4')
                    ) or exists (
                        select
                            dco.id
                        from    
                            exam_other_diagnosis_xref as odx 
                            left join diagnostic_code as dco on odx.diagnosis_id = dco.id
                        where
                            emd.id=odx.exam_medical_decision_id and
                            upper(trim(dco.code)) in (
                                'V70.0', 'V70.3', 'V70.5', 'V70.6', 'V70.8', 'V70.9', 'V24', 'V25', 'V26',
                                'V27', 'V28', 'V45.5', 'V61.5', 'V61.6', 'V61.7', 'V69.2', 'V72.3', 'V72.4')
                    ) or exists (
                        select 
                            emdc.id
                        from
                            exam_medical_decision_code as emdc
                        where
                            emd.id=emdc.exam_medical_decision_id and
                            trim(emdc.procedure_code) in (
                               '99201', '99202', '99203', '99204', '99205', '99211', '99212', '99213',
                               '99214', '99215', '99217', '99218', '99219', '99220', '99241', '99242',
                               '99243', '99244', '99245', '99341', '99342', '99343', '99344', '99345',
                               '99347', '99348', '99349', '99350', '99384', '99385', '99386', '99387',
                               '99394', '99395', '99396', '99397', '99401', '99402', '99403', '99404',
                               '99411', '99412', '99420', '99429', '99455', '99456')
                    )        
                ) and not (
                    exists (
                        select 
                            dcp.id
                        from
                            exam_diagnosis_and_management_options as edmo
                            left join diagnostic_code as dcp on edmo.diagnostic_code_id = dcp.id
                        where
                           emd.id=edmo.exam_medical_decision_id and
                           upper(trim(dcp.code)) in (
                               'V26.81', 'V28', 'V28.3', 'V28.81', 'V28.82', 'V72.4', 'V72.40', 'V72.41', 'V72.42')
                    ) or exists (
                        select
                           dco.id
                        from    
                           exam_other_diagnosis_xref as odx 
                           left join diagnostic_code as dco on odx.diagnosis_id = dco.id
                        where
                           emd.id=odx.exam_medical_decision_id and
                           upper(trim(dco.code)) in (
                               'V26.81', 'V28', 'V28.3', 'V28.81', 'V28.82', 'V72.4', 'V72.40', 'V72.41', 'V72.42')
                    )
                )) as ex on patient.id=ex.patient_id
        inner join patient_diagnostic_code_status pdcs on patient.id = pdcs.patient_id
        inner join diagnostic_code on pdcs.diagnostic_code_id = diagnostic_code.id           
    where
        extract('years' from age($1, patient.date_of_birth)) >= 2 and extract('years' from age($1, patient.date_of_birth)) <= 16 and not
        exists (
            SELECT 
                diagnostic_code.id
            from
                patient_diagnostic_code_status pdcs
                inner join diagnostic_code on pdcs.diagnostic_code_id = diagnostic_code.id 
            where
                patient.id = pdcs.patient_id and 
                pdcs.status='ACTIVE' AND
                diagnostic_code.code in (
                    '630', '631', '632', '633', '633.0', '633.00', '633.01', '633.1', '633.10', '633.11',
                    '633.2', '633.20', '633.21', '633.8', '633.80', '633.81', '633.9', '633.90', '633.91',
                    '634', '634.0', '634.00', '634.01', '634.02', '634.1', '634.10', '634.11', '634.12',
                    '634.2', '634.20', '634.21', '634.22', '634.3', '634.30', '634.31', '634.32', '634.4',
                    '634.40', '634.41', '634.42', '634.5', '634.50', '634.51', '634.52', '634.6', '634.60',
                    '634.61', '634.62', '634.7', '634.70', '634.71', '634.72', '634.8', '634.80', '634.81',
                    '634.82', '634.9', '634.90', '634.91', '634.92', '635', '635.0', '635.00', '635.01',
                    '635.02', '635.1', '635.10', '635.11', '635.12', '635.2', '635.20', '635.21', '635.22',
                    '635.3', '635.30', '635.31', '635.32', '635.4', '635.40', '635.41', '635.42', '635.5',
                    '635.50', '635.51', '635.52', '635.6', '635.60', '635.61', '635.62', '635.7', '635.70',
                    '635.71', '635.72', '635.8', '635.80', '635.81', '635.82', '635.9', '635.90', '635.91',
                    '635.92', '636', '636.0', '636.00', '636.01', '636.02', '636.1', '636.10', '636.11',
                    '636.12', '636.2', '636.20', '636.21', '636.22', '636.3', '636.30', '636.31', '636.32',
                    '636.4', '636.40', '636.41', '636.42', '636.5', '636.50', '636.51', '636.52', '636.6',
                    '636.60', '636.61', '636.62', '636.7', '636.70', '636.71', '636.72', '636.8', '636.80',
