ALTER FUNCTION dbo.nqf_24_1_3(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_24_2_1(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_24_2_1(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier,
    '24'(MAX),
    2,
    1,
    count(patient_id),
    count(has_bmi_percentile),
    0,
    count(patient_id) - count(has_bmi_percentile),
    100.00,
    safe_divide (count(has_bmi_percentile)* 100, count(patient_id))
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi,
        patient.id as patient_id,
        nullif(
            exists (
                select
                    ex2.id    
                from
                    doctor_provider as dp2
                    inner join exam as ex2 on dp2.id = ex2.doctor_provider_id
                    inner join exam_physical ep2 on ex2.id = ep2.exam_id
                where 
                    ex2.patient_id = patient.id and
                    dp2.national_provider_identifier = ex.dp_npi and
                    ex2.exam_date_of_service between $1 and $2 and
                    ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                    ep2.height is not null and
                    ep2.weight is not null and
                    ep2.height <> 0
            ) or exists(
                select
                    edmo2.id
                from 
                    doctor_provider as dp2
                    inner join exam as ex2 on dp2.id = ex2.doctor_provider_id
                    inner join exam_medical_decision as emd2 on ex2.id=emd2.exam_id
                    inner join exam_diagnosis_and_management_options as edmo2 on emd2.id=edmo2.exam_medical_decision_id
                    inner join diagnostic_code as dc2 on edmo2.diagnostic_code_id = dc2.id
                where
                    ex2.patient_id = patient.id and
                    dp2.national_provider_identifier = ex.dp_npi and
                    ex2.exam_date_of_service between $1 and $2 and
                    ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                    (upper(trim(dc2.code)) in ('V85.5', 'V85.51', 'V85.52', 'V85.53', 'V85.54'))
            ) or exists(
                select
                    odx2.diagnosis_id,
                    odx2.exam_medical_decision_id
                from 
                    doctor_provider as dp2
                    inner join exam as ex2 on dp2.id = ex2.doctor_provider_id
                    inner join exam_medical_decision as emd2 on ex2.id=emd2.exam_id
                    inner join exam_other_diagnosis_xref as odx2 on emd2.id=odx2.exam_medical_decision_id
                    inner join diagnostic_code as dc2 on odx2.diagnosis_id = dc2.id
                where
                    ex2.patient_id = patient.id and
                    dp2.national_provider_identifier = ex.dp_npi and
                    ex2.exam_date_of_service between $1 and $2 and
                    ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                    (upper(trim(dc2.code)) in ('V85.5', 'V85.51', 'V85.52', 'V85.53', 'V85.54'))
            ), false) as has_bmi_percentile
    from
        patient
        inner join (
            select distinct 
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                left join exam_medical_decision emd on exam.id=emd.exam_id
            where 
               (exam_date_of_service between $1 and $2) and
                exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                doctor_provider.national_provider_identifier = any ($3) and 
                (
                    exists (
                        select 
                            dcp.id
                        from
                            exam_diagnosis_and_management_options as edmo
                            left join diagnostic_code as dcp on edmo.diagnostic_code_id = dcp.id
                        where
                            emd.id=edmo.exam_medical_decision_id and
                            upper(trim(dcp.code)) in (
                               'V70.0', 'V70.3', 'V70.5', 'V70.6', 'V70.8', 'V70.9', 'V24', 'V25', 'V26',
                               'V27', 'V28', 'V45.5', 'V61.5', 'V61.6', 'V61.7', 'V69.2', 'V72.3', 'V72.4')
                    ) or exists (
                        select
                            dco.id
                        from    
                            exam_other_diagnosis_xref as odx 
                            left join diagnostic_code as dco on odx.diagnosis_id = dco.id
                        where
                            emd.id=odx.exam_medical_decision_id and
                            upper(trim(dco.code)) in (
                                'V70.0', 'V70.3', 'V70.5', 'V70.6', 'V70.8', 'V70.9', 'V24', 'V25', 'V26',
                                'V27', 'V28', 'V45.5', 'V61.5', 'V61.6', 'V61.7', 'V69.2', 'V72.3', 'V72.4')
                    ) or exists (
                        select 
                            emdc.id
                        from
                            exam_medical_decision_code as emdc
                        where
                            emd.id=emdc.exam_medical_decision_id and
                            trim(emdc.procedure_code) in (
                               '99201', '99202', '99203', '99204', '99205', '99211', '99212', '99213',
                               '99214', '99215', '99217', '99218', '99219', '99220', '99241', '99242',
                               '99243', '99244', '99245', '99341', '99342', '99343', '99344', '99345',
                               '99347', '99348', '99349', '99350', '99384', '99385', '99386', '99387',
                               '99394', '99395', '99396', '99397', '99401', '99402', '99403', '99404',
                               '99411', '99412', '99420', '99429', '99455', '99456')
                    )        
                ) and not (
                    exists (
                        select 
                            dcp.id
                        from
                            exam_diagnosis_and_management_options as edmo
                            left join diagnostic_code as dcp on edmo.diagnostic_code_id = dcp.id
                        where
                           emd.id=edmo.exam_medical_decision_id and
                           upper(trim(dcp.code)) in (
                               'V26.81', 'V28', 'V28.3', 'V28.81', 'V28.82', 'V72.4', 'V72.40', 'V72.41', 'V72.42')
                    ) or exists (
                        select
                           dco.id
                        from    
                           exam_other_diagnosis_xref as odx 
                           left join diagnostic_code as dco on odx.diagnosis_id = dco.id
                        where
                           emd.id=odx.exam_medical_decision_id and
                           upper(trim(dco.code)) in (
                               'V26.81', 'V28', 'V28.3', 'V28.81', 'V28.82', 'V72.4', 'V72.40', 'V72.41', 'V72.42')
                    )
                )) as ex on patient.id=ex.patient_id
        inner join patient_diagnostic_code_status pdcs on patient.id = pdcs.patient_id
        inner join diagnostic_code on pdcs.diagnostic_code_id = diagnostic_code.id           
    where
        extract('years' from age($1, patient.date_of_birth)) >= 2 and extract('years' from age($1, patient.date_of_birth)) <= 10 and not
        exists (
            SELECT 
                diagnostic_code.id
            from
                patient_diagnostic_code_status pdcs
                inner join diagnostic_code on pdcs.diagnostic_code_id = diagnostic_code.id 
            where
                patient.id = pdcs.patient_id and 
                pdcs.status='ACTIVE' AND
                diagnostic_code.code in (
                    '630', '631', '632', '633', '633.0', '633.00', '633.01', '633.1', '633.10', '633.11',
                    '633.2', '633.20', '633.21', '633.8', '633.80', '633.81', '633.9', '633.90', '633.91',
