ALTER FUNCTION dbo.nqf_24_3_3(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_27_1(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_27_1(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier,
    '27'(MAX),
    1,
    null,
    count(patient_id),
    count(has_smoking_status),
    0,
    count(patient_id) - count(has_smoking_status),
    100.00,
    safe_divide (count(has_smoking_status)* 100, count(patient_id))
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi, patient.id as patient_id, nullif(count(ex.smoking_status), 0) as has_smoking_status
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                nullif(
                    exists(
                        select
                            ex2.id,
                            ros2.respiratory_smoking_status_id
                        from
                            exam as ex2 
                            inner join exam_review_of_systems ros2 on ex2.id = ros2.exam_id
                        where 
                            ex2.patient_id = exam.patient_id and
                            ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                            (ex2.exam_date_of_service between $1 - '1 years'$2) and
                            (ros2.respiratory_smoking_status_id is not null and ros2.respiratory_smoking_status_id in (1, 2, 5)) 
                   ),
                   false) as smoking_status
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                inner join exam_medical_decision emd on exam.id=emd.exam_id
            where 
               (exam_date_of_service between $2 - '2 years'$2) and
                exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                doctor_provider.national_provider_identifier = any ($3) and
                (
                    exists (
                        select
                            emdc
                        from
                            exam_medical_decision_code emdc 
                        where
                            emd.id=emdc.exam_medical_decision_id and
                            trim(emdc.procedure_code) in (
                               '99201', '99202', '99203', '99204', '99205', '99211', '99212',
                               '99213', '99214', '99215', '99217', '99218', '99219', '99220',
                               '99241', '99242', '99243', '99244', '99245', '99341', '99342',
                               '99343', '99344', '99345', '99347', '99348', '99349', '99350',
                               '99384', '99385', '99386', '99387', '99394', '99395', '99396',
                               '99397', '99401', '99402', '99403', '99404', '99411', '99412',
                               '99420', '99429', '99455', '99456')
                    ) or exists(
                        select
                            edmo2.id
                        from 
                            exam_diagnosis_and_management_options as edmo2
                            inner join diagnostic_code as dc2 on edmo2.diagnostic_code_id = dc2.id
                        where
                            emd.id=edmo2.exam_medical_decision_id and
                            (upper(trim(dc2.code)) in ('V70.0', 'V70.3', 'V70.5', 'V70.6', 'V70.8', 'V70.9'))
                    ) or exists(
                        select
                            odx2.diagnosis_id,
                            odx2.exam_medical_decision_id
                        from 
                            exam_other_diagnosis_xref as odx2
                            inner join diagnostic_code as dc2 on odx2.diagnosis_id = dc2.id
                        where
                            emd.id=odx2.exam_medical_decision_id and
                            (upper(trim(dc2.code)) in ('V70.0', 'V70.3', 'V70.5', 'V70.6', 'V70.8', 'V70.9'))
                    )
                )) as ex on patient.id=ex.patient_id
    where
       extract('years' from age($1, patient.date_of_birth))>=17 
    group by 
        ex.dp_npi, patient.id) as measures
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
