ALTER FUNCTION dbo.nqf_27_2(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_28a(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_28a(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier,
    '28a'(MAX),
    null,
    null,
    count(patient_id),
    count(has_smoking_status),
    0,
    count(patient_id) - count(has_smoking_status),
    100.00,
    safe_divide (count(has_smoking_status)* 100, count(patient_id))
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi, patient.id as patient_id, nullif(count(ex.smoking_status), 0) as has_smoking_status
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                nullif(
                    exists(
                        select
                            ex2.id,
                            ros2.respiratory_smoking_status_id
                        from
                            exam as ex2 
                            inner join exam_review_of_systems ros2 on ex2.id = ros2.exam_id
                        where 
                            ex2.patient_id = exam.patient_id and 
                            (ex2.exam_date_of_service between exam.exam_date_of_service - '2 years'.exam_date_of_service) and
                            (ros2.respiratory_smoking_status_id is not null and ros2.respiratory_smoking_status_id <> 9)),
                   false) as smoking_status,
                exists(
                    select 
                        emdc3.id
                    from
                        exam as ex3
                        inner join exam_medical_decision emd3 on ex3.id=emd3.exam_id
                        inner join exam_medical_decision_code emdc3 on emd3.id=emdc3.exam_medical_decision_id
                    where
                        ex3.id = exam.id and
                        trim(emdc3.procedure_code) in (
                            '99401', '99402', '99403', '99404', '99385', '99386', '99387',
                            '99395', '99396', '99397', '99420', '99429', '99411', '99412')) as medication_counseling
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                inner join exam_medical_decision emd on exam.id=emd.exam_id
            where 
               (exam_date_of_service between $1 and $2) and
               (
                    ($5 is null and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed')) or 
                    ($5 is not null and 
                        (
                            (exam.id = $5 and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed', 'Draft')) or
                            (exam.id != $5 and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed'))
                        )
                    )
               ) and
                doctor_provider.national_provider_identifier = any ($3) and
                exists (
                    select
                        emdc
                    from
                        exam_medical_decision_code emdc 
                    where
                        emd.id=emdc.exam_medical_decision_id and
                        trim(emdc.procedure_code) in (
                           '96150', '96152', '97003', '97004', '99201', '99202', '99203',
                           '99204', '99205', '99212', '99213', '99214', '99215', '99411',
                           '99412', '99420', '99429', '99385', '99386', '99387', '99395',
                           '99396', '99397', '99401', '99402', '99403', '99404', '90801',
                           '90802', '90804', '90805', '90806', '90807', '90808', '90809',
                           '90810', '90811', '90812', '90813', '90814', '90815', '90845',
                           '90862'))) as ex on patient.id=ex.patient_id
    where
       ($4 is null and extract('years' from age($1, patient.date_of_birth))>=18) or
       ($4 is not null and patient.id = $4 and extract('years' from age($1, patient.date_of_birth))>=18)
    group by 
        ex.dp_npi, patient.id
    having
        count(distinct ex.id) >= 2 or
        count(nullif(medication_counseling, false)) >= 1) as measures 
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_28a(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_28b(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_28b(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier,
    '28b'(MAX),
    null,
    null,
    count(patient_id),
    count(has_smoking_cessation),
    0, count(patient_id) - count(has_smoking_cessation),
    100.00,
    safe_divide (count(has_smoking_cessation)* 100, count(patient_id))
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi,
        patient.id as patient_id,
        nullif(count(ex.smoking_cessation), 0) as has_smoking_cessation
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                nullif(
                    exists(
                        select 
                            emdc4.id
                        from
                            exam as ex4
                            inner join exam_medical_decision as emd4 on ex4.id=emd4.exam_id
                            inner join exam_medical_decision_code as emdc4 on emd4.id=emdc4.exam_medical_decision_id
                        where
                            ex4.patient_id = exam.patient_id and
                            
                            (
                            ($5 is null and ex4.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed')) or 
                            ($5 is not null and 
                                (
                                    (ex4.id = $5 and ex4.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed', 'Draft')) or
                                    (ex4.id != $5 and ex4.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed'))
                                )
                             )
                           ) and         
                            (ex4.exam_date_of_service between exam.exam_date_of_service - '2 years'.exam_date_of_service) and
                            trim(emdc4.procedure_code) in ('99406', '99407')
                    ) or exists (
                        select
                            rm.rcopia_id
                        from
                            rcopia_medication as rm
                            inner join rcopia_drug as rd on rm.sig_drug_rcopia_id = rd.rcopia_id
                        where
                            rm.deleted = false and
                            rm.patient_id = exam.patient_id and 
                            ((rm.stop_date >= exam.exam_date_of_service - '2 years'.stop_date < (exam.exam_date_of_service + '1 day')) or rm.stop_date is null) and
                            (rm.start_date < (exam.exam_date_of_service + '1 day') or rm.start_date is null) and
                            (rd.rx_norm in
                                ('105075', '198029', '198030', '198031', '198406', '198407', '199677',
                                 '227177', '250983', '311975', '314119', '359817', '359818', '388082', '636353') or 
                             rd.rx_norm_generic in
                                ('105075', '198029', '198030', '198031', '198406', '198407', '199677',
                                 '227177', '250983', '311975', '314119', '359817', '359818', '388082', '636353'))  
                    ) or exists (
                         select
                            rp.rcopia_id
                        from
                            rcopia_prescription as rp
                            inner join rcopia_drug as rd on rp.sig_drug_rcopia_id = rd.rcopia_id
                        where
                            rp.deleted = false and 
                            rp.patient_id = exam.patient_id and 
                            ((rp.stop_date >= exam.exam_date_of_service - '2 years'.stop_date < (exam.exam_date_of_service + '1 day')) or rp.stop_date is null) and
                            rp.signed_date < (exam.exam_date_of_service + '1 day') and
                            (rd.rx_norm in
                                ('105075', '198029', '198030', '198031', '198406', '198407', '199677',
                                 '227177', '250983', '311975', '314119', '359817', '359818', '388082', '636353') or 
                             rd.rx_norm_generic in
                                ('105075', '198029', '198030', '198031', '198406', '198407', '199677',
                                 '227177', '250983', '311975', '314119', '359817', '359818', '388082', '636353'))
                    ), false) as smoking_cessation,
                exists(
                    select 
                        emdc3.id
                    from
                        exam as ex3
                        inner join exam_medical_decision emd3 on ex3.id=emd3.exam_id
                        inner join exam_medical_decision_code emdc3 on emd3.id=emdc3.exam_medical_decision_id
                    where
                        ex3.id = exam.id and
                        trim(emdc3.procedure_code) in (
                            '99401', '99402', '99403', '99404', '99385', '99386', '99387',
                            '99395', '99396', '99397', '99420', '99429', '99411', '99412')) as medication_counseling,
                exists(
                    select
                        ex2.id,
                        ros2.respiratory_smoking_status_id
                    from
                        exam as ex2 
                        inner join exam_review_of_systems ros2 on ex2.id = ros2.exam_id
                    where 
                        ex2.patient_id = exam.patient_id and

                        (
                            ($5 is null and ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed')) or 
                            ($5 is not null and 
                                (
                                    (ex2.id = $5 and ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed', 'Draft')) or
                                    (ex2.id != $5 and ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed'))
                                )
                            )
                        ) and                       

                        (ex2.exam_date_of_service between exam.exam_date_of_service - '2 years'.exam_date_of_service) and
                        (ros2.respiratory_smoking_status_id is not null and ros2.respiratory_smoking_status_id in (1, 2, 5))) as denominator
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                inner join exam_medical_decision emd on exam.id=emd.exam_id
            where
               (exam_date_of_service between $1 and $2) and
               (
                    ($5 is null and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed')) or 
                    ($5 is not null and 
                        (
                            (exam.id = $5 and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed', 'Draft')) or
                            (exam.id != $5 and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed'))
                        )
                    )
                ) and
               doctor_provider.national_provider_identifier = any ($3) and 
               exists (
                   select
                       emdc.id 
                   from
                       exam_medical_decision_code as emdc
                   where
                       emd.id=emdc.exam_medical_decision_id and
                       trim(emdc.procedure_code) in (
                           '96150', '96152', '97003', '97004', '99201', '99202', '99203',
                           '99204', '99205', '99212', '99213', '99214', '99215', '99411',
                           '99412', '99420', '99429', '99385', '99386', '99387', '99395',
                           '99396', '99397', '99401', '99402', '99403', '99404', '90801',
                           '90802', '90804', '90805', '90806', '90807', '90808', '90809',
                           '90810', '90811', '90812', '90813', '90814', '90815', '90845',
                           '90862'))) as ex on patient.id=ex.patient_id
    where
       ($4 is null and extract('years' from age($1, patient.date_of_birth))>=18) or
       ($4 is not null and patient.id = $4 and extract('years' from age($1, patient.date_of_birth))>=18)
    group by 
        ex.dp_npi, patient.id
    having
        count(nullif(ex.denominator, false)) >= 1 and
        (
            count(distinct ex.id) >= 2 or
            count(nullif(medication_counseling, false)) >= 1
        )) as measures
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_28b(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_38_1(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_38_1(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier, 
    '38'(MAX), 
    null, 
    1, 
    count(patient_id), 
    count(has_immuniz), 
    count(is_excluded), 
    count(patient_id) - count(is_excluded) - count(has_immuniz), 
    100.00, 
    safe_divide (count(has_immuniz) * 100, ( (count(patient_id) - count(is_excluded) - count(has_immuniz)) + count(has_immuniz) ) )
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi, patient.id as patient_id, nullif(count(ex.immuniz), 0) as has_immuniz, nullif(count(ex.excluded), 0) as is_excluded
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                nullif(
                exists(
                    select
                        patient2.id
                    from
                        exam as ex2 
                        inner join exam_medical_decision emd2 on ex2.id = emd2.exam_id
                        inner join exam_medical_decision_code emdc2 on emd2.id=emdc2.exam_medical_decision_id
                        inner join patient patient2 on ex2.patient_id = patient2.id
                        where 
                            ex2.patient_id = exam.patient_id and 
                            (ex2.exam_date_of_service between patient2.date_of_birth + '42 days'.date_of_birth + '2 years'- '1 day') and
                            trim(emdc2.procedure_code) in ('90698', '90700', '90721', '90723')
                        group by patient2.id
                        having count(distinct ex2.id) >= 4        
                ) or
                exists(
                    select
                        patient2.id
                    from
                        rcopia_medication as rm2 
                        inner join rcopia_drug as rd2 on rm2.sig_drug_rcopia_id = rd2.rcopia_id
                        inner join patient as patient2 on rm2.patient_id = patient2.id
                        where 
                            rm2.patient_id = exam.patient_id and 
                            (rm2.start_date between patient2.date_of_birth + '42 days'.date_of_birth + '2 years'- '1 day') and
                            (trim(rd2.rx_norm) in (
                                '359454', '562372', '795926', '795930', '795938', '795939', '798309', '798347', '805375', 
                                '806587', '806593', '807415', '824542', '829894', '829971', '829987', '830518', '830549', 
                                '830555', '830893', '835879') or 
                             trim(rd2.rx_norm_generic) in (
                                '359454', '562372', '795926', '795930', '795938', '795939', '798309', '798347', '805375', 
                                '806587', '806593', '807415', '824542', '829894', '829971', '829987', '830518', '830549', 
                                '830555', '830893', '835879'))
                        group by patient2.id
                        having count(distinct rm2.rcopia_id) >= 4                
                ), false) as immuniz,  
                      
               nullif(
                exists(
                    select
                        ex3.id
                    from
                        exam as ex3 
                        inner join patient_diagnostic_code_status pdcs3 on ex3.patient_id = pdcs3.patient_id
                        inner join diagnostic_code dc3 on pdcs3.diagnostic_code_id = dc3.id
                    where 
                        ex3.patient_id = exam.patient_id and                        
                        pdcs3.status='ACTIVE' AND
                        dc3.code in ('323.51', '333.0')                                                
                 )
                 or
                 exists(
                    select
                        ra3.rcopia_id
                    from
                        rcopia_allergy as ra3 
                        inner join rcopia_drug as rd3 on ra3.rcopia_drug_id = rd3.rcopia_id
                        where 
                            ra3.patient_id = exam.patient_id and 
                            ra3.deleted = false and
                            (trim(rd3.rx_norm) in (
                                '359454', '562372', '795926', '795930', '795938', '795939', '798309', '798347', '805375', 
                                '806587', '806593', '807415', '824542', '829894', '829971', '829987', '830518', '830549', 
                                '830555', '830893', '835879') or 
                             trim(rd3.rx_norm_generic) in (
                                '359454', '562372', '795926', '795930', '795938', '795939', '798309', '798347', '805375', 
                                '806587', '806593', '807415', '824542', '829894', '829971', '829987', '830518', '830549', 
                                '830555', '830893', '835879'))
                ), false) as excluded       
                                 
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                inner join exam_medical_decision emd on exam.id=emd.exam_id
                inner join exam_medical_decision_code emdc on emd.id=emdc.exam_medical_decision_id
            where 
               (exam_date_of_service between $1 and $2) and
                exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                doctor_provider.national_provider_identifier = any ($3) and 
                (trim(emdc.procedure_code) in (
                    '99201', '99202', '99203', '99204', '99205', '99211', '99212', '99213', '99214', '99215', '99217', '99218', 
                    '99219', '99220', '99241', '99242', '99243', '99244', '99245', '99341', '99342', '99343', '99344', '99345', 
                    '99347', '99348', '99349', '99350', '99384', '99385', '99386', '99387', '99394', '99395', '99396', '99397', 
                    '99401', '99402', '99403', '99404', '99411', '99412', '99420', '99429', '99455', '99456'))) as ex on patient.id=ex.patient_id
    where
       extract('years' from age($1, patient.date_of_birth))>=1 and extract('years' from age($1, patient.date_of_birth))< 2
    group by 
        ex.dp_npi, patient.id) as measures 
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
