                        group by patient2.id
                        having count(distinct ex2.id) >= 3
                ) or
                exists(
                    select
                        patient2.id
                    from
                        rcopia_medication as rm2 
                        inner join rcopia_drug as rd2 on rm2.sig_drug_rcopia_id = rd2.rcopia_id
                        inner join patient as patient2 on rm2.patient_id = patient2.id
                        where 
                            rm2.patient_id = exam.patient_id and 
                            (rm2.start_date between patient2.date_of_birth and patient2.date_of_birth + '2 years'- '1 day') and
                            (trim(rd2.rx_norm) in ('310752', '310753', '310756', '606375', '763313') or 
                             trim(rd2.rx_norm_generic) in ('310752', '310753', '310756', '606375', '763313'))
                        group by patient2.id
                        having count(distinct rm2.rcopia_id) >= 3                
                ) 
                or 
                exists(
                    select
                        ex3.id
                    from
                        exam as ex3 
                        inner join patient_diagnostic_code_status pdcs3 on ex3.patient_id = pdcs3.patient_id
                        inner join diagnostic_code dc3 on pdcs3.diagnostic_code_id = dc3.id
                    where 
                        ex3.patient_id = exam.patient_id and                        
                        pdcs3.status in ('ACTIVE', 'RESOLVED') AND
                        dc3.code in ('070.2', '070.3', 'V02.61')                       
                ))
                and
                --38_6
                (exists(
                    select
                        patient2.id
                    from
                        exam as ex2 
                        inner join exam_medical_decision emd2 on ex2.id = emd2.exam_id
                        inner join exam_medical_decision_code emdc2 on emd2.id=emdc2.exam_medical_decision_id
                        inner join patient patient2 on ex2.patient_id = patient2.id
                        where 
                            ex2.patient_id = exam.patient_id and 
                            (ex2.exam_date_of_service between patient2.date_of_birth and patient2.date_of_birth + '2 years'- '1 day') and
                            trim(emdc2.procedure_code) in ('90710', '90716')
                ) or
                exists(
                    select
                        patient2.id
