                        group by patient2.id
                        having count(distinct rm2.rcopia_id) >= 4                
                )), false) as immuniz,  

               nullif(
               --38_1
                exists(
                    select
                        ex3.id
                    from
                        exam as ex3 
                        inner join patient_diagnostic_code_status pdcs3 on ex3.patient_id = pdcs3.patient_id
                        inner join diagnostic_code dc3 on pdcs3.diagnostic_code_id = dc3.id
                    where 
                        ex3.patient_id = exam.patient_id and                        
                        pdcs3.status='ACTIVE' AND
