                    '99219', '99220', '99241', '99242', '99243', '99244', '99245', '99341', '99342', '99343', '99344', '99345', 
                    '99347', '99348', '99349', '99350', '99384', '99385', '99386', '99387', '99394', '99395', '99396', '99397', 
                    '99401', '99402', '99403', '99404', '99411', '99412', '99420', '99429', '99455', '99456'))) as ex on patient.id=ex.patient_id
    where
       extract('years' from age($1, patient.date_of_birth))>=1 and extract('years' from age($1, patient.date_of_birth))< 2
    group by 
        ex.dp_npi, patient.id) as measures 
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_38_8(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_38_9(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_38_9(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier, 
    '38'(MAX), 
    null, 
    9, 
    count(patient_id), 
    count(has_immuniz), 
    count(is_excluded), 
    count(patient_id) - count(is_excluded) - count(has_immuniz), 
    100.00, 
    safe_divide (count(has_immuniz) * 100, ( (count(patient_id) - count(is_excluded) - count(has_immuniz)) + count(has_immuniz) ) )
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi, patient.id as patient_id, nullif(count(ex.immuniz), 0) as has_immuniz, nullif(count(ex.excluded), 0) as is_excluded
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                nullif(
                exists(
                    select
                        patient2.id
                    from
                        exam as ex2 
                        inner join exam_medical_decision emd2 on ex2.id = emd2.exam_id
                        inner join exam_medical_decision_code emdc2 on emd2.id=emdc2.exam_medical_decision_id
                        inner join patient patient2 on ex2.patient_id = patient2.id
                        where 
                            ex2.patient_id = exam.patient_id and 
                            (ex2.exam_date_of_service between patient2.date_of_birth + '42 days'.date_of_birth + '2 years'- '1 day') and
                            trim(emdc2.procedure_code) in ('90680', '90681')
                        group by patient2.id
                        having count(distinct ex2.id) >= 2
                ) or
                exists(
                    select
                        patient2.id
                    from
                        rcopia_medication as rm2 
                        inner join rcopia_drug as rd2 on rm2.sig_drug_rcopia_id = rd2.rcopia_id
                        inner join patient as patient2 on rm2.patient_id = patient2.id
                        where 
                            rm2.patient_id = exam.patient_id and 
                            (rm2.start_date between patient2.date_of_birth + '42 days'.date_of_birth + '2 years'- '1 day') and
                            (trim(rd2.rx_norm) in ('798297', '805576') or 
                             trim(rd2.rx_norm_generic) in ('798297', '805576'))
                        group by patient2.id
                        having count(distinct rm2.rcopia_id) >= 2                
                ), false) as immuniz,  
                      
               nullif(
                 exists(
                    select
                        ra3.rcopia_id
                    from
                        rcopia_allergy as ra3 
                        inner join rcopia_drug as rd3 on ra3.rcopia_drug_id = rd3.rcopia_id
                        where 
                            ra3.patient_id = exam.patient_id and 
                            ra3.deleted = false and                         
                            (trim(rd3.rx_norm) in ('798297', '805576') or 
                             trim(rd3.rx_norm_generic) in ('798297', '805576'))
                ), false) as excluded       
                                 
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                inner join exam_medical_decision emd on exam.id=emd.exam_id
                inner join exam_medical_decision_code emdc on emd.id=emdc.exam_medical_decision_id
            where 
               (exam_date_of_service between $1 and $2) and
                exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                doctor_provider.national_provider_identifier = any ($3) and 
                (trim(emdc.procedure_code) in (
                    '99201', '99202', '99203', '99204', '99205', '99211', '99212', '99213', '99214', '99215', '99217', '99218', 
                    '99219', '99220', '99241', '99242', '99243', '99244', '99245', '99341', '99342', '99343', '99344', '99345', 
                    '99347', '99348', '99349', '99350', '99384', '99385', '99386', '99387', '99394', '99395', '99396', '99397', 
                    '99401', '99402', '99403', '99404', '99411', '99412', '99420', '99429', '99455', '99456'))) as ex on patient.id=ex.patient_id
    where
       extract('years' from age($1, patient.date_of_birth))>=1 and extract('years' from age($1, patient.date_of_birth))< 2
    group by 
        ex.dp_npi, patient.id) as measures 
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_38_9(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_41(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_41(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier, 
    '41'(MAX), 
    null, 
    null, 
    count(patient_id), 
    count(has_influenza_vaccine), 
    count(is_excluded), 
    count(patient_id) - count(is_excluded) - count(has_influenza_vaccine), 
    100.00, 
    safe_divide (count(has_influenza_vaccine) * 100, ( (count(patient_id) - count(is_excluded) - count(has_influenza_vaccine)) + count(has_influenza_vaccine) ) )
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi, patient.id as patient_id, nullif(count(ex.influenza_vaccine), 0) as has_influenza_vaccine, nullif(count(ex.excluded), 0) as is_excluded
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                
                nullif(
                    exists(
                        select
                            ex2.id
                        from
                            exam as ex2 
                            inner join exam_medical_decision emd2 on ex2.id = emd2.exam_id
                            inner join exam_medical_decision_code emdc2 on emd2.id=emdc2.exam_medical_decision_id
                        where 
                            ex2.id = exam.id and 
                            (ex2.exam_date_of_service between $1 - '122 days'$1 + '58 days') 
                            and
                            trim(emdc2.procedure_code) in (
                                '90656', '90658', '90660', '90661', '90662', '90663', '90664', '90666', '90667', '90668') 
                            and
                            not
                            (
                                upper(trim(coalesce(emdc2.modifier_1, ''))) in ('1P', '2P', '3P') or
                                upper(trim(coalesce(emdc2.modifier_2, ''))) in ('1P', '2P', '3P') or
                                upper(trim(coalesce(emdc2.modifier_3, ''))) in ('1P', '2P', '3P') or
                                upper(trim(coalesce(emdc2.modifier_4, ''))) in ('1P', '2P', '3P') 
                            )                          
                    )
                    or
                    exists(
                        select
                            rm2.rcopia_id
                        from
                            rcopia_medication as rm2 
                            inner join rcopia_drug as rd2 on rm2.sig_drug_rcopia_id = rd2.rcopia_id
                        where 
                            rm2.patient_id = exam.patient_id and 
                            (rm2.start_date between $1 - '122 days'$1 + '58 days') and
                            (trim(rd2.rx_norm) in ('857924', '857942', '857965') or 
                             trim(rd2.rx_norm_generic) in ('857924', '857942', '857965'))                   
                    ), false) as influenza_vaccine,
                                   
               nullif(
                exists(
                    select
                        ex3.id
                    from
                        exam as ex3 
                        inner join patient_diagnostic_code_status pdcs3 on ex3.patient_id = pdcs3.patient_id
                        inner join diagnostic_code dc3 on pdcs3.diagnostic_code_id = dc3.id
                    where   
                        ex3.id = exam.id and                        
                        pdcs3.status='ACTIVE' and
                        dc3.code in ('V15.03')                             
                )                                       
                or 
                exists(
                    select
                        ra3.rcopia_id
                    from
                        rcopia_allergy as ra3 
                        inner join rcopia_drug as rd3 on ra3.rcopia_drug_id = rd3.rcopia_id
                    where 
                        ra3.patient_id = exam.patient_id and 
                        ra3.deleted = false and
                        (trim(rd3.rx_norm) in ('857924', '857942', '857965') 
                            or 
                        trim(rd3.rx_norm_generic) in ('857924', '857942', '857965'))
                )
                or 
                exists(
                    select
                        ex2.id
                    from
                        exam as ex2 
                        inner join exam_medical_decision emd2 on ex2.id = emd2.exam_id
                        inner join exam_medical_decision_code emdc2 on emd2.id=emdc2.exam_medical_decision_id
                    where 
                        ex2.id = exam.id and 
                        trim(emdc2.procedure_code) in (
                            '90656', '90658', '90660', '90661', '90662', '90663', '90664', '90666', '90667', '90668')   
                        and
                        (
                            upper(trim(coalesce(emdc2.modifier_1, ''))) in ('1P', '2P', '3P') or
                            upper(trim(coalesce(emdc2.modifier_2, ''))) in ('1P', '2P', '3P') or
                            upper(trim(coalesce(emdc2.modifier_3, ''))) in ('1P', '2P', '3P') or
                            upper(trim(coalesce(emdc2.modifier_4, ''))) in ('1P', '2P', '3P') 
                        )                                                       
                ), false) as excluded,    
                              
                nullif(exists(
                    select 
                        ex3.id
                    from
                        exam as ex3
                        inner join exam_medical_decision emd3 on ex3.id=emd3.exam_id
                        inner join exam_medical_decision_code emdc3 on emd3.id=emdc3.exam_medical_decision_id
                    where
                        ex3.id = exam.id and
                        trim(emdc3.procedure_code) in (                      
                            '99201', '99202', '99203', '99204', '99205', '99212', '99213', '99214', '99215', 
                            '99241', '99242', '99243', '99244', '99245', '99324', '99325', '99326', '99327', 
                            '99328', '99334', '99335', '99336', '99337', '99341', '99342', '99343', '99344', 
                            '99345', '99347', '99348', '99349', '99350')
                ), false) as encounter_outpatient,               
                
                                                               
                nullif(exists(
                    select 
                        ex3.id
                    from
                        exam as ex3
                        inner join exam_medical_decision emd3 on ex3.id=emd3.exam_id
                        inner join exam_medical_decision_code emdc3 on emd3.id=emdc3.exam_medical_decision_id
                    where
                        ex3.id = exam.id and
                        trim(emdc3.procedure_code) in (                      
                        '99386', '99387', '99396', '99397',
                        '99411', '99412',
                        '99401', '99402', '99403', '99404',
                        '99420', '99429',
                        '99304', '99305', '99306', '99307', '99308', '99309', '99310',
                        '99315', '99316')
                ), false) as encounter_other                     
                                    
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                inner join exam_medical_decision emd on exam.id=emd.exam_id
                inner join exam_medical_decision_code emdc on emd.id=emdc.exam_medical_decision_id
            where 
            
                exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and            
                doctor_provider.national_provider_identifier = any ($3) and            
                (   (exam_date_of_service <= $2 and
                    trim(emdc.procedure_code) in (
                    '99201', '99202', '99203', '99204', 
                    '99205', '99212', '99213', '99214', '99215', '99241', '99242', '99243', '99244', '99245', '99324', '99325', '99326', 
                    '99327', '99328', '99334', '99335', '99336', '99337', '99341', '99342', '99343', '99344', '99345', '99347', '99348', 
                    '99349', '99350',                
                    '99411', '99412',
                    '99401', '99402', '99403', '99404',
                    '99420', '99429',
                    '99304', '99305', '99306', '99307', '99308', '99309', '99310',
                    '99315', '99316'))
                    or
                    (exam_date_of_service <= $1 and
                    trim(emdc.procedure_code) in (
                    '99386', '99387', '99396', '99397'))
                )   
            ) as ex on patient.id=ex.patient_id
    where
       extract('years' from age($1, patient.date_of_birth))>=50  
    group by 
        ex.dp_npi, patient.id
    having
        count(ex.encounter_outpatient) >= 2 or
        count(ex.encounter_other) >= 1) as measures         
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
