                        ex5.id = exam.id 
                        and       
                        -- physical exam cpt codes
                        upper(trim(emdc5.procedure_code)) in ('99381', '99382', '99383', '99384', '99385',
                            '99386', '99387', '99388', '99389', '99390', '99391', '99392', '99393', '99394',
                            '99395', '99396', '99397') 
                        and
                        (
                            upper(trim(coalesce(emdc5.modifier_1, ''))) in ('1P', '2P', '3P') or
                            upper(trim(coalesce(emdc5.modifier_2, ''))) in ('1P', '2P', '3P') or
                            upper(trim(coalesce(emdc5.modifier_3, ''))) in ('1P', '2P', '3P') or
                            upper(trim(coalesce(emdc5.modifier_4, ''))) in ('1P', '2P', '3P') 
                        )                        
                    )
    
                )     
                and not exists(
                    select
                        ex4.id
                    from
                        exam as ex4 
                        inner join exam_physical ep4 on ex4.id = ep4.exam_id
                        left outer join exam_medical_decision emd4 on ex4.id = emd4.exam_id
                        left outer join exam_medical_decision_code emdc4 on emd4.id=emdc4.exam_medical_decision_id
