                        ex4.patient_id = exam.patient_id and    
                        (
                            ($5 is null and ex4.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed')) or 
                            ($5 is not null and 
                                (
                                    (ex4.id = $5 and ex4.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed', 'Draft')) or
                                    (ex4.id != $5 and ex4.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed'))
                                )
                            )
                         ) and              
                        (ex4.exam_date_of_service between exam.exam_date_of_service - '6 months'.exam_date_of_service) and
                        (
                            (bmi_nqf_421(ep4.height, ep4.weight, ep4.height_and_weight_metric) >= 22 and 
                                bmi_nqf_421(ep4.height, ep4.weight, ep4.height_and_weight_metric) < 30) or 
                            (bmi_nqf_421(ep4.height, ep4.weight, ep4.height_and_weight_metric) < 22 and 
                                trim(emdc4.procedure_code) in (
                                    '43644', '43645', '43770', '43771', '43772', '43773', '43774', 
                                    '43842', '43843', '43845', '43846', '43847', '43848', '97804', 
                                    '98961', '98962', '99078')) or
                            (bmi_nqf_421(ep4.height, ep4.weight, ep4.height_and_weight_metric) >= 30 and 
                                trim(emdc4.procedure_code) in (
                                    '43644', '43645', '43770', '43771', '43772', '43773', '43774', 
                                    '43842', '43843', '43845', '43846', '43847', '43848', '97804', 
                                    '98961', '98962', '99078'))                         
                        )
                 )
            , false) as excluded       
                                                
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                inner join exam_medical_decision emd on exam.id=emd.exam_id
                inner join exam_medical_decision_code emdc on emd.id=emdc.exam_medical_decision_id
            where 
                (exam_date_of_service between $1 and $2) and

                (
                    ($5 is null and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed')) or 
                    ($5 is not null and 
                        (
                            (exam.id = $5 and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed', 'Draft')) or
                            (exam.id != $5 and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed'))
                        )
                    )
                ) and               

                doctor_provider.national_provider_identifier = any ($3) and 
                (trim(emdc.procedure_code) in (
                    '90801', '90802', '90804', '90805', '90806', '90807', '90808', '90809', '97001', '97003', '97802', '97803', '98960', 
                    '99201', '99202', '99203', '99204', '99205', '99211', '99212', '99213', '99214', '99215', '99324', '99325', '99326', 
                    '99327', '99328', '99334', '99335', '99336', '99337', '99341', '99342', '99343', '99344', '99345', '99347', '99348', 
                    '99349', '99350'))) as ex on patient.id=ex.patient_id
    where
       ($4 is null and extract('years' from age($1, patient.date_of_birth))>=65) or
       ($4 is not null and patient.id = $4 and extract('years' from age($1, patient.date_of_birth))>=65)
    group by 
        ex.dp_npi, patient.id) as measures 
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_421_1(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_421_2(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_421_2(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier, 
    '421'(MAX), 
    2, 
    null, 
    count(patient_id), 
    count(has_bmi_mgt), 
    count(is_excluded), 
    count(patient_id) - count(is_excluded) - count(has_bmi_mgt), 
    100.00, 
    safe_divide (count(has_bmi_mgt) * 100, ( (count(patient_id) - count(is_excluded) - count(has_bmi_mgt)) + count(has_bmi_mgt) ) )
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi, patient.id as patient_id, nullif(count(ex.bmi_mgt), 0) as has_bmi_mgt, nullif(count(ex.excluded), 0) as is_excluded
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                nullif(exists(
                    select
                        ex2.id
                    from
                        exam as ex2 
                        inner join exam_physical ep2 on ex2.id = ep2.exam_id
                        left outer join exam_medical_decision emd2 on ex2.id = emd2.exam_id
