                            (bmi_nqf_421(ep4.height, ep4.weight, ep4.height_and_weight_metric) < 18.5 and 
                                trim(emdc4.procedure_code) in (
                                    '43644', '43645', '43770', '43771', '43772', '43773', '43774', 
                                    '43842', '43843', '43845', '43846', '43847', '43848', '97804', 
                                    '98961', '98962', '99078')) or
                            (bmi_nqf_421(ep4.height, ep4.weight, ep4.height_and_weight_metric) >= 25 and 
                                trim(emdc4.procedure_code) in (
                                    '43644', '43645', '43770', '43771', '43772', '43773', '43774', 
                                    '43842', '43843', '43845', '43846', '43847', '43848', '97804', 
                                    '98961', '98962', '99078'))                         
                        )
                 )
            , false) as excluded   
            
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                inner join exam_medical_decision emd on exam.id=emd.exam_id
                inner join exam_medical_decision_code emdc on emd.id=emdc.exam_medical_decision_id
            where 
               (exam_date_of_service between $1 and $2) and
                (
                    ($5 is null and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed')) or 
                    ($5 is not null and 
                        (
                            (exam.id = $5 and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed', 'Draft')) or
                            (exam.id != $5 and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed'))
                        )
                    )                
                ) and
                doctor_provider.national_provider_identifier = any ($3) and 
                (trim(emdc.procedure_code) in (
                    '90801', '90802', '90804', '90805', '90806', '90807', '90808', '90809', '97001', '97003', '97802', '97803', '98960', 
                    '99201', '99202', '99203', '99204', '99205', '99211', '99212', '99213', '99214', '99215', '99324', '99325', '99326', 
                    '99327', '99328', '99334', '99335', '99336', '99337', '99341', '99342', '99343', '99344', '99345', '99347', '99348', 
                    '99349', '99350'))
                    
                    
                    ) as ex on patient.id=ex.patient_id
    where
       ($4 is null and extract('years' from age($1, patient.date_of_birth))>=18 and extract('years' from age($1, patient.date_of_birth))<=64) or
       ($4 is not null and patient.id = $4 and extract('years' from age($1, patient.date_of_birth))>=18 and extract('years' from age($1, patient.date_of_birth))<=64)
    group by 
        ex.dp_npi, patient.id) as measures 
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_421_2(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_43(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_43(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier, 
    '43'(MAX), 
    null, 
    null, 
    count(patient_id), 
    count(has_immuniz), 
    0, 
    count(patient_id) - count(has_immuniz), 
    100.00, 
    safe_divide (count(has_immuniz) * 100, ( (count(patient_id) - count(has_immuniz)) + count(has_immuniz) ) )
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi, patient.id as patient_id, nullif(count(ex.immuniz), 0) as has_immuniz
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                nullif(
                exists(
                    select
                        ex2.id
                    from
                        exam as ex2 
                        inner join exam_medical_decision emd2 on ex2.id = emd2.exam_id
                        inner join exam_medical_decision_code emdc2 on emd2.id=emdc2.exam_medical_decision_id
                    where 
                        ex2.patient_id = exam.patient_id and 
                        ex2.exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                        trim(emdc2.procedure_code) in ('90669', '90670', '90732')
                ) or
                exists(
                    select
                        rm2.rcopia_id
                    from
                        rcopia_medication as rm2 
                        inner join rcopia_drug as rd2 on rm2.sig_drug_rcopia_id = rd2.rcopia_id
                    where 
                        rm2.patient_id = exam.patient_id and 
                        (trim(rd2.rx_norm) in (
                            '854931', '854933', '854935', '854937', '854939', '854941', '854943', '854945', '854947', 
                            '854949', '854951', '854953', '854955', '854957', '854959', '854961', '854963', '854965', 
                            '854967', '854969', '854971', '854973', '854975', '854977',
                            '854981') or 
                        trim(rd2.rx_norm_generic) in (
                             '854931', '854933', '854935', '854937', '854939', '854941', '854943', '854945', '854947', 
                            '854949', '854951', '854953', '854955', '854957', '854959', '854961', '854963', '854965', 
                            '854967', '854969', '854971', '854973', '854975', '854977',
                            '854981'))              
                ), false) as immuniz      
                                 
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                inner join exam_medical_decision emd on exam.id=emd.exam_id
                inner join exam_medical_decision_code emdc on emd.id=emdc.exam_medical_decision_id
            where 
               (exam_date_of_service between $2 - '1 year'$2) and
                exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed') and
                doctor_provider.national_provider_identifier = any ($3) and 
                (trim(emdc.procedure_code) in (
                    '99201', '99202', '99203', '99204', '99205', '99211', '99212', '99213', '99214', '99215', '99217', '99218', 
                    '99219', '99220', '99241', '99242', '99243', '99244', '99245', '99341', '99342', '99343', '99344', '99345', 
                    '99347', '99348', '99349', '99350', '99384', '99385', '99386', '99387', '99394', '99395', '99396', '99397', 
                    '99401', '99402', '99403', '99404', '99411', '99412', '99420', '99429', '99455', '99456'))
            ) as ex on patient.id=ex.patient_id
    where
       extract('years' from age($1, patient.date_of_birth))>=64
    group by 
        ex.dp_npi, patient.id) as measures 
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_43(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_86(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_86(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$                    
select 
    national_provider_identifier,
    '86'(MAX),
    null,
    null,
    count(patient_id),
    count(nullif(has_ophthalmic, false)),
    count(nullif(has_exclusion and not has_ophthalmic, false)),
    count(patient_id) - count(nullif(has_ophthalmic, false)) - count(nullif(has_exclusion and not has_ophthalmic, false)),
    100.00,
    safe_divide (count(nullif(has_ophthalmic, false))* 100, (count(patient_id)- count(nullif(has_exclusion and not has_ophthalmic, false))) )
from 
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi,
        patient.id as patient_id,
        CASE WHEN count(nullif(ex.ophthalmic, false)) <> 0 THEN true ELSE false END as has_ophthalmic,
        CASE WHEN count(nullif(ex.exclusion, false)) <> 0 THEN true ELSE false END as has_exclusion
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                exists (
                    select 
                        emdc.id
                    from
                        exam_medical_decision_code as emdc
                    where
                        emd.id=emdc.exam_medical_decision_id and
                        upper(trim(emdc.procedure_code)) in ('2027F') and not
                        (
                            upper(trim(coalesce(emdc.modifier_1, ''))) in ('1P', '2P', '8P') or
                            upper(trim(coalesce(emdc.modifier_2, ''))) in ('1P', '2P', '8P') or
                            upper(trim(coalesce(emdc.modifier_3, ''))) in ('1P', '2P', '8P') or
                            upper(trim(coalesce(emdc.modifier_4, ''))) in ('1P', '2P', '8P') 
                        )
               ) as ophthalmic,
               exists (
                    select 
                        emdc.id
                    from
                        exam_medical_decision_code as emdc
                    where
                        emd.id=emdc.exam_medical_decision_id and
                        upper(trim(emdc.procedure_code)) in ('2027F') and
                        (
                            upper(trim(coalesce(emdc.modifier_1, ''))) in ('1P', '2P', '8P') or
                            upper(trim(coalesce(emdc.modifier_2, ''))) in ('1P', '2P', '8P') or
                            upper(trim(coalesce(emdc.modifier_3, ''))) in ('1P', '2P', '8P') or
                            upper(trim(coalesce(emdc.modifier_4, ''))) in ('1P', '2P', '8P') 
                        )
               ) as exclusion
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id
                left join exam_medical_decision emd on exam.id=emd.exam_id
            where 
               (exam_date_of_service between $1 and $2) and
        
                (
                    ($5 is null and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed')) or 
                    ($5 is not null and 
                        (
                            (exam.id = $5 and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed', 'Draft')) or
                            (exam.id != $5 and exam_status in ('Invoiced' , 'Complete-NonBill' , 'Completed'))
                        )
                    )
                ) and
                
                doctor_provider.national_provider_identifier = any ($3) and 
                exists (
                        select 
                            emdc.id
                        from
                            exam_medical_decision_code as emdc
                        where
                            emd.id=emdc.exam_medical_decision_id and
                            trim(emdc.procedure_code) in (
                               '99324', '99325', '99326', '99327', '99328', '99334', '99335',
                               '99336', '99337', '99304', '99305', '99306', '99307', '99308',
                               '99309', '99310', '99201', '99202', '99203', '99204', '99205',
                               '99212', '99213', '99214', '99215', '99241', '99242', '99243',
                               '99244', '99245', '92002', '92004', '92012', '92014')
               )) as ex on patient.id=ex.patient_id
        inner join patient_diagnostic_code_status pdcs on patient.id = pdcs.patient_id
        inner join diagnostic_code on pdcs.diagnostic_code_id = diagnostic_code.id           
    where
        (
            ($4 is null and extract('years' from age($1, patient.date_of_birth))>=18) or
            ($4 is not null and patient.id = $4 and extract('years' from age($1, patient.date_of_birth))>=18)
        ) and
        exists (
            SELECT 
                diagnostic_code.id
            from
                patient_diagnostic_code_status pdcs
                inner join diagnostic_code on pdcs.diagnostic_code_id = diagnostic_code.id 
            where
                patient.id = pdcs.patient_id and 
                pdcs.status='ACTIVE' AND
                diagnostic_code.code in ('365.10', '365.11', '365.12', '365.15')) 
    group by 
        ex.dp_npi, patient.id
    having count(distinct ex.id) >= 2) as measures
    right join
        doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
    
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_86(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_88(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_88(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$
select 
    national_provider_identifier,
    '88'(MAX),
    null,
    null,
    count(patient_id),
    count(nullif(in_numerator and not in_exclusion, false)),
    count(nullif(in_exclusion, false)),
    count(patient_id) - count(nullif(in_numerator and not in_exclusion, false)) - count(nullif(in_exclusion, false)),
    100.00,
    safe_divide (count(nullif(in_numerator and not in_exclusion, false))* 100, count(patient_id))
from
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi,
        patient.id as patient_id,
        count(nullif(ex.numerator, false)) > 0 as in_numerator,
        count(nullif(ex.exclusion, false)) > 0 as in_exclusion
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                (
                    nqf_util_procedure_code_without_modifiers_check(exam.id, '2021F', ARRAY['1P', '2P', '8P']) and
                    (
                        (          
       						(
								exists(
                   					select
                        				ex2.id
                    				from
                        				exam as ex2 
                        				join exam_posterior_segment ps2 on ps2.exam_id = ex2.id
                    				where
                        				ps2.macula_edema_normal_od is true and
                        				ps2.macula_edema_normal_os is true and
                        				ex2.exam_date_of_service between $1 and exam.exam_date_of_service and
                        				ex2.patient_id = exam.patient_id and
                        				nqf_util_check_exam_status(ex2.id, ex2.exam_status, $5)
								)
								or 
                            	nqf_util_snomed_code_check(
                                	exam.patient_id,
                                	$1,
                               	 	exam.exam_date_of_service,
                                	ARRAY[193350004, 193387007, 232020009, 312911008, 312912001, 312920004, 312921000,
                                      312922007, 314010006, 314011005, 314014002, 314015001, 37231002, 399864000,
                                      408415007, 408416008, 414892004, 414908005, 420486006, 421779007, 432789001],
                                	$5) 
                 
               				)                 
                        and
                            nqf_util_snomed_code_check(
                                exam.patient_id,
                                $1,
                                exam.exam_date_of_service,
                                ARRAY[193349004, 312903003, 312904009, 312905005, 390834004, 408411003, 408412005],
                                $5) 
                        ) or (
                            nqf_util_snomed_code_check(
                                exam.patient_id,
                                $1,
                                exam.exam_date_of_service,
                                ARRAY[399872003, 399873008, 399874002, 399875001, 399877009],
                                $5) 
                        )
                    )          
                ) as numerator,
                nqf_util_procedure_code_with_modifiers_check(exam.id, '2021F', ARRAY['1P', '2P', '8P']) as exclusion
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id 
            where 
                (exam_date_of_service between $1 and $2) and
                nqf_util_check_exam_status(exam.id, exam.exam_status, $5) and       
                doctor_provider.national_provider_identifier = any ($3) and
                nqf_util_procedure_code_check(exam.id, ARRAY[
                            '99324', '99325', '99326', '99327', '99328', '99334', '99335', '99336',
                            '99337', '99304', '99305', '99306', '99307', '99308', '99309', '99310',
                            '99201', '99202', '99203', '99204', '99205, 99212', '99213', '99214',
                            '99215', '99241', '99242', '99243', '99244', '99245', '92002', '92004',
                            '92012', '92014'])
            ) as ex on patient.id=ex.patient_id
    where
        (
            ($4 is null and extract('years' from age($1, patient.date_of_birth))>=18) or
            ($4 is not null and patient.id = $4 and extract('years' from age($1, patient.date_of_birth))>=18)
        ) and
        nqf_util_diagnosis_check(patient.id, $1, $2, ARRAY['362.01', '362.02', '362.03', '362.04', '362.05', '362.06'])
    group by ex.dp_npi, patient.id having count(distinct ex.id) >= 2) as measures 
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_88(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_89(date, date, NVARCHAR(MAX)[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_89(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) RETURNS SETOF dbo.pqri_measure
    LANGUAGE sql
    AS $_$
select 
    national_provider_identifier,
    '89'(MAX),
    null,
    null,
    count(nullif(in_denominator, false)),
    count(nullif(in_denominator and in_numerator and not in_exclusion, false)),
    count(nullif(in_denominator and in_exclusion, false)),
    count(nullif(in_denominator, false)) - count(nullif(in_denominator and in_numerator and not in_exclusion, false)) - count(nullif(in_denominator and in_exclusion, false)),
    100.00,
    safe_divide (count(nullif(in_denominator and in_numerator and not in_exclusion, false))* 100, count(nullif(in_denominator, false)))
from
    (select                                         --the aggregate function count() does not count nulls (except count(*))
        ex.dp_npi as npi,
        patient.id as patient_id,
        count(nullif(ex.denominator, false)) > 0 as in_denominator,
        count(nullif(ex.numerator, false)) > 0 as in_numerator,
        count(nullif(ex.exclusion, false)) > 0 as in_exclusion
    from
        patient
        inner join (
            select
                exam.id as id,
                exam.patient_id as patient_id,
                doctor_provider.national_provider_identifier as dp_npi,
                nqf_util_procedure_code_without_modifiers_check(exam.id, '2021F', ARRAY['1P', '2P', '8P']) as denominator,
                nqf_util_procedure_code_without_modifiers_check(exam.id, '5010F', ARRAY['1P', '2P', '8P']) as numerator,
                nqf_util_procedure_code_with_modifiers_check(exam.id, '5010F', ARRAY['1P', '2P', '8P']) as exclusion
            from
                doctor_provider 
                inner join exam on doctor_provider.id = exam.doctor_provider_id 
            where 
                exam_date_of_service >= $1 and exam_date_of_service <= $2 and
                nqf_util_check_exam_status(exam.id, exam.exam_status, $5) and       
                doctor_provider.national_provider_identifier = any ($3) and
                nqf_util_procedure_code_check(exam.id, ARRAY['99324', '99325', '99326', '99327', '99328', '99334', '99335', '99336',
                            '99337', '99304', '99305', '99306', '99307', '99308', '99309', '99310',
                            '99201', '99202', '99203', '99204', '99205, 99212', '99213', '99214',
                            '99215', '99241', '99242', '99243', '99244', '99245', '92002', '92004',
                            '92012', '92014'])
            ) as ex on patient.id=ex.patient_id
    where
        (
            ($4 is null and extract('years' from age($1, patient.date_of_birth))>=18) or
            ($4 is not null and patient.id = $4 and extract('years' from age($1, patient.date_of_birth))>=18)
        ) and
        nqf_util_diagnosis_check(patient.id, $1, $2, ARRAY['362.01', '362.02', '362.03', '362.04', '362.05', '362.06'])
    group by ex.dp_npi, patient.id having count(distinct ex.id) >= 2) as measures 
    right join doctor_provider on measures.npi = doctor_provider.national_provider_identifier --all npis must be returned even if they have no data that matches the above query.
where 
    doctor_provider.national_provider_identifier = any ($3)
    and doctor_provider.is_active = true
group by national_provider_identifier
$_$
ALTER FUNCTION dbo.nqf_89(reporting_period_start date, reporting_period_end date, npis NVARCHAR(MAX)[], m_patient_id integer, m_exam_id integer) OWNER TO postgres
--
-- Name: nqf_util_check_exam_status(integer, NVARCHAR(MAX), integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_util_check_exam_status(exam_id integer, exam_status NVARCHAR(MAX), exam_id_exeption integer) RETURNS BIT
    LANGUAGE sql IMMUTABLE
    AS $_$select (
    ($3 is null and $2 in ('Invoiced' , 'Complete-NonBill' , 'Completed')) or 
    ($3 is not null and 
        (
            ($1 = $3 and $2 in ('Invoiced' , 'Complete-NonBill' , 'Completed', 'Draft')) or
            ($1 != $3 and $2 in ('Invoiced' , 'Complete-NonBill' , 'Completed'))
        )
    )
) as pass;$_$
ALTER FUNCTION dbo.nqf_util_check_exam_status(exam_id integer, exam_status NVARCHAR(MAX), exam_id_exeption integer) OWNER TO postgres
--
-- Name: nqf_util_diagnosis_check(integer, date, date, NVARCHAR(MAX)[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_util_diagnosis_check(patient_id integer, start_date date, end_date date, diagnoses NVARCHAR(MAX)[]) RETURNS BIT
    LANGUAGE sql STABLE
    AS $_$select exists (  
            select
                diagnostic_code.id
            from
                patient_diagnostic_code_status as pdcs
                inner join diagnostic_code on pdcs.diagnostic_code_id = diagnostic_code.id
            where
                $1 = pdcs.patient_id and
                pdcs.status='ACTIVE' AND
                diagnostic_code.code = any ($4)
) as pass$_$
ALTER FUNCTION dbo.nqf_util_diagnosis_check(patient_id integer, start_date date, end_date date, diagnoses NVARCHAR(MAX)[]) OWNER TO postgres
--
-- Name: nqf_util_diagnosis_check(integer, date, date, NVARCHAR(MAX)); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_util_diagnosis_check(patient_id integer, start_date date, end_date date, nqf_number NVARCHAR(MAX)) RETURNS BIT
    LANGUAGE sql STABLE
    AS $_$
select exists (  
             select
                pdcs.id, diagnostic_code.id as diag_id, diagnostic_code.code, cc.code, cm.nqf_number as nqf,

		coalesce(onset_date, '-infinity'), 
		case when status = 'ACTIVE' 
			then '-infinity'.diagnostic_code_id = diagnostic_code.id,
                cms_codes cc, cms_measure cm 
                
            where
                $1 = pdcs.patient_id 
                and pdcs.status='ACTIVE' 
                AND cm.nqf_number = $4 and cm.id(MAX) = ANY((select (regexp_split_to_array(cc.cms_measure_ids,  '; ')))(MAX)[]) 
				and diagnostic_code.code = cc.code
				and ((last_modified_date >= $2 and last_modified_date <= $3) or last_modified_date = '-infinity') 
				and ((onset_date >= $2 and onset_date <= $3) or onset_date = '-infinity')  
) as pass$_$
ALTER FUNCTION dbo.nqf_util_diagnosis_check(patient_id integer, start_date date, end_date date, nqf_number NVARCHAR(MAX)) OWNER TO postgres
