-- Name: nqf_util_snomed_code_check(integer, date, date, integer[], integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.nqf_util_snomed_code_check(patient_id integer, finding_start date, finding_end date, snomed integer[], exam_exception integer) RETURNS BIT
    LANGUAGE sql STABLE
    AS $_$select   exists(
                   select
                        ex2.id,
                        em2.id
                    from
                        exam as ex2 
                        join exam_posterior_segment ps2 on ps2.exam_id = ex2.id
                        left join exam_macula_edema as em2 on em2.id = ps2.macula_edema_od_id
                    where
                        em2.snomed = any ($4) and
                        ex2.exam_date_of_service between $2 and $3 and
                        ex2.patient_id = $1 and
                        nqf_util_check_exam_status(ex2.id, ex2.exam_status, $5)
                )
                or exists (
                    select
                        ex2.id,
                        em2.id
                    from
                        exam as ex2 
                        join exam_posterior_segment ps2 on ps2.exam_id = ex2.id
                        left join exam_macula_edema as em2 on em2.id = ps2.macula_edema_os_id
                    where
                        em2.snomed = any ($4) and
                        ex2.exam_date_of_service between $2 and $3 and
                        ex2.patient_id = $1 and
                        nqf_util_check_exam_status(ex2.id, ex2.exam_status, $5)
                )
                or exists(
                    select
                        ex2.id,
                        ret2.id
                    from
                        exam as ex2 
                        join exam_posterior_segment ps2 on ps2.exam_id = ex2.id
                        left join exam_retinopathy as ret2 on ret2.id = ps2.retinopathy_od_id
                    where
                        ret2.snomed = any ($4) and
                        ex2.exam_date_of_service between $2 and $3 and
                        ex2.patient_id = $1 and
                        nqf_util_check_exam_status(ex2.id, ex2.exam_status, $5)
                )
                or exists (
                    select
                        ex2.id,
                        ret2.id
                    from
                        exam as ex2 
                        join exam_posterior_segment ps2 on ps2.exam_id = ex2.id
                        left join exam_retinopathy as ret2 on ret2.id = ps2.retinopathy_os_id
                    where
                        ret2.snomed = any ($4) and
                        ex2.exam_date_of_service between $2 and $3 and
                        ex2.patient_id = $1 and
                        nqf_util_check_exam_status(ex2.id, ex2.exam_status, $5)
                )
$_$
