--
-- Name: patient_known_allergies(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.patient_known_allergies() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
	DECLARE
		num_allergies_query NVARCHAR(MAX)
		num_allergies INTEGER
		patient_id INTEGER
   	BEGIN
		IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
			patient_id = NEW.patient_id
		ELSIF TG_OP = 'DELETE' THEN
			patient_id = OLD.patient_id
		END IF
		num_allergies_query := 'SELECT COUNT(*) FROM rcopia_allergy WHERE patient_id = ' || patient_id || ' AND deleted = false AND lower(allergen_name) != '|| quote_literal('nkda')
		EXECUTE num_allergies_query INTO num_allergies
		IF (num_allergies > 0) THEN
			EXECUTE 'UPDATE patient SET known_allergies = TRUE WHERE id = ' || patient_id 
		ELSE
			EXECUTE 'UPDATE patient SET known_allergies = FALSE WHERE id = ' || patient_id 
		END IF
        		RETURN NULL
	 END
$$
ALTER FUNCTION dbo.patient_known_allergies() OWNER TO postgres
--
-- Name: patient_known_medications(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.patient_known_medications() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
        num_medications_query NVARCHAR(MAX)
        num_medications INTEGER
        patient_id INTEGER
    BEGIN
        IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
            patient_id = NEW.patient_id
        ELSIF TG_OP = 'DELETE' THEN
            patient_id = OLD.patient_id
        END IF
        IF (patient_id IS NULL) THEN
            RETURN NULL
        END IF
        num_medications_query := 'SELECT COUNT(*) FROM rcopia_medication WHERE patient_id = ' || patient_id || ' AND deleted = false'
        EXECUTE num_medications_query INTO num_medications
        IF (num_medications > 0) THEN
            EXECUTE 'UPDATE patient SET known_medications = TRUE WHERE id = ' || patient_id 
        ELSE
            EXECUTE 'UPDATE patient SET known_medications = FALSE WHERE id = ' || patient_id 
        END IF
                RETURN NULL
     END
$$
ALTER FUNCTION dbo.patient_known_medications() OWNER TO postgres
--
-- Name: patient_known_problems(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.patient_known_problems() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
	DECLARE
		num_problems_query NVARCHAR(MAX)
		num_problems INTEGER
		patient_id INTEGER
   	BEGIN
	
		IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
			patient_id = NEW.patient_id
		ELSIF TG_OP = 'DELETE' THEN
			patient_id = OLD.patient_id
		END IF
		num_problems_query := 'SELECT COUNT(*) FROM patient_diagnostic_code_status pdcs INNER JOIN diagnostic_code dc on pdcs.diagnostic_code_id = dc.id WHERE pdcs.patient_id = ' || patient_id || ' AND pdcs.status in (' || quote_literal('ACTIVE') || ')'
		EXECUTE num_problems_query INTO num_problems
		IF (num_problems > 0) THEN
		
			-- There are diagnoses (i.e. problems) that are ACTIVE
			
			num_problems_query := 'SELECT COUNT(*) FROM patient_diagnostic_code_status pdcs INNER JOIN diagnostic_code dc on pdcs.diagnostic_code_id = dc.id WHERE pdcs.patient_id = ' || patient_id || ' AND pdcs.status in (' || quote_literal('ACTIVE') || 
			') AND (dc.diagnostic_code_type != 0 OR dc.code != ' || quote_literal('V65.5') || ')'
			EXECUTE num_problems_query INTO num_problems
			IF (num_problems > 0) THEN
				-- There is at least one diagnosis other than ICD-9 No diagnosis made
				EXECUTE 'UPDATE patient SET known_problems = TRUE WHERE id = ' || patient_id 
			ELSE
				-- The only diagnoses are ICD-9 No diagnosis made
				EXECUTE 'UPDATE patient SET known_problems = FALSE WHERE id = ' || patient_id 
			END IF
		ELSE
			-- There are no ACTIVE diagnoses, so see if there are any other diagnoses (RESOLVED, INACTIVE, DELETED)
		
			num_problems_query := 'SELECT COUNT(*) FROM patient_diagnostic_code_status pdcs INNER JOIN diagnostic_code dc on pdcs.diagnostic_code_id = dc.id WHERE pdcs.patient_id = ' || patient_id || ' AND pdcs.status not in (' || quote_literal('ACTIVE') || ')'
			EXECUTE num_problems_query INTO num_problems
			IF (num_problems > 0) THEN
				-- There are only non-ACTIVE diagnoses so no matter what they are, consider this a representation of Known Problems = FALSE
				EXECUTE 'UPDATE patient SET known_problems = FALSE WHERE id = ' || patient_id 
			END IF
		END IF
        RETURN NULL
	 END
$$
ALTER FUNCTION dbo.patient_known_problems() OWNER TO postgres
