-- Name: pd_array_remove(anyarray, anyelement); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.pd_array_remove(a anyarray, element anyelement) RETURNS anyarray
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE 
    result a%TYPE
BEGIN
SELECT ARRAY(
    SELECT b.e FROM (SELECT pd_unnest(a)) AS b(e) WHERE b.e <> element) INTO result
RETURN result
END
$$
