-- Name: populate_claim_response_set_au_pair_table(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.populate_claim_response_set_au_pair_table() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
	crs RECORD
	maxInvId INTEGER
BEGIN
	
	maxInvId := 0
	FOR crs IN SELECT * FROM claim_response_set LOOP
		
		IF crs.id > maxInvId THEN
			maxInvId := crs.id
		END IF
		INSERT INTO claim_response_set_au_pair (claim_response_set_au_pair_id, current_claim_response_set_id) VALUES (crs.id, crs.id)
		UPDATE claim_response_set SET claim_response_set_au_pair_id = crs.id WHERE claim_response_set.id = crs.id
	END LOOP
	PERFORM setval('claim_response_set_au_pair_id_seq', maxInvId + 1, true)
END
$$
ALTER FUNCTION dbo.populate_claim_response_set_au_pair_table() OWNER TO postgres
--
-- Name: populate_invoice_parent_table(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.populate_invoice_parent_table() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
	invParId INTEGER
	inv RECORD
	maxInvId INTEGER
BEGIN
	
	maxInvId := 0
	FOR inv IN SELECT * FROM invoice LOOP
		
		IF inv.id > maxInvId THEN
			maxInvId := inv.id
		END IF
		INSERT INTO invoice_parent (invoice_parent_id, current_invoice_id, patient_id) VALUES (inv.id, inv.id, inv.patient_id)
		UPDATE invoice SET invoice_parent_id = inv.id WHERE invoice.id = inv.id
	END LOOP
	PERFORM setval('invoice_parent_id_seq', maxInvId + 1, true)
END
$$
