--
-- Name: post_financial_transactions(NVARCHAR(MAX), NVARCHAR(MAX), integer, NVARCHAR(MAX), integer, NVARCHAR(MAX), NVARCHAR(MAX)); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.post_financial_transactions(financial_transactions NVARCHAR(MAX), amount NVARCHAR(MAX), the_user integer, source_type NVARCHAR(MAX), source_id integer, action_type NVARCHAR(MAX), description NVARCHAR(MAX)) RETURNS integer
    LANGUAGE plpgsql
    AS $_$

DECLARE
	f_transaction integer[]; -- the financial transaction id
	amt numeric[]; -- the debited amounts
	source_user alias for $3; -- the user
	source_type alias for $4; -- the source type (invoice, payment, credit etc.)
	source_id alias for $5; -- the source id
	action_type alias for $6; -- the action type (add, edit, delete)
	action_description alias for $7; -- the action desciption for flexible situations


	r record; -- the financial transaction record
	credit_acc record; -- record for credit account
	debit_acc record; -- record for debit accunt

	temp_acc_record record; -- record for the tempoary account table
	array_index integer
	i integer
BEGIN
	f_transaction:= string_to_array($1, ',')
	amt:= string_to_array($2, ',')
	raise notice 'trans: %', f_transaction
	-- create a temporary table for us to perform calculations
	create table temp_account(
		account_number integer not null primary key,
		account_name NVARCHAR(MAX),
		balance numeric(11, 2) default 0
	);
	insert into general_journal (id, entry_date, source_type, source_id, action_type, user, description)
	values (nextval('general_journal_id_seq'), GETDATE(), source_type, source_id, action_type, source_user, action_description)
	array_index:=1
	foreach i in ARRAY f_transaction
	loop
		raise notice 'i = %' , i
		select * into r from financial_transaction where financial_transaction_id = i
		-- raise notice 'amount[%] = %', array_index, amt[array_index]
		-- debit
		select * into debit_acc from account where r.financial_transaction_debit_account = account_number
		-- update account balance for debit account
		update account set account_balance = account_balance + amt[array_index] where r.financial_transaction_debit_account = account_number
		-- add the debit ammount for the general journal
		if exists(  select * from temp_account where r.financial_transaction_debit_account = account_number) then
			-- sum the amount for this account
			update temp_account set balance = balance + amt[array_index] where r.financial_transaction_debit_account = account_number
		else
			-- insert the account into the temp_account table for further calculations
			insert into temp_account(account_number, account_name, balance)
			values (debit_acc.account_number, debit_acc.account_name, amt[array_index])
		end if
		--select * into temp_acc_record from temp_account where r.financial_transaction_debit_account = account_number 
		--raise notice 'temp acc record %', temp_acc_record
		-- credit
		select * into credit_acc from account where r.financial_transaction_credit_account = account_number
		-- update account balance for credit account
		update account set account_balance = account_balance - amt[array_index] where r.financial_transaction_credit_account = account_number
		-- subtract the credit ammount for the general journal
		if exists(  select * from temp_account where r.financial_transaction_credit_account = account_number) then
			-- sum the amount for this account
			update temp_account set balance = balance - amt[array_index] where r.financial_transaction_credit_account = account_number
		else
			-- insert the account into the temp_account table for further calculations
			insert into temp_account(account_number, account_name, balance)
			values (credit_acc.account_number, credit_acc.account_name, -amt[array_index])
		end if
		--select * into temp_acc_record from temp_account where r.financial_transaction_credit_account = account_number 
		--raise notice 'temp acc record %', temp_acc_record
		array_index:=array_index+1
	end loop
	-- print out the summary table
	for temp_acc_record in select * from temp_account
	loop
		raise notice 'temp acc number % balance %', temp_acc_record.account_number, temp_acc_record.balance
		if temp_acc_record.balance > 0
		then
			-- insert into general journal
			insert into general_journal_transactions (id, journal_entry_id, account_number, account_description, account_type, amount)
			values (nextval('general_journal_transactions_id_seq'), (select max(id) from general_journal), temp_acc_record.account_number, temp_acc_record.account_name, 0, temp_acc_record.balance)
		elseif temp_acc_record.balance < 0 then
			insert into general_journal_transactions (id, journal_entry_id, account_number, account_description, account_type, amount)
			values (nextval('general_journal_transactions_id_seq'), (select max(id) from general_journal), temp_acc_record.account_number, temp_acc_record.account_name, 1, -temp_acc_record.balance)
		end if
	end loop
	drop table temp_account
	return 0; -- return a dummy integer because hibernate does not like void (see http://stackoverflow.com/questions/16883669/call-a-postgres-function-via-hibernate)
END
$_$
