--
-- Name: post_financial_transactions(NVARCHAR(MAX), NVARCHAR(MAX), NVARCHAR(MAX), integer, NVARCHAR(MAX), integer, NVARCHAR(MAX), NVARCHAR(MAX)); Type: FUNCTION; Schema: public; Owner: postgres
