CREATE FUNCTION dbo.post_financial_transactions(debit_accounts NVARCHAR(MAX), credit_accounts NVARCHAR(MAX), amounts NVARCHAR(MAX), the_user integer, source_type NVARCHAR(MAX), source_id integer, action_type NVARCHAR(MAX), description NVARCHAR(MAX)) RETURNS integer
    LANGUAGE plpgsql
    AS $_$

DECLARE
	debit_accounts_array integer[]
	credit_accounts_array integer[]
	amounts_arrary numeric[]
	source_user alias for $4; -- the user
	source_type alias for $5; -- the source type (invoice, payment, credit etc.)
	source_id alias for $6; -- the source id
	action_type alias for $7; -- the action type (add, edit, delete)
	action_description alias for $8; -- the action desciption for flexible situations

	general_journal_id integer; -- primary key for the general journal
	account_holder record; -- record holder for debit/credit accounts
	general_journal_account_type integer; -- holder for the account type for general journal transaction

BEGIN
	debit_accounts_array:= string_to_array($1, ',')
	credit_accounts_array:= string_to_array($2, ',')
	amounts_arrary:= string_to_array($3, ',')
	--raise notice 'Debits: %', debit_accounts_array
	--raise notice 'Credits: %', credit_accounts_array
	--raise notice 'Ammounts: %', amounts_arrary
	-- create a temporary table for us to perform calculations
	create temporary table temporary_account_table (
		account_number integer not null primary key,
		account_name NVARCHAR(MAX),
		account_balance numeric(11, 2) default 0
	)
	SELECT nextval('general_journal_id_seq') INTO general_journal_id
	--raise notice 'general_journal_id: %', general_journal_id
	insert into general_journal (id, entry_date, source_type, source_id, action_type, user, description)
	values (general_journal_id, GETDATE(), source_type, source_id, action_type, source_user, action_description)
	-- Processing Debit Accounts
	--raise notice 'Processing Debit Accounts'
	FOR i in 1 .. array_length(debit_accounts_array, 1) LOOP

		-- Get account
		--raise notice 'Looking up Account: %', debit_accounts_array[i]
		select * into account_holder from account where account_number = debit_accounts_array[i]
		--raise notice 'Account Found: %', account_holder
		-- update account balance for account
		IF (select is_debit_normal_balance (debit_accounts_array[i])) THEN
				raise notice 'Debiting debit(+) account: %', credit_accounts_array[i]
				update account set account_balance = account_balance + amounts_arrary[i] where account_number = debit_accounts_array[i]
		ELSE
				raise notice 'Debiting credit(-) account: %', credit_accounts_array[i]
				update account set account_balance = account_balance - amounts_arrary[i] where account_number = debit_accounts_array[i]
		END IF
		-- Maintain running total
		if exists(select * from temporary_account_table where account_number = debit_accounts_array[i]) then
			-- sum the amount for this account
			--raise notice 'Update Temp: %', debit_accounts_array[i]
			update temporary_account_table set account_balance = account_balance + amounts_arrary[i] where account_number = debit_accounts_array[i]
		else
			-- insert the account into the temporary_account_table table for further calculations
			--raise notice 'Insert Temp: %', debit_accounts_array[i]
			INSERT INTO temporary_account_table (account_number, account_name, account_balance)
			VALUES (account_holder.account_number, account_holder.account_name, amounts_arrary[i])
		end if
	END LOOP
	-- Processing Credit Accounts
	--raise notice 'Processing Credit Accounts'
	FOR i in 1 .. array_length(credit_accounts_array, 1) LOOP

		-- Get account
		--raise notice 'Looking up Account: %', credit_accounts_array[i]
		select * into account_holder from account where account_number = credit_accounts_array[i]
		--raise notice 'Account Found: %', account_holder
		-- update account balance for account
		IF (select is_debit_normal_balance (credit_accounts_array[i])) THEN
				raise notice 'Crediting debit(-) account: %', credit_accounts_array[i]
				update account set account_balance = account_balance - amounts_arrary[i] where account_number = credit_accounts_array[i]
		ELSE
				raise notice 'Crediting credit(+) account%', credit_accounts_array[i]
				update account set account_balance = account_balance + amounts_arrary[i] where account_number = credit_accounts_array[i]
		END IF
		-- Maintain running total
		if exists(select * from temporary_account_table where account_number = credit_accounts_array[i]) then
			-- sum the amount for this account
			--raise notice 'Update Temp: %', credit_accounts_array[i]
			update temporary_account_table set account_balance = account_balance - amounts_arrary[i] where account_number = credit_accounts_array[i]
		else
			-- insert the account into the temporary_account_table table for further calculations
			--raise notice 'Insert Temp: %', credit_accounts_array[i]
			INSERT INTO temporary_account_table (account_number, account_name, account_balance)
			VALUES (account_holder.account_number, account_holder.account_name, -amounts_arrary[i])
		end if
	END LOOP
	-- Processing General Journal Transaction
	--raise notice 'Processing temporary_account_table into general_journal_transactions'
	FOR account_holder IN select * from temporary_account_table LOOP
		--raise notice 'Processing Account: %', account_holder
		IF account_holder.account_balance > 0 THEN
			general_journal_account_type:=0
-- 		ELSEIF account_holder.account_balance < 0 then
			general_journal_account_type:=1
		end if
		-- insert into general journal
		insert into general_journal_transaction (id, journal_entry_id, account_number, account_description, account_type, amount)
		values (nextval('general_journal_transaction_id_seq'), general_journal_id, account_holder.account_number, account_holder.account_name, general_journal_account_type, ABS(account_holder.account_balance))
	END LOOP
	drop table temporary_account_table
	return 0; -- return a dummy integer because hibernate does not like void (see http://stackoverflow.com/questions/16883669/call-a-postgres-function-via-hibernate)

	END
$_$
