CREATE FUNCTION dbo.post_financial_transactions(debit_accounts NVARCHAR(MAX), credit_accounts NVARCHAR(MAX), amounts NVARCHAR(MAX), the_user integer, source_type NVARCHAR(MAX), source_id integer, action_type NVARCHAR(MAX), description NVARCHAR(MAX), reference_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$

DECLARE
	debit_accounts_array integer[]
