--
-- Name: recreate_views(NVARCHAR(MAX), NVARCHAR(MAX)[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.recreate_views(run_me NVARCHAR(MAX), VARIADIC views NVARCHAR(MAX)[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  view_defs NVARCHAR(MAX)[]
  i integer
  def NVARCHAR(MAX)
BEGIN
  for i in array_lower(views,1) .. array_upper(views,1) loop
    select definition into def from pg_views where viewname = views[i]
    view_defs[i] := def
    EXECUTE 'DROP VIEW ' || views[i]
  end loop
  EXECUTE run_me
  for i in reverse array_upper(views,1) .. array_lower(views,1) loop
    def = 'CREATE OR REPLACE VIEW ' || quote_ident( views[i] ) || ' AS ' || view_defs[i]
    EXECUTE def
  end loop
END
$$
ALTER FUNCTION dbo.recreate_views(run_me NVARCHAR(MAX), VARIADIC views NVARCHAR(MAX)[]) OWNER TO postgres
--
-- Name: refresh_credit_remaining(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.refresh_credit_remaining(target_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$

DECLARE
  debt_id alias for $1; -- the user
  positive numeric
  negative numeric
  reversed BIT
BEGIN
  
  reversed:= (SELECT COUNT(*)>0 FROM credit AS revOf WHERE revOf.reversal_of = debt_id); -- if a reversal exists
  
  IF reversed 
  THEN
    update credit set remaining = 0 where credit_id = debt_id
  ELSE
    positive:= COALESCE( (select sum(adj.amount) from credit_adjustment as adj where adj.source_credit = debt_id and adj.reversal_of is null), 0)
    negative:= COALESCE( (select sum(adj.amount) from credit_adjustment as adj where adj.source_credit = debt_id and adj.reversal_of is not null), 0)
    update credit set remaining = (amount -positive + negative) where credit_id = debt_id
  END if
  return 0; -- return a dummy integer because hibernate does not like void (see http://stackoverflow.com/questions/16883669/call-a-postgres-function-via-hibernate)
END
$_$
ALTER FUNCTION dbo.refresh_credit_remaining(target_id integer) OWNER TO postgres
--
-- Name: refresh_gift_certificate_remaining(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.refresh_gift_certificate_remaining(target_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$

DECLARE
  positive numeric
  negative numeric
  debt_id alias for $1; -- the user
  remainingAmt numeric
BEGIN
  positive:= COALESCE( (select sum(adj.amount) from gift_certificate_adjustment as adj where adj.source_gift_certificate = debt_id and adj.reversal_of is null), 0)
  negative:= COALESCE( (select sum(adj.amount) from gift_certificate_adjustment as adj where adj.source_gift_certificate = debt_id and adj.reversal_of is not null), 0)
  update gift_certificate set remaining = (amount -positive + negative) where id = debt_id
  select remaining into remainingAmt from gift_certificate where id = debt_id
  if remainingAmt <= 0
  then
    update gift_certificate set status = 'CLOSED' where id = debt_id
    end if
  return 0; -- return a dummy integer because hibernate does not like void (see http://stackoverflow.com/questions/16883669/call-a-postgres-function-via-hibernate)
END
$_$
ALTER FUNCTION dbo.refresh_gift_certificate_remaining(target_id integer) OWNER TO postgres
--
-- Name: refresh_invoice_balance(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.refresh_invoice_balance(inv integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$

DECLARE
  inv_id alias for $1; -- the invoice id
  inv_line record; -- invoice line
  inv_line_adjustment record; -- invoice line adjustment

  invPatRespTotal numeric
  invPatCoverTotal numeric
  invInsRespTotal numeric
  invInsCoverTotal numeric
  patRespTotal numeric
  patCoverTotal numeric
  insRespTotal numeric
  insCoverTotal numeric
  invPatBal numeric
  invInsBal numeric
  tt numeric
  pat_id integer
  skip integer
  asOfDate DATE
  ilaDate DATE
BEGIN

  invPatRespTotal := 0
  invPatCoverTotal := 0
  invInsRespTotal := 0
  invInsCoverTotal := 0
  asOfDate := (SELECT date_of_posting FROM invoice WHERE id = inv_id)
    -- For each invoice line of the given invoice id
    FOR inv_line IN (SELECT * from invoice_line where invoice_line.invoice_id = inv_id) LOOP

      patRespTotal := 0
      patCoverTotal := 0
      insRespTotal := 0
      insCoverTotal := 0
      IF inv_line.deleted IS NOT TRUE THEN
      
	      -- If the line is a reversal line then perform the opposite addition/subtraction
	      IF inv_line.reversal_of is null THEN
	        patRespTotal := patRespTotal + inv_line.patient_amount
	        insRespTotal := insRespTotal + inv_line.insurance_amount
	      ELSE
	        patRespTotal := patRespTotal - inv_line.patient_amount
	        insRespTotal := insRespTotal - inv_line.insurance_amount
		      END IF
	      -- for each adjustment of the invoice line
	      FOR inv_line_adjustment IN (SELECT * from invoice_line_adjustment where invoice_line_adjustment.source_invoice_line = inv_line.id) LOOP
	        
	        -- Update As Of Date
	        ilaDate := int_to_date(inv_line_adjustment.accounting_period)
	        IF ilaDate > asOfDate THEN asOfDate := ilaDate
	        END IF
	        -- Update Patient Resp Amount
	        IF inv_line_adjustment.patient_resp_action_type = 'POSITIVE' THEN
	          IF inv_line_adjustment.reversal_of > 0 THEN
	            patRespTotal:= (select contribute_balance(true, inv_line_adjustment.adjustment_amount, patRespTotal))
	          ELSE
	            patRespTotal:= (select contribute_balance(false, inv_line_adjustment.adjustment_amount, patRespTotal))
	          END IF
	        END IF
	        IF inv_line_adjustment.patient_resp_action_type = 'NEGATIVE' THEN
	          IF inv_line_adjustment.reversal_of > 0 THEN
	            patRespTotal:= (select contribute_balance(false, inv_line_adjustment.adjustment_amount, patRespTotal))
	          ELSE
	            patRespTotal:= (select contribute_balance(true, inv_line_adjustment.adjustment_amount, patRespTotal))
	          END IF
	        END IF
	        -- Update Patient Cover Amount
	        IF inv_line_adjustment.patient_cover_action_type = 'POSITIVE' THEN
	          IF inv_line_adjustment.reversal_of > 0 THEN
	            patCoverTotal:= (select contribute_balance(true, inv_line_adjustment.adjustment_amount, patCoverTotal))
	          ELSE
	            patCoverTotal:= (select contribute_balance(false, inv_line_adjustment.adjustment_amount, patCoverTotal))
	          END IF
	        END IF
	        IF inv_line_adjustment.patient_cover_action_type = 'NEGATIVE' THEN
	          IF inv_line_adjustment.reversal_of > 0 THEN
	            patCoverTotal:= (select contribute_balance(false, inv_line_adjustment.adjustment_amount, patCoverTotal))
	          ELSE
	            patCoverTotal:= (select contribute_balance(true, inv_line_adjustment.adjustment_amount, patCoverTotal))
	          END IF
	        END IF
	        -- Update Insurance Resp Amount
	        IF inv_line_adjustment.insurance_resp_action_type = 'POSITIVE' THEN
	          IF inv_line_adjustment.reversal_of > 0 THEN
	            insRespTotal:= (select contribute_balance(true, inv_line_adjustment.adjustment_amount, insRespTotal))
	          ELSE
	            insRespTotal:= (select contribute_balance(false, inv_line_adjustment.adjustment_amount, insRespTotal))
	          END IF
	        END IF
	        IF inv_line_adjustment.insurance_resp_action_type = 'NEGATIVE' THEN
	          IF inv_line_adjustment.reversal_of > 0 THEN
	            insRespTotal:= (select contribute_balance(false, inv_line_adjustment.adjustment_amount, insRespTotal))
	          ELSE
	            insRespTotal:= (select contribute_balance(true, inv_line_adjustment.adjustment_amount, insRespTotal))
	          END IF
	        END IF
	        -- Update Insurance Cover Amount
	        IF inv_line_adjustment.insurance_cover_action_type = 'POSITIVE' THEN
	          IF inv_line_adjustment.reversal_of > 0 THEN
	            insCoverTotal:= (select contribute_balance(true, inv_line_adjustment.adjustment_amount, insCoverTotal))
	          ELSE
	            insCoverTotal:= (select contribute_balance(false, inv_line_adjustment.adjustment_amount, insCoverTotal))
	          END IF
	        END IF
	        IF inv_line_adjustment.insurance_cover_action_type = 'NEGATIVE' THEN
	          IF inv_line_adjustment.reversal_of > 0 THEN
	            insCoverTotal:= (select contribute_balance(false, inv_line_adjustment.adjustment_amount, insCoverTotal))
	          ELSE
	            insCoverTotal:= (select contribute_balance(true, inv_line_adjustment.adjustment_amount, insCoverTotal))
	          END IF
	        END IF
	      END LOOP
      END IF
      -- Update inv totals
      invPatRespTotal := invPatRespTotal + patRespTotal
      invPatCoverTotal := invPatCoverTotal + patCoverTotal
      invInsRespTotal := invInsRespTotal + insRespTotal
      invInsCoverTotal := invInsCoverTotal + insCoverTotal
      update invoice_line set pat_current_balance = patRespTotal - patCoverTotal, ins_current_balance = insRespTotal - insCoverTotal where invoice_line.id = inv_line.id
    END LOOP
    invPatBal := invPatRespTotal - invPatCoverTotal
    invInsBal := invInsRespTotal - invInsCoverTotal
  --If the invoice in question is a reversal or reversed, mark it as resolved and zero balance
  skip := (select count(1) from invoice where id = inv_id and (reversal_of is not null or reversed_by is not null))
  IF skip = 1 THEN
    update invoice set resolved = true, pat_current_balance = 0, ins_current_balance = 0, pat_total_charges = invPatRespTotal, ins_total_charges = invInsRespTotal  where id = inv_id
  ELSE

    -- Update this invoice balances
    update invoice set pat_current_balance = invPatBal, ins_current_balance = invInsBal, pat_total_charges = invPatRespTotal, ins_total_charges = invInsRespTotal, as_of_Date = asOfDate  where invoice.id = inv_id
    tt := invPatBal + invInsBal
    IF tt = 0 THEN
      update invoice set resolved = true where id = inv_id
    ELSE
      update invoice set resolved = false where id = inv_id
    END IF
  END IF
  -- Update the patients totals
  pat_id:=(select patient_id from invoice where id = inv_id)
  return (select refresh_patient_balance(pat_id))
END
$_$
ALTER FUNCTION dbo.refresh_invoice_balance(inv integer) OWNER TO postgres
--
-- Name: refresh_patient_balance(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.refresh_patient_balance(p_id integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$

DECLARE
  pat_id alias for $1; -- the patient
  inv record; -- invoice line

  patcurtotal numeric
  inscurtotal numeric
BEGIN
  -- we need to look at the patients un resolved invoices, sum them up and update the cached value
  patcurtotal:=0
  inscurtotal:=0
  -- For each invoice line of the given invoice id
  FOR inv IN (SELECT * from invoice where patient_id = pat_id AND (deleted is null or deleted = false) AND resolved = false) LOOP
    patcurtotal :=patcurtotal + inv.pat_current_balance
    inscurtotal :=inscurtotal + inv.ins_current_balance
  END LOOP
  update patient set patient_balance = patcurtotal, insurance_balance = inscurtotal  where id = pat_id
  return patcurtotal
END
$_$
ALTER FUNCTION dbo.refresh_patient_balance(p_id integer) OWNER TO postgres
--
-- Name: refresh_prepayment_remaining(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.refresh_prepayment_remaining(pp_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$

DECLARE
  debt_id alias for $1; -- the user
  positive numeric
  negative numeric
  reversed BIT
BEGIN
  
  reversed:= (SELECT COUNT(*)>0 FROM prepayment AS revOf WHERE revOf.reversal_of = debt_id); -- if a reversal exists
  
  IF reversed 
  THEN
    update prepayment set remaining = 0 where prepayment_id = debt_id
  ELSE
    positive:= COALESCE( (select sum(adj.amount) from prepayment_adjustment as adj where adj.source_prepayment = debt_id and adj.reversal_of is null), 0)
    negative:= COALESCE( (select sum(adj.amount) from prepayment_adjustment as adj where adj.source_prepayment = debt_id and adj.reversal_of is not null), 0)
    update prepayment set remaining = (prepayment_amount -positive + negative) where prepayment_id = debt_id
  END if
  return 0; -- return a dummy integer because hibernate does not like void (see http://stackoverflow.com/questions/16883669/call-a-postgres-function-via-hibernate)
END
$_$
ALTER FUNCTION dbo.refresh_prepayment_remaining(pp_id integer) OWNER TO postgres
