--

CREATE FUNCTION dbo.remove_audit_log_triggers_from_single_table(s_table NVARCHAR(MAX)) RETURNS void
    LANGUAGE plpgsql
    AS $$ 
DECLARE
BEGIN
	EXECUTE 'DROP TRIGGER audit_trigger_row ON ' ||  quote_ident(s_table)
	EXECUTE 'DROP TRIGGER audit_trigger_stm ON ' || quote_ident(s_table)
EXCEPTION WHEN OTHERS THEN return
END
$$
ALTER FUNCTION dbo.remove_audit_log_triggers_from_single_table(s_table NVARCHAR(MAX)) OWNER TO postgres
