-- Name: remove_index_from_fkey(NVARCHAR(MAX), NVARCHAR(MAX)); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.remove_index_from_fkey(schema_name NVARCHAR(MAX), contraint NVARCHAR(MAX)) RETURNS void
    LANGUAGE plpgsql
    AS $_$DECLARE
    functor NVARCHAR(MAX)
BEGIN    
    FOR functor IN 
        select 
        'DROP INDEX ' || quote_ident(x.index_name) 
        from 
            (
                select
                    vfki.constraint_name,
                    vfki.schema_name,
                    vfki.table_name,
                    vfki.index_name,
                    pd_unnest(vfki.column_name_list) as column_name
                from    
                    view_foriegn_key_indexes as vfki
                where vfki.schema_name = $1 and vfki.constraint_name = $2
        ) as x
        group by x.constraint_name, x.schema_name, x.table_name, x.index_name having x.index_name is not null LOOP  
             EXECUTE functor
    END LOOP
END;$_$
ALTER FUNCTION dbo.remove_index_from_fkey(schema_name NVARCHAR(MAX), contraint NVARCHAR(MAX)) OWNER TO postgres
