-- Name: safe_number_cast(NVARCHAR(MAX)); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.safe_number_cast(p_input NVARCHAR(MAX)) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE v_value NUMERIC DEFAULT 0.00
BEGIN
    BEGIN
        v_value := nullif(trim(replace(p_input, ',', '')), '')
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Invalid numeric value: %.  Returning 0.00.', p_input
    END
RETURN v_value
END
$$
ALTER FUNCTION dbo.safe_number_cast(p_input NVARCHAR(MAX)) OWNER TO postgres
