CREATE FUNCTION dbo.safe_to_number(p_input NVARCHAR(MAX), p_mask NVARCHAR(MAX)) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE v_value NUMERIC DEFAULT 0.00
BEGIN
    BEGIN
        v_value := to_number(p_input, p_mask)
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Invalid numeric value: %.  Returning 0.00.', p_input
    END
RETURN v_value
END
$$
