--
-- Name: standarizeidentifier(integer, NVARCHAR(MAX), integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION dbo.standarizeidentifier(codeid integer, ident NVARCHAR(MAX), codetype integer) RETURNS void
    LANGUAGE plpgsql
    AS $_$

DECLARE

	retValue NVARCHAR(MAX)(30)
	nc BIT
	alt NVARCHAR(MAX)(30)
	i integer
	found integer
	prefixLength integer
	ICD9 integer := 0
	ICD10 integer := 1
BEGIN
	nc = null
	-- Normalize if ICD9
	IF $3 = ICD9 THEN
		retValue:= upper(regexp_replace($2, '\.', ''))
		IF regexp_replace(retValue, '[evEV0-9][\d]{2,4}'(MAX), 'X') <> 'X' THEN
			retValue:=$2
			nc := true
		END IF
	-- Normalize if ICD10
	ELSIF $3 = ICD10 THEN
		retValue:= upper(regexp_replace($2, '\.', ''))
		IF regexp_replace(retValue, '[a-zA-Z][\d]{2,6}'(MAX), 'X') <> 'X' THEN
			retValue:=$2
			nc := true
		END IF
	END IF
	i := 1
	alt := retValue
	LOOP
		--Search for records other than the one we are currently working on, and see if the identifier string is already taken
		found := (SELECT count(id) from diagnostic_code where diagnostic_code.identifier = alt and diagnostic_code.diagnostic_code_type = codeType and diagnostic_code.id != codeID)
		IF found > 0 THEN
			nc:=true
			prefixLength := length('('|| i || ')')
			-- We need to modifiy the code, but check if the modified length will be too long
			IF length(alt) + prefixLength > 30 THEN
				alt:= substr(retValue, 1, 30-prefixLength) || '(' || i || ')'
			ELSE
				alt:= retValue || '(' || i || ')'
			END IF
			i:=i+1
		ELSE
			EXIT
		END IF
	END LOOP
	if nc = true THEN
		UPDATE diagnostic_code SET active_inactive = false, identifier = alt, diagnostic_code_type = codeType, non_conforming=nc WHERE diagnostic_code.id = codeID
	ELSE
		UPDATE diagnostic_code SET  identifier = alt, diagnostic_code_type = codeType, non_conforming=nc WHERE diagnostic_code.id = codeID
	END IF
END
$_$
ALTER FUNCTION dbo.standarizeidentifier(codeid integer, ident NVARCHAR(MAX), codetype integer) OWNER TO postgres
