CREATE FUNCTION dbo.update_user_acl(resource_setting integer, auth_setting integer) RETURNS void
    LANGUAGE plpgsql
    AS $_$

DECLARE

  resource alias for $1
  auth alias for $2
  user_holder record
BEGIN
--   FOR account_holder IN select * from temporary_account_table LOOP

  FOR user_holder IN (select * from user) LOOP

    INSERT INTO acl_user_resource (id, user_id, acl_resource_id, auth_combination)
    VALUES (nextval('acl_user_resource_id_seq'), user_holder.id, resource, auth )
  END LOOP
END
$_$
ALTER FUNCTION dbo.update_user_acl(resource_setting integer, auth_setting integer) OWNER TO postgres
