CREATE TABLE audit.logged_action (
    id bigint NOT NULL,
    schema_name NVARCHAR(MAX) NOT NULL,
    table_name NVARCHAR(MAX) NOT NULL,
    practice_director_user_id integer,
    practice_director_patient_id integer,
    action_tstamp_tx timestamp with time zone NOT NULL,
    application_name NVARCHAR(MAX),
    client_query NVARCHAR(MAX) NOT NULL,
    action NVARCHAR(MAX) NOT NULL,
    row_data dbo.hstore,
    changed_fields dbo.hstore,
    statement_only BIT NOT NULL,
    prev_id bigint,
    row_hash_value VARBINARY(MAX),
    prev_row_hash_value VARBINARY(MAX),
    batch_id bigint,
    CONSTRAINT logged_action_action_check CHECK ((action = ANY (ARRAY['I'(MAX), 'D'(MAX), 'U'(MAX), 'T'(MAX), 'C'(MAX), 'Q'(MAX), 'P'(MAX)])))
);
