    occupation NVARCHAR(MAX)(60),
    government_no NVARCHAR(MAX)(30),
    guarantor integer,
    guarantor_type NVARCHAR(MAX)(30),
    signature_on_file_date date,
    source NVARCHAR(MAX)(30),
    suffix NVARCHAR(MAX)(5),
    sub_chart_no NVARCHAR(MAX)(30),
    use_signature_on_file BIT,
    has_bad_credit BIT,
    no_show_count integer DEFAULT 0 NOT NULL,
    picture_image_path NVARCHAR(MAX)(100),
    preferred_contact NVARCHAR(MAX)(30),
    outside_referral integer,
    family_doctor integer,
    patient_referral integer,
    sent_to_collection BIT,
    is_deceased BIT DEFAULT 0 NOT NULL,
    reason_for_visit NVARCHAR(MAX)(30),
    diagnosis_1 NVARCHAR(MAX)(10),
    diagnosis_2 NVARCHAR(MAX)(10),
    diagnosis_3 NVARCHAR(MAX)(10),
    diagnosis_4 NVARCHAR(MAX)(10),
    alerts NVARCHAR(MAX),
    version integer DEFAULT 0 NOT NULL,
    doctor_cancel_count integer,
    patient_cancel_count integer,
    first_referral NVARCHAR(MAX)(60),
    referral_count integer,
    is_no_recall BIT,
    is_offered_hippa_privacy BIT,
    is_offered_hippa_privacy_notes NVARCHAR(MAX)(500),
    non_patient_guarantor integer,
    hipaa_signed_date date,
    picture_image_id bigint,
    weight FLOAT,
    weight_unit NCHAR(1)(5),
    race_id integer,
    ethnicity_id integer,
    language_id integer,
    reconciliation_performed BIT DEFAULT 0 NOT NULL,
    transferred_in BIT DEFAULT 0 NOT NULL,
    known_problems BIT,
    known_medications BIT,
    known_allergies BIT,
    date_transferred_in date,
    transferred_out BIT DEFAULT 0 NOT NULL,
    date_transferred_out date,
    summary_of_care_provided BIT DEFAULT 0 NOT NULL,
    date_referred date,
    work_office_id integer,
    sms_enabled BIT DEFAULT 0,
    date_modified date,
    patient_acc_no NVARCHAR(MAX)(60),
    race_alternative NVARCHAR(MAX)(60),
    patient_identifier NVARCHAR(MAX)(30),
    assigning_authority NVARCHAR(MAX)(30),
    name_type_code NVARCHAR(MAX)(2),
    namespace_id NVARCHAR(MAX)(255),
    universal_id NVARCHAR(MAX)(255),
    setid_pid integer,
    family_relation_id integer,
    account_number NVARCHAR(MAX)(20),
    ssn_number NVARCHAR(MAX)(255),
    zipcode NVARCHAR(MAX)(15),
    patient_countycode integer,
    assigning_facility NVARCHAR(MAX)(255),
    prefix NVARCHAR(MAX)(10),
    other_desig NVARCHAR(MAX)(60),
    address_type NVARCHAR(MAX)(10),
    other_geographic_desig NVARCHAR(MAX)(60),
    patient_death_dateime DATETIME,
    patient_death_indicator NVARCHAR(MAX)(5),
    alternate_patient_identifier NVARCHAR(MAX),
    alternate_assigning_authority NVARCHAR(MAX),
    alternate_identification_type_code NVARCHAR(MAX),
    mothers_maiden_name integer,
    next_of_kin_name integer,
    next_of_kin_phone integer,
    next_of_kin_address integer,
    next_of_kin_relationship integer,
    publicity_setting integer,
    status_setting integer,
    date_of_death date,
    protection_setting BIT,
    publicity_setting_date date,
    protection_setting_date date,
    status_setting_date date,
    multiple_birth BIT,
    multiple_birth_order integer,
    portal_user_name NVARCHAR(MAX)(255),
    date_last_submitted_aoa date,
    gender_identity_id integer,
    sexual_orientation_id integer,
    sexual_orientation_description_id integer,
    gender_identity_description_id integer,
    alternate_ethnicity_id integer,
    alternate_race_id integer,
    insurance_balance numeric(11,2) DEFAULT 0,
    patient_balance numeric(11,2) DEFAULT 0,
    office_contact_id integer,
    medications_reviewed BIT DEFAULT 0 NOT NULL,
    CONSTRAINT cannot_have_two_guarantors_check CHECK ((NOT ((guarantor IS NOT NULL) AND (non_patient_guarantor IS NOT NULL)))),
    CONSTRAINT no_self_refrencing_guarantors_check CHECK ((id <> guarantor))
);
