--
-- Name: pqri_function_names; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.pqri_function_names AS
 SELECT (routine_catalog)(MAX) AS routine_catalog,
    (routine_schema)(MAX) AS routine_schema,
    (routine_name)(MAX) AS routine_name
   FROM information_schema.routines routines
  WHERE (((routine_name)(MAX) ~~ 'nqf_%'(MAX)) AND ((data_type)(MAX) = 'USER-DEFINED'(MAX)) AND ((type_udt_catalog)(MAX) = (specific_catalog)(MAX)) AND ((type_udt_schema)(MAX) = 'public'(MAX)) AND ((type_udt_name)(MAX) = 'pqri_measure'(MAX)) AND (( SELECT count(*) AS count
           FROM information_schema.parameters params
          WHERE (((params.specific_catalog)(MAX) = (routines.specific_catalog)(MAX)) AND ((params.specific_schema)(MAX) = (routines.specific_schema)(MAX)) AND ((params.specific_name)(MAX) = (routines.specific_name)(MAX)))) = 5) AND (( SELECT count(*) AS count
           FROM information_schema.parameters params
          WHERE (((params.specific_catalog)(MAX) = (routines.specific_catalog)(MAX)) AND ((params.specific_schema)(MAX) = (routines.specific_schema)(MAX)) AND ((params.specific_name)(MAX) = (routines.specific_name)(MAX)) AND ((((params.data_type)(MAX) = 'date'(MAX)) AND ((params.ordinal_position)= 1)) OR (((params.data_type)(MAX) = 'date'(MAX)) AND ((params.ordinal_position)= 2)) OR (((params.data_type)(MAX) = 'ARRAY'(MAX)) AND ((params.ordinal_position)= 3) AND ((params.udt_name)(MAX) = '_text'(MAX))) OR (((params.data_type)(MAX) = 'integer'(MAX)) AND ((params.ordinal_position)= 4)) OR (((params.data_type)(MAX) = 'integer'(MAX)) AND ((params.ordinal_position)= 5))))) = 5))
  ORDER BY ((routine_catalog)(MAX)), ((routine_schema)(MAX)), ((routine_name)(MAX))
ALTER VIEW dbo.pqri_function_names OWNER TO postgres
