--
-- Name: v_patient_exams; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_patient_exams AS
 SELECT p.id AS patient_id,
    e.exam_date_of_service AS exam_date,
    e.doctor_provider_id AS exam_provider,
    date_part('years'(MAX), age((e.exam_date_of_service), (p.date_of_birth))) AS patient_age_at_exam,
    date_part('years'(MAX), age(GETDATE(), (p.date_of_birth))) AS patient_age_now,
    e.id AS exam_id,
    p.active_patient,
    p.transferred_in,
    p.date_transferred_in,
    p.transferred_out,
    p.date_transferred_out,
    p.reconciliation_performed,
    p.summary_of_care_provided,
    p.date_of_birth,
    p.gender,
    p.race_id,
    p.ethnicity_id,
    p.language_id,
    p.known_problems,
    p.known_medications,
    p.known_allergies,
    p.portal_user_name,
    wo.tax_id_number AS office_tin
   FROM ((dbo.patient p
     JOIN dbo.exam e ON ((p.id = e.patient_id)))
     JOIN dbo.work_office wo ON ((e.work_office_id = wo.id)))
  WHERE ((e.exam_status)(MAX) = ANY (ARRAY[('Invoiced'(MAX))(MAX), ('Complete-NonBill'(MAX))(MAX), ('Completed'(MAX))(MAX)]))
ALTER VIEW dbo.v_patient_exams OWNER TO postgres
