--
-- Name: v_patient_exams_565; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_patient_exams_565 AS
 SELECT patient_id,
    exam_date,
    exam_provider,
    patient_age_at_exam,
    patient_age_now,
    exam_id,
    active_patient,
    transferred_in,
    date_transferred_in,
    transferred_out,
    date_transferred_out,
    reconciliation_performed,
    summary_of_care_provided,
    date_of_birth,
    gender,
    race_id,
    ethnicity_id,
    language_id
   FROM dbo.v_patient_exams
  WHERE ((NOT ((patient_age_now >= (6)) AND (patient_age_now <= (64)))) AND active_patient)
