--
-- Name: v_patient_lab_orders; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_patient_lab_orders AS
 SELECT p.id AS patient_id,
    p.provider_id,
    lo.id AS lo_id,
    lo.order_date,
    lo.active AS lo_active,
    lo.loinc_id AS lo_loinc_id
   FROM (dbo.patient p
     JOIN dbo.lab_order lo ON ((p.id = lo.patient_id)))
ALTER VIEW dbo.v_patient_lab_orders OWNER TO postgres
--
-- Name: v_patient_lab_results; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_patient_lab_results AS
 SELECT vplo.patient_id,
    vplo.provider_id,
    vplo.lo_id,
    vplo.order_date,
    vplo.lo_active,
    lc.loinc_code
   FROM (((dbo.v_patient_lab_orders vplo
     JOIN dbo.loinc_code lc ON ((vplo.lo_loinc_id = lc.id)))
     JOIN dbo.lab_test_report ltrep USING (patient_id))
     JOIN dbo.lab_test_result ltres ON ((ltrep.id = ltres.lab_test_report_id)))
  WHERE (((lc.loinc_code)(MAX) = (ltres.loinc_code)(MAX)) AND (date_trunc('day'(MAX), vplo.order_date) = date_trunc('day'(MAX), (ltrep.requested_date))))
ALTER VIEW dbo.v_patient_lab_results OWNER TO postgres
