    vpei.image_date
   FROM (dbo.v_patient_radiology_orders vpro
     JOIN dbo.v_patient_exam_images vpei ON (((date_trunc('day'(MAX), vpro.order_date) = date_trunc('day'(MAX), (vpei.exam_date))) AND (vpro.patient_id = vpei.patient_id) AND (vpro.provider_id = vpei.exam_provider))))
ALTER VIEW dbo.v_patient_radiology_images OWNER TO postgres
--
-- Name: v_patient_recalls; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_patient_recalls AS
 SELECT vpe.patient_id,
    vpe.exam_provider,
    vpe.active_patient,
    r.id AS recall_id,
    r.date_of_recall AS recall_date,
    r.doctor_provider_id AS recall_provider,
    r.active AS recall_active
   FROM ((dbo.v_patient_exams vpe
     JOIN dbo.recall r USING (patient_id))
     JOIN dbo.recall_reason rr ON ((rr.id = r.recall_reason_id)))
  WHERE (rr.is_preventative AND ((r.doctor_provider_id IS NULL) OR (r.doctor_provider_id = vpe.exam_provider)))
ALTER VIEW dbo.v_patient_recalls OWNER TO postgres
--
-- Name: v_patient_recalls_565; Type: VIEW; Schema: public; Owner: postgres
