    r.active AS recall_active
   FROM ((dbo.v_patient_exams_565 vpe
     JOIN dbo.recall r USING (patient_id))
     JOIN dbo.recall_reason rr ON ((rr.id = r.recall_reason_id)))
  WHERE (rr.is_preventative AND ((r.doctor_provider_id IS NULL) OR (r.doctor_provider_id = vpe.exam_provider)))
