--
-- Name: v_rcopia_prescription_error_exam_date; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_rcopia_prescription_error_exam_date AS
 SELECT max(e.exam_date_of_service) AS exam_date,
    rpe.rcopia_id
   FROM (dbo.exam e
     JOIN dbo.rcopia_prescription_error rpe USING (patient_id))
  WHERE ((rpe.last_modified_date >= e.exam_date_of_service) AND ((e.exam_status)(MAX) = ANY (ARRAY[('Invoiced'(MAX))(MAX), ('Complete-NonBill'(MAX))(MAX), ('Completed'(MAX))(MAX)])) AND (rpe.pd_verified IS TRUE))
  GROUP BY rpe.rcopia_id
ALTER VIEW dbo.v_rcopia_prescription_error_exam_date OWNER TO postgres
--
-- Name: v_rcopia_nonscheduled_error_exam; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_rcopia_nonscheduled_error_exam AS
 SELECT rpe.rcopia_id,
    rpe.last_modified_date,
    rpe.completion_action,
    vpe.patient_id,
    vpe.exam_date,
    vpe.exam_provider
   FROM (((dbo.rcopia_prescription_error rpe
     JOIN dbo.v_patient_exams vpe USING (patient_id))
     JOIN dbo.rcopia_drug_error rde ON ((rpe.sig_drug_id = rde.id)))
     JOIN dbo.v_rcopia_prescription_error_exam_date vrpeed ON (((vpe.exam_date = vrpeed.exam_date) AND (rpe.rcopia_id = vrpeed.rcopia_id))))
  WHERE ((btrim(lower(rde.schedule)) = 'nonscheduled'(MAX)) AND (NOT rpe.deleted) AND (rpe.pd_verified IS TRUE))
ALTER VIEW dbo.v_rcopia_nonscheduled_error_exam OWNER TO postgres
