-- Name: v_rcopia_prescription_exam_date; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_rcopia_prescription_exam_date AS
 SELECT max(e.exam_date_of_service) AS exam_date,
    rp.rcopia_id
   FROM (dbo.exam e
     JOIN dbo.rcopia_prescription rp USING (patient_id))
  WHERE ((rp.last_modified_date >= e.exam_date_of_service) AND ((e.exam_status)(MAX) = ANY (ARRAY[('Invoiced'(MAX))(MAX), ('Complete-NonBill'(MAX))(MAX), ('Completed'(MAX))(MAX)])))
  GROUP BY rp.rcopia_id
ALTER VIEW dbo.v_rcopia_prescription_exam_date OWNER TO postgres
--
-- Name: v_rcopia_nonscheduled_exam; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_rcopia_nonscheduled_exam AS
 SELECT rp.rcopia_id,
    rp.last_modified_date,
    rp.completion_action,
    vpe.patient_id,
    vpe.exam_date,
    vpe.exam_provider
   FROM (((dbo.rcopia_prescription rp
     JOIN dbo.v_patient_exams vpe USING (patient_id))
     JOIN dbo.rcopia_drug rd ON ((rp.sig_drug_id = rd.id)))
     JOIN dbo.v_rcopia_prescription_exam_date vrped ON (((vpe.exam_date = vrped.exam_date) AND (rp.rcopia_id = vrped.rcopia_id))))
  WHERE ((btrim(lower(rd.schedule)) = 'nonscheduled'(MAX)) AND (NOT rp.deleted))
ALTER VIEW dbo.v_rcopia_nonscheduled_exam OWNER TO postgres
--
-- Name: v_rcopia_nonscheduled_provider; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_rcopia_nonscheduled_provider AS
 SELECT rp.rcopia_id,
    rp.patient_id,
    rp.completed_date,
    rp.completion_action,
    u.doctor_provider_id AS rx_provider
   FROM ((dbo.rcopia_prescription rp
     JOIN dbo.user u ON ((btrim(rp.provider_id) = btrim((u.rcopia_username)(MAX)))))
     JOIN dbo.rcopia_drug rd ON ((rp.sig_drug_id = rd.id)))
  WHERE ((btrim(lower(rd.schedule)) = 'nonscheduled'(MAX)) AND (NOT rp.deleted) AND (rp.patient_id IS NOT NULL))
ALTER VIEW dbo.v_rcopia_nonscheduled_provider OWNER TO postgres
--
-- Name: v_rcopia_nonscheduled_provider_exam; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.v_rcopia_nonscheduled_provider_exam AS
 SELECT rp.rcopia_id,
    rp.patient_id,
    rp.completed_date,
    rp.completion_action,
    u.doctor_provider_id AS rx_provider,
    vpe.office_tin
   FROM (((dbo.rcopia_prescription rp
     JOIN dbo.user u ON ((btrim(rp.provider_id) = btrim((u.rcopia_username)(MAX)))))
     JOIN dbo.rcopia_drug rd ON ((rp.sig_drug_id = rd.id)))
     JOIN dbo.v_patient_exams vpe USING (patient_id))
  WHERE ((btrim(lower(rd.schedule)) = 'nonscheduled'(MAX)) AND (NOT rp.deleted) AND (rp.patient_id IS NOT NULL) AND (vpe.exam_provider = u.doctor_provider_id) AND (date_trunc('day'(MAX), (vpe.exam_date)) = date_trunc('day'(MAX), rp.completed_date)))
ALTER VIEW dbo.v_rcopia_nonscheduled_provider_exam OWNER TO postgres
--
-- Name: v_referral_documents_received; Type: VIEW; Schema: public; Owner: postgres
