CREATE VIEW dbo.v_referral_documents_received AS
 SELECT rd.id AS referral_id,
    rd.type AS referral_type,
    rd.created_date AS incorporated_date,
    socr.id AS received_id,
    socr.patient_id,
    socr.doctor_provider_id AS received_provider,
    wo.tax_id_number AS received_office_tin,
    socr.in_processed_date AS patient_in_date,
    socr.summary_of_care_requested_date AS requested_date,
    socr.summary_of_care_available AS available,
    socr.summary_of_care_received_date AS received_date,
    socr.medications_reconciled,
    socr.medication_allergies_reconciled AS allergies_reconciled,
    socr.problems_reconciled,
    socr.reconciliation_date
   FROM ((dbo.summary_of_care_received socr
     JOIN dbo.work_office wo ON ((socr.work_office_id = wo.id)))
     LEFT JOIN dbo.referral_document rd ON ((socr.referral_document_id = rd.id)))
ALTER VIEW dbo.v_referral_documents_received OWNER TO postgres
