--
-- Name: view_claim_line_balance; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.view_claim_line_balance AS
 SELECT cl.claim_id,
    cl.id AS claim_line_id,
    totals.totals_invoice_line_id AS invoice_line_id,
    sum(totals.invoice_line_amount) AS balance_owing
   FROM ( SELECT invoice_line.id AS totals_invoice_line_id,
            invoice_line.insurance_amount AS invoice_line_amount
           FROM dbo.invoice_line
        UNION ALL
         SELECT pa.invoice_line_id AS totals_invoice_line_id,
            ((- (1)) * pa.amount) AS invoice_line_amount
           FROM dbo.payment_allocation pa,
            dbo.payment py
          WHERE ((py.payment_type_id = 2) AND (pa.payment_set_id = py.payment_set_id))
        UNION ALL
         SELECT ret.invoice_line_id AS totals_invoice_line_id,
            ((- (1)) * ret.return_insurance_amount) AS invoice_line_amount
           FROM dbo.product_return_line ret
        UNION ALL
         SELECT adj.invoice_line_id AS totals_invoice_line_id,
            adj.adjustment_amount AS invoice_line_amount
           FROM dbo.adjustment adj,
            dbo.adjustment_reason ar,
            dbo.adjustment_type at
          WHERE ((adj.adjustment_reason_id = ar.id) AND (ar.adjustment_type_id = at.id) AND (((at.code)(MAX) = 'IRL'(MAX)) OR ((at.code)(MAX) = 'INS'(MAX)) OR ((at.code)(MAX) = 'IWO'(MAX)) OR ((at.code)(MAX) = 'WOI'(MAX))))) totals,
    dbo.claim_line cl
  WHERE ((totals.totals_invoice_line_id = cl.invoice_line_id) AND (cl.insurance_charge > (0)))
  GROUP BY cl.claim_id, cl.id, totals.totals_invoice_line_id
UNION ALL
 SELECT cl.claim_id,
    cl.id AS claim_line_id,
    cl.invoice_line_id,
    cl.insurance_charge AS balance_owing
   FROM dbo.claim_line cl
  WHERE (cl.insurance_charge = (0))
ALTER VIEW dbo.view_claim_line_balance OWNER TO postgres
--
-- Name: view_claim_balance; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.view_claim_balance AS
 SELECT claim_id,
    sum(balance_owing) AS balance_owing
   FROM dbo.view_claim_line_balance
  GROUP BY claim_id
  ORDER BY claim_id
ALTER VIEW dbo.view_claim_balance OWNER TO postgres
--
-- Name: view_credits_refunds_voids; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.view_credits_refunds_voids AS
 SELECT ('Credit: '(MAX) || (py.id)(MAX)) AS reference,
    py.date_of_payment AS date,
    py.patient_id,
    py.work_office_id,
    NULL,
    (- py.amount) AS patient_amount,
    (0).payment py
  WHERE ((py.payment_type_id = 3) AND (py.payment_set_id IS NULL))
UNION ALL
 SELECT ('Ins Credit: '(MAX) || (py.id)(MAX)) AS reference,
    py.date_of_payment AS date,
    py.patient_id,
    py.work_office_id,
    py.insurance_provider_id AS insurance_id,
    (0),
    (- py.amount) AS insurance_amount
   FROM dbo.payment py
  WHERE ((py.payment_type_id = 4) AND (py.payment_set_id IS NULL))
UNION ALL
 SELECT ('Refund: '(MAX) || (py.id)(MAX)) AS reference,
    py.date_of_payment AS date,
    py.patient_id,
    py.work_office_id,
    NULL,
    py.amount AS patient_amount,
    (0).payment py
  WHERE ((py.payment_type_id = 5) AND (py.payment_method <> 3))
UNION ALL
 SELECT ('Ins Refund: '(MAX) || (ra.id)(MAX)) AS reference,
    ra.create_date AS date,
    ra.patient_id,
    ra.work_office_id,
    ra.insurance_provider_id AS insurance_id,
    (0)(11,2) AS patient_amount,
    ra.refund_amount AS insurance_amount
   FROM dbo.refund_allocation ra
  WHERE ((ra.insurance_provider_id IS NOT NULL) AND (ra.payment_set_id IS NOT NULL))
UNION ALL
 SELECT ('Void: '(MAX) || (ra.id)(MAX)) AS reference,
    ra.create_date AS date,
    ra.patient_id,
    ra.work_office_id,
    NULL,
    ra.void_amount AS patient_amount,
    (0).refund_allocation ra
  WHERE ((ra.void_amount > (0)) AND (ra.insurance_provider_id IS NULL) AND (ra.payment_set_id IS NOT NULL))
UNION ALL
 SELECT ('Ins Void: '(MAX) || (ra.id)(MAX)) AS reference,
    ra.create_date AS date,
    ra.patient_id,
    ra.work_office_id,
    ra.insurance_provider_id AS insurance_id,
    (0),
    ra.void_amount AS insurance_amount
   FROM dbo.refund_allocation ra
  WHERE ((ra.void_amount > (0)) AND (ra.insurance_provider_id IS NOT NULL) AND (ra.payment_set_id IS NOT NULL))
ALTER VIEW dbo.view_credits_refunds_voids OWNER TO postgres
