--
-- Name: view_invoice_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.view_invoice_summary AS
 SELECT patient_id,
    invoice_id,
    insurance_id,
    sum(patient_amount) AS patient_amount,
    sum(insurance_amount) AS insurance_amount
   FROM ( SELECT 'Invoice: '(MAX) AS reference,
            inv.patient_id,
            inv.id AS invoice_id,
            insprov.id AS insurance_id,
            (((il.patient_amount - il.discount_amount) + il.tax_1_amount) + il.tax_2_amount) AS patient_amount,
            il.insurance_amount
           FROM dbo.invoice inv,
            (((dbo.invoice_line il
             LEFT JOIN dbo.patient_insurance_plan pinsplan ON ((il.primary_insurance = pinsplan.id)))
             LEFT JOIN dbo.insurance_plan insplan ON ((pinsplan.insurance_plan_id = insplan.id)))
             LEFT JOIN dbo.insurance_provider insprov ON ((insplan.insurance_prov_id = insprov.id)))
          WHERE ((inv.id = il.invoice_id) AND ((inv.deleted IS NULL) OR (inv.deleted = false)) AND ((il.deleted IS NULL) OR (il.deleted = false)))
        UNION ALL
         SELECT 'Invoice Savings '(MAX) AS reference,
            inv.patient_id,
            inv.id,
            NULL,
            (- inv.discount_amount) AS patient_amount,
            (0).invoice inv
          WHERE (((inv.deleted IS NULL) OR (inv.deleted = false)) AND (inv.discount_amount IS NOT NULL) AND (inv.discount_amount > (0)))
        UNION ALL
        ( SELECT DISTINCT ('Payment Allocation: '(MAX) || (pa.id)(MAX)) AS reference,
            pa.patient_id,
            inv.id,
            NULL,
            (- pa.amount) AS patient_amount,
            (0).payment_allocation pa,
            dbo.payment py,
            dbo.invoice inv
          WHERE ((pa.payment_set_id = py.payment_set_id) AND ((py.payment_type_id = 1) OR (py.payment_type_id = 3)) AND (inv.id = pa.invoice_id))
          ORDER BY ('Payment Allocation: '(MAX) || (pa.id)(MAX)), pa.patient_id, inv.id, (- pa.amount), ((0)), NULL)
        UNION ALL
         SELECT 'Return: '(MAX) AS reference,
            pret.patient_id,
            il.invoice_id,
            insprov.id AS insurance_id,
            (- ((pline.return_patient_amount + pline.return_tax) - pline.return_savings)) AS patient_amount,
            (- pline.return_insurance_amount) AS insurance_amount
           FROM dbo.product_return_line pline,
            dbo.product_return pret,
            (((dbo.invoice_line il
             LEFT JOIN dbo.patient_insurance_plan pinsplan ON ((il.primary_insurance = pinsplan.id)))
             LEFT JOIN dbo.insurance_plan insplan ON ((pinsplan.insurance_plan_id = insplan.id)))
             LEFT JOIN dbo.insurance_provider insprov ON ((insplan.insurance_prov_id = insprov.id)))
          WHERE ((pline.return_id = pret.id) AND (pline.invoice_line_id = il.id))
        UNION ALL
         SELECT 'Patient Return Credit'(MAX) AS reference,
            p.patient_id,
            pr.invoice_id,
            NULL,
            p.amount AS patient_amount,
            (0).payment p,
            dbo.product_return pr
          WHERE ((p.credit_return_id = pr.id) AND (p.payment_type_id = 3))
        UNION ALL
         SELECT 'Insurance Return Credit'(MAX) AS reference,
            p.patient_id,
            pr.invoice_id,
            p.insurance_provider_id AS insurance_id,
            (0),
            p.amount AS insurance_amount
           FROM dbo.payment p,
            dbo.product_return pr
          WHERE ((p.credit_return_id = pr.id) AND (p.payment_type_id = 4))
        UNION ALL
         SELECT 'Ins: '(MAX) AS reference,
            c.patient_id,
            c.invoice_id,
            insprov.id AS insurance_id,
            (0),
            (- crl.amount_paid) AS insurance_amount
           FROM dbo.claim_line cl,
            dbo.claim_response cr,
            dbo.claim_response_line crl,
            (((dbo.claim c
             LEFT JOIN dbo.patient_insurance_plan pinsplan ON ((c.primary_insurance_plan = pinsplan.id)))
             LEFT JOIN dbo.insurance_plan insplan ON ((pinsplan.insurance_plan_id = insplan.id)))
             LEFT JOIN dbo.insurance_provider insprov ON ((insplan.insurance_prov_id = insprov.id)))
          WHERE ((c.id = cr.claim_id) AND (c.id = cl.claim_id) AND (crl.claim_line_id = cl.id) AND (crl.claim_response_id = cr.id))
        UNION ALL
         SELECT 'Patient Adjustment'(MAX) AS reference,
            a_1.patient_id,
            inv.id AS invoice_id,
            NULL,
            a_1.adjustment_amount AS patient_amount,
            (0).adjustment a_1,
            dbo.adjustment_reason ar,
            dbo.adjustment_type adt,
            dbo.invoice inv
          WHERE ((a_1.adjustment_reason_id = ar.id) AND (ar.adjustment_type_id = adt.id) AND (((adt.code)(MAX) = 'PAT'(MAX)) OR ((adt.code)(MAX) = 'PWO'(MAX))) AND (a_1.invoice_id = inv.id) AND ((inv.deleted = false) OR (inv.deleted IS NULL)))
        UNION ALL
         SELECT 'Ins Adjustment'(MAX) AS reference,
            a_1.patient_id,
            inv.id,
            a_1.insurance_provider_id,
            (0),
            a_1.adjustment_amount AS insurance_amount
           FROM dbo.adjustment a_1,
            dbo.adjustment_reason ar,
            dbo.adjustment_type adt,
            dbo.invoice inv
          WHERE ((a_1.adjustment_reason_id = ar.id) AND (ar.adjustment_type_id = adt.id) AND (((adt.code)(MAX) = 'IWO'(MAX)) OR ((adt.code)(MAX) = 'IRL'(MAX)) OR ((adt.code)(MAX) = 'INS'(MAX))) AND (a_1.invoice_id = inv.id) AND ((inv.deleted = false) OR (inv.deleted IS NULL)))) a
  GROUP BY patient_id, invoice_id, insurance_id
ALTER VIEW dbo.view_invoice_summary OWNER TO postgres
--
-- Name: view_ledger_detail; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.view_ledger_detail AS
 SELECT reference,
    date,
    patient_id,
    office_id,
    insurance_id,
    patientamount AS patient_amount,
    insuranceamount AS insurance_amount
   FROM ( SELECT ((((il.procedure_code)(MAX) || ' (Invoice: '(MAX)) || (inv.id)(MAX)) || ')'(MAX)) AS reference,
            inv.date_of_service AS date,
            inv.patient_id,
            inv.location_id AS office_id,
            insprov.id AS insurance_id,
            (((il.patient_amount - il.discount_amount) + il.tax_1_amount) + il.tax_2_amount) AS patientamount,
            il.insurance_amount AS insuranceamount
           FROM dbo.invoice inv,
            (((dbo.invoice_line il
             LEFT JOIN dbo.patient_insurance_plan pinsplan ON ((il.primary_insurance = pinsplan.id)))
             LEFT JOIN dbo.insurance_plan insplan ON ((pinsplan.insurance_plan_id = insplan.id)))
             LEFT JOIN dbo.insurance_provider insprov ON ((insplan.insurance_prov_id = insprov.id)))
          WHERE ((inv.id = il.invoice_id) AND ((inv.deleted IS NULL) OR (inv.deleted = false)) AND ((il.deleted IS NULL) OR (il.deleted = false)))
        UNION ALL
         SELECT ((('Invoice: '(MAX) || (inv.id)(MAX)) || ' Savings - '(MAX)) || (inv.discount_reason)(MAX)) AS reference,
            inv.date_of_service AS date,
            inv.patient_id,
            inv.location_id AS office_id,
            NULL,
            (- inv.discount_amount) AS patientamount,
            (0).invoice inv
          WHERE (((inv.deleted IS NULL) OR (inv.deleted = false)) AND (inv.discount_amount IS NOT NULL) AND (inv.discount_amount > (0)))
        UNION ALL
         SELECT ('Payment: '(MAX) || (py.id)(MAX)) AS reference,
            py.date_of_payment AS date,
            py.patient_id,
            py.work_office_id AS office_id,
            NULL,
            (- py.amount) AS patientamount,
            (0).payment py
          WHERE (((py.payment_type_id = 1) OR (py.payment_type_id = 3)) AND (py.payment_method IS NOT NULL) AND (py.parent_payment_set_id IS NULL) AND (py.amount > (0)))
        UNION ALL
        ( SELECT DISTINCT ('Guarantor Transfer: '(MAX) || (pa.id)(MAX)) AS reference,
            pa.date_of_payment_allocation AS date,
            pa.patient_id,
            py.work_office_id AS office_id,
            NULL,
            (- (pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0)))) AS patientamount,
            (0).payment_allocation pa,
            dbo.payment py
          WHERE ((pa.payment_set_id = py.payment_set_id) AND (pa.patient_id <> py.patient_id) AND ((py.payment_type_id = 1) OR (py.payment_type_id = 3)) AND ((pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0))) > (0)))
          ORDER BY ('Guarantor Transfer: '(MAX) || (pa.id)(MAX)), pa.date_of_payment_allocation, pa.patient_id, py.work_office_id, (- (pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0)))), ((0)), NULL)
        UNION ALL
        ( SELECT DISTINCT ('Guarantor Transfer: '(MAX) || (pa.id)(MAX)) AS reference,
            pa.date_of_payment_allocation AS date,
            py.patient_id,
            py.work_office_id AS office_id,
            NULL,
            (pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0))) AS patientamount,
            (0).payment_allocation pa,
            dbo.payment py
          WHERE ((pa.payment_set_id = py.payment_set_id) AND (pa.patient_id <> py.patient_id) AND ((py.payment_type_id = 1) OR (py.payment_type_id = 3)) AND ((pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0))) > (0)))
          ORDER BY ('Guarantor Transfer: '(MAX) || (pa.id)(MAX)), pa.date_of_payment_allocation, py.patient_id, py.work_office_id, (pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0))), ((0)), NULL)
        UNION ALL
         SELECT ('Return: '(MAX) || (pret.id)(MAX)) AS reference,
            pret.return_date AS date,
            pret.patient_id,
            pret.work_office_id AS office_id,
            insprov.id AS insurance_id,
            (- ((pline.return_patient_amount + pline.return_tax) - pline.return_savings)) AS patientamount,
            (- pline.return_insurance_amount) AS insuranceamount
           FROM dbo.product_return_line pline,
            dbo.product_return pret,
            (((dbo.invoice_line il
             LEFT JOIN dbo.patient_insurance_plan pinsplan ON ((il.primary_insurance = pinsplan.id)))
             LEFT JOIN dbo.insurance_plan insplan ON ((pinsplan.insurance_plan_id = insplan.id)))
             LEFT JOIN dbo.insurance_provider insprov ON ((insplan.insurance_prov_id = insprov.id)))
          WHERE ((pline.return_id = pret.id) AND (pline.invoice_line_id = il.id))
        UNION ALL
         SELECT ('Refund: '(MAX) || (py.id)(MAX)) AS reference,
            py.date_of_payment AS date,
            py.patient_id,
            py.work_office_id AS office_id,
            NULL,
            py.amount AS patientamount,
            (0).payment py
          WHERE ((py.payment_type_id = 5) AND (py.payment_method <> 3))
        UNION ALL
         SELECT ('Refund: '(MAX) || (ra.id)(MAX)) AS reference,
            ra.create_date AS date,
            ra.patient_id,
            ra.work_office_id AS office_id,
            ra.insurance_provider_id,
            (0),
            ra.refund_amount AS insuranceamount
           FROM dbo.refund_allocation ra
          WHERE ((ra.insurance_provider_id IS NOT NULL) AND (ra.payment_set_id IS NOT NULL))
        UNION ALL
         SELECT ('Void: '(MAX) || (ra.id)(MAX)) AS reference,
            ra.create_date AS date,
            ra.patient_id,
            ra.work_office_id AS office_id,
            NULL,
            ra.void_amount AS patientamount,
            (0).refund_allocation ra
          WHERE ((ra.void_amount > (0)) AND (ra.insurance_provider_id IS NULL) AND (ra.payment_set_id IS NOT NULL))
        UNION ALL
         SELECT ('Void: '(MAX) || (ra.id)(MAX)) AS reference,
            ra.create_date AS date,
            ra.patient_id,
            ra.work_office_id AS office_id,
            ra.insurance_provider_id,
            (0),
            ra.void_amount AS insuranceamount
           FROM dbo.refund_allocation ra
          WHERE ((ra.void_amount > (0)) AND (ra.insurance_provider_id IS NOT NULL) AND (ra.payment_set_id IS NOT NULL))
        UNION ALL
         SELECT ('Ins: '(MAX) || (cl.procedure_code)(MAX)) AS reference,
            cr.claim_response_date AS date,
            c.patient_id,
            c.work_office_id AS office_id,
            insprov.id AS insurance_id,
            (0),
            (- crl.amount_paid) AS insuranceamount
           FROM dbo.claim_line cl,
            dbo.claim_response cr,
            dbo.claim_response_line crl,
            (((dbo.claim c
             LEFT JOIN dbo.patient_insurance_plan pinsplan ON ((c.primary_insurance_plan = pinsplan.id)))
             LEFT JOIN dbo.insurance_plan insplan ON ((pinsplan.insurance_plan_id = insplan.id)))
             LEFT JOIN dbo.insurance_provider insprov ON ((insplan.insurance_prov_id = insprov.id)))
          WHERE ((c.id = cr.claim_id) AND (c.id = cl.claim_id) AND (crl.claim_line_id = cl.id) AND (crl.claim_response_id = cr.id))
        UNION ALL
         SELECT ((((ar.reason_code)(MAX) || ' ('(MAX)) || (a_1.id)(MAX)) || ')'(MAX)) AS reference,
            (a_1.date_adjusted),
            a_1.patient_id,
            inv.location_id AS office_id,
            NULL,
            a_1.adjustment_amount AS patientamount,
            (0).adjustment a_1,
            dbo.adjustment_reason ar,
            dbo.adjustment_type adt,
            dbo.invoice inv
          WHERE ((a_1.adjustment_reason_id = ar.id) AND (ar.adjustment_type_id = adt.id) AND (((adt.code)(MAX) = 'PAT'(MAX)) OR ((adt.code)(MAX) = 'PWO'(MAX))) AND (a_1.invoice_id = inv.id) AND ((inv.deleted = false) OR (inv.deleted IS NULL)))
        UNION ALL
         SELECT ((((ar.reason_code)(MAX) || ' ('(MAX)) || (a_1.id)(MAX)) || ')'(MAX)) AS reference,
            (a_1.date_adjusted),
            a_1.patient_id,
            inv.location_id AS office_id,
            a_1.insurance_provider_id,
            (0),
            a_1.adjustment_amount AS insuranceamount
           FROM dbo.adjustment a_1,
            dbo.adjustment_reason ar,
            dbo.adjustment_type adt,
            dbo.invoice inv
          WHERE ((a_1.adjustment_reason_id = ar.id) AND (ar.adjustment_type_id = adt.id) AND (((adt.code)(MAX) = 'IWO'(MAX)) OR ((adt.code)(MAX) = 'IRL'(MAX)) OR ((adt.code)(MAX) = 'INS'(MAX))) AND (a_1.invoice_id = inv.id) AND ((inv.deleted = false) OR (inv.deleted IS NULL)))) a
ALTER VIEW dbo.view_ledger_detail OWNER TO postgres
--
-- Name: view_ledger_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW dbo.view_ledger_summary AS
 SELECT reference,
    date,
    patient_id,
    office_id,
    patientamount AS patient_amount,
    insuranceamount AS insurance_amount
   FROM ( SELECT ('Invoice: '(MAX) || (inv.id)(MAX)) AS reference,
            inv.date_of_service AS date,
            inv.patient_id,
            inv.location_id AS office_id,
            inv.pat_total_charges AS patientamount,
            inv.ins_total_charges AS insuranceamount
           FROM dbo.invoice inv
          WHERE ((inv.deleted IS NULL) OR (inv.deleted = false))
        UNION ALL
         SELECT ('Payment: '(MAX) || (py.id)(MAX)) AS reference,
            py.date_of_payment AS date,
            py.patient_id,
            py.work_office_id AS office_id,
            (- py.amount) AS patientamount,
            (0).payment py
          WHERE (((py.payment_type_id = 1) OR (py.payment_type_id = 3)) AND (py.payment_method IS NOT NULL) AND (py.parent_payment_set_id IS NULL) AND (py.amount > (0)))
        UNION ALL
        ( SELECT DISTINCT ('Guarantor Transfer: '(MAX) || (pa.id)(MAX)) AS reference,
            pa.date_of_payment_allocation AS date,
            pa.patient_id,
            py.work_office_id AS office_id,
            (- (pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0)))) AS patientbalance,
            (0).payment_allocation pa,
            dbo.payment py
          WHERE ((pa.payment_set_id = py.payment_set_id) AND (pa.patient_id <> py.patient_id) AND ((py.payment_type_id = 1) OR (py.payment_type_id = 3)) AND ((pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0))) > (0)))
          ORDER BY ('Guarantor Transfer: '(MAX) || (pa.id)(MAX)), pa.date_of_payment_allocation, pa.patient_id, py.work_office_id, (- (pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0)))), ((0)))
        UNION ALL
        ( SELECT DISTINCT ('Guarantor Transfer: '(MAX) || (pa.id)(MAX)) AS reference,
            pa.date_of_payment_allocation AS date,
            py.patient_id,
            py.work_office_id AS office_id,
            (pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0))) AS patientamount,
            (0).payment_allocation pa,
            dbo.payment py
          WHERE ((pa.payment_set_id = py.payment_set_id) AND (pa.patient_id <> py.patient_id) AND ((py.payment_type_id = 1) OR (py.payment_type_id = 3)) AND ((pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0))) > (0)))
          ORDER BY ('Guarantor Transfer: '(MAX) || (pa.id)(MAX)), pa.date_of_payment_allocation, py.patient_id, py.work_office_id, (pa.amount - COALESCE(( SELECT sum(py2.amount) AS sum
                   FROM dbo.payment py2
                  WHERE ((py2.payment_set_id = pa.payment_set_id) AND (py2.patient_id = pa.patient_id) AND ((py2.payment_type_id = 1) OR (py2.payment_type_id = 3)))), (0))), ((0)))
        UNION ALL
         SELECT ('Return: '(MAX) || (pret.id)(MAX)) AS reference,
            pret.return_date AS date,
            pret.patient_id,
            pret.work_office_id AS office_id,
            (- ((pline.return_patient_amount + pline.return_tax) - pline.return_savings)) AS patientamount,
            (- pline.return_insurance_amount) AS insuranceamount
           FROM dbo.product_return_line pline,
            dbo.product_return pret
          WHERE (pline.return_id = pret.id)
        UNION ALL
         SELECT ('Refund: '(MAX) || (py.id)(MAX)) AS reference,
            py.date_of_payment AS date,
            py.patient_id,
            py.work_office_id AS office_id,
            py.amount AS patientamount,
            (0).payment py
          WHERE ((py.payment_type_id = 5) AND (py.payment_method <> 3))
        UNION ALL
         SELECT ('Refund: '(MAX) || (ra.id)(MAX)) AS reference,
            ra.create_date AS date,
            ra.patient_id,
            ra.work_office_id AS office_id,
            (0),
            ra.refund_amount AS insuranceamount
           FROM dbo.refund_allocation ra
          WHERE ((ra.insurance_provider_id IS NOT NULL) AND (ra.payment_set_id IS NOT NULL))
        UNION ALL
         SELECT ('Void: '(MAX) || (ra.id)(MAX)) AS reference,
            ra.create_date AS date,
            ra.patient_id,
            ra.work_office_id AS office_id,
            ra.void_amount AS patientamount,
            (0).refund_allocation ra
          WHERE ((ra.void_amount > (0)) AND (ra.insurance_provider_id IS NULL) AND (ra.payment_set_id IS NOT NULL))
        UNION ALL
         SELECT ('Void: '(MAX) || (ra.id)(MAX)) AS reference,
            ra.create_date AS date,
            ra.patient_id,
            ra.work_office_id AS office_id,
            (0),
            ra.void_amount AS insuranceamount
           FROM dbo.refund_allocation ra
          WHERE ((ra.void_amount > (0)) AND (ra.insurance_provider_id IS NOT NULL) AND (ra.payment_set_id IS NOT NULL))
        UNION ALL
         SELECT ('Ins Check: '(MAX) || (py.check_number)(MAX)) AS reference,
            py.date_of_payment AS date,
            pa.patient_id,
            py.work_office_id AS office_id,
            (0),
            (- pa.amount) AS insuranceamount
           FROM dbo.payment py,
            dbo.payment_allocation pa,
            dbo.payment_set ps
          WHERE ((py.insurance_provider_id IS NOT NULL) AND (py.payment_type_id = 2) AND (pa.payment_set_id = ps.id) AND (ps.id = py.payment_set_id))
        UNION ALL
         SELECT ((((ar.reason_code)(MAX) || ' ('(MAX)) || (a_1.id)(MAX)) || ')'(MAX)) AS reference,
            (a_1.date_adjusted),
            a_1.patient_id,
            inv.location_id AS office_id,
            a_1.adjustment_amount AS patientamount,
            (0).adjustment a_1,
            dbo.adjustment_reason ar,
            dbo.adjustment_type adt,
            dbo.invoice inv
          WHERE ((a_1.adjustment_reason_id = ar.id) AND (ar.adjustment_type_id = adt.id) AND (((adt.code)(MAX) = 'PAT'(MAX)) OR ((adt.code)(MAX) = 'PWO'(MAX))) AND (a_1.invoice_id = inv.id) AND ((inv.deleted = false) OR (inv.deleted IS NULL)))
        UNION ALL
         SELECT ((((ar.reason_code)(MAX) || ' ('(MAX)) || (a_1.id)(MAX)) || ')'(MAX)) AS reference,
            (a_1.date_adjusted),
            a_1.patient_id,
            inv.location_id AS office_id,
            (0),
            a_1.adjustment_amount AS insuranceamount
           FROM dbo.adjustment a_1,
            dbo.adjustment_reason ar,
            dbo.adjustment_type adt,
            dbo.invoice inv
          WHERE ((a_1.adjustment_reason_id = ar.id) AND (ar.adjustment_type_id = adt.id) AND (((adt.code)(MAX) = 'IWO'(MAX)) OR ((adt.code)(MAX) = 'IRL'(MAX)) OR ((adt.code)(MAX) = 'INS'(MAX))) AND (a_1.invoice_id = inv.id) AND ((inv.deleted = false) OR (inv.deleted IS NULL)))) a
